window.HB_TR["isaiah"]["ur"]=["1۔ یسعیاہ کے بیٹے اموز کا خواب، جو اس نے یہوداہ اور یروشلم کے بارے میں عوزیا، یوتھم، آہز، {اور} حزقیاہ کے زمانے میں دیکھا، جو یہوداہ کے بادشاہ تھے۔\n2. اے آسمانوں، سنو اور سنو، اے زمین، کیونکہ خداوند نے فرمایا، میں نے بچوں کو پروان چڑھایا اور پرورش کی، اور انہوں نے میرے خلاف بغاوت کی۔\n3۔ بیل اپنے مالک کو جانتا ہے، اور گدھا اپنے مالک کے پالنے کو: {لیکن} اسرائیل نہیں جانتا، میرے لوگ غور نہیں کرتے۔\n4. اے گناہ گار قوم، ایک قوم جو گناہوں سے بھری ہوئی ہے، بدکاروں کا بیج ہے، بگاڑنے والے بچے ہیں: انہوں نے خداوند کو چھوڑ دیا ہے، انہوں نے اسرائیل کے مقدس وجود کو غصہ دلایا ہے، وہ پیچھے چلے گئے ہیں۔ {لادن: ہیب۔ بھاری پن} {غائب...: عبرانی الگ تھلگ، یا، الگ تھلگ ہو چکا ہے}\n5. آپ کو مزید کیوں متاثر کیا جانا چاہیے؟ تم اور زیادہ بغاوت کرو گے: پورا سر بیمار ہے، اور پورا دل بے ہوش ہو جائے گا۔ {بغاوت...: عبرانی۔ بغاوت بڑھاؤ}\n6۔ پاؤں کے تلوے سے سر تک {اس میں کوئی مضبوطی نہیں}؛ {لیکن} زخم، چوٹیں، اور سڑنے والے زخم: انہیں بند نہیں کیا گیا، نہ باندھا گیا، نہ مرہم سے نرم کیا گیا۔ {مرہم: یا، تیل}\n7. تمہارا ملک ویران ہے، تمہارے شہر آگ میں جل رہے ہیں: تمہاری زمین، اجنبی تمہاری موجودگی میں اسے کھا جاتے ہیں، اور یہ ویران ہے، جیسے اجنبیوں نے اسے گرا دیا ہو۔ {الٹ دیا گیا...: عببرانی۔ تختہ الٹنا}\n8۔ اور صیہون کی بیٹی کو انگور کے باغ میں ایک جھونپڑی کے طور پر چھوڑ دیا گیا ہے، کھیرے کے باغ میں ایک رہائش گاہ کے طور پر، ایک محصور شہر کے طور پر۔\n9۔ جب تک کہ لشکروں کے رب نے ہمیں بہت چھوٹا سا باقیات نہ چھوڑا ہوتا، ہمیں سدوم کی طرح ہونا چاہیے تھا، {اور} ہمیں عمورہ کی طرح ہونا چاہیے تھا۔\n10۔ خداوند کا کلام سنو، اے سدوم کے حکمرانو؛ ہمارے خدا کے قانون کو سنو، اے عمورہ کے لوگو۔\n11. آپ کی قربانیوں کی کثرت میرے لیے کس مقصد کے لیے ہے؟ خداوند فرماتا ہے: میں مینڈوں کے جلانے والے قربانیوں اور کھائے ہوئے جانوروں کی چربی سے بھرا ہوا ہوں؛ اور میں بیلوں، بھیڑوں یا بکریوں کے خون سے خوش نہیں ہوتا۔ {وہ بکری بناتا ہے: عبوری۔ زبردست بکریاں ہیں}\n12۔ جب تم میرے سامنے آتے ہو، تو کس نے تمہارے ہاتھوں یہ مطالبہ کیا ہے، تاکہ میری عدالت میں قدم رکھو؟ {ظاہر ہونے کے لیے: عبرانی۔ دیکھنے کے لیے}\n13۔ مزید فضول نذرانے نہ لاؤ؛ دھوبتی میرے لیے ایک مکروہ چیز ہے؛ نئے چاند اور سبات، اجتماعات کی بلانے کو میں چھوڑ نہیں سکتا؛ {یہ} بدکاری ہے، حتیٰ کہ سنجیدہ ملاقات بھی۔ {بدکاری: یا، غم}\n14۔ تمہارے نئے چاند اور تمہارے مقرر کردہ دعوتیں میری روح سے نفرت کرتی ہیں: یہ میرے لیے پریشانی ہیں؛ میں ان کو برداشت کرنے سے ہچکچا رہا ہوں۔\n15۔ اور جب تم اپنے ہاتھ پھیلاؤ گے، میں اپنی آنکھیں تم سے چھپا لوں گا: ہاں، جب تم بہت دعائیں کرو گے، میں نہیں سنوں گا: تمہارے ہاتھ خون سے بھرے ہوئے ہیں۔ {make...: عبرانی۔ دعا کو ضرب دو} {خون: عبرانی۔ bloods}\n16۔ تمہیں دھوئے، تمہیں صاف کرے؛ اپنے اعمال کی برائی کو میری آنکھوں کے سامنے سے دور کر دو؛ برائی کرنا بند کرو؛\n17. اچھا کرنا سیکھیں؛ فیصلہ طلب کرو، مظلوموں کو راحت دو، یتیم کا فیصلہ کرو، بیوہ کے لیے دعا کرو۔ {ریلیف: یا، رائٹن}\n18۔ اب آؤ، اور ہم مل کر دلیل دیں، خداوند فرماتا ہے: اگرچہ تمہارے گناہ سرخ ہوں، وہ برف کی طرح سفید ہوں گے؛ اگرچہ وہ سرخ ہوں گے، لیکن اون کی طرح ہوں گے۔\n19۔ اگر تم رضا مند اور فرمانبردار ہو تو تم زمین کی بھلائی کھاؤ گے:\n20. لیکن اگر تم انکار کرو اور بغاوت کرو، تو تمہیں تلوار سے کھا لیا جائے گا: کیونکہ خداوند کے منہ نے کہا ہے۔\n21. وفادار شہر بدکار کیسے بن جاتا ہے! یہ فیصلے سے بھرپور تھا؛ اس میں راستبازی پیوست ہے؛ لیکن اب قاتل۔\n22۔ تیری چاندی بکواس ہو گئی، تیری شراب پانی میں ملی ہوئی:\n23. تمہارے شہزادے باغی اور چوروں کے ساتھی ہیں: ہر کوئی تحفے پسند کرتا ہے، اور انعامات کے پیچھے چلتا ہے: وہ یتیم کو فیصلہ نہیں کرتے، نہ ہی بیوہ کا مقصد ان کے پاس آتا ہے۔\n24۔ لہٰذا خداوند فرماتا ہے، لشکروں کا رب، اسرائیل کا طاقتور ہوا، آہ، میں اپنے دشمنوں کو کم کروں گا، اور اپنے دشمنوں کا بدلہ لوں گا:\n25۔ اور میں اپنا ہاتھ تم پر کروں گا، اور تمہارا فضلہ صاف کر دوں گا، اور تمہارا سارا ٹن لے لوں گا: {خالص: عبرانی۔ پاکیزگی کے مطابق}\n26۔ اور میں تمہارے ججوں کو پہلے کی طرح بحال کروں گا، اور تمہارے مشیروں کو ابتدا کی طرح بحال کروں گا: بعد میں تمہیں راستبازی کا شہر، وفادار شہر کہا جائے گا۔\n27۔ صیون کو فیصلے سے نجات ملے گی، اور اس کے تبدیل ہونے والے راستبازی سے۔ {اس کی...: یا، وہ جو اس کی واپسی کرتے ہیں}\n28۔ اور گناہگاروں اور گناہ گاروں کی تباہی ایک ساتھ ہو گی، اور جو خداوند کو چھوڑ دیں گے وہ ختم ہو جائیں گے۔ {تباہی: عبرانی۔ بریکنگ}\n29۔ کیونکہ وہ ان بلوط کے درختوں پر شرمندہ ہوں گے جن کی تم نے خواہش کی ہے، اور تم ان باغات کے لیے شرمندہ ہو جاؤ گے جو تم نے منتخب کیے ہیں۔\n30۔ کیونکہ تم بلوط کی طرح ہو گے جس کا پتا مرجھا جاتا ہے، اور ایک باغ کی طرح جس میں پانی نہیں۔\n31۔ اور طاقتور کھینچنے کی طرح ہوگا، اور اسے بنانے والا چنگاری کی طرح ہوگا، اور دونوں ایک ساتھ جلیں گے، اور کوئی انہیں بجھا نہیں سکے گا۔ {خالق...: یا، اور اس کا کام}","1۔ وہ کلام جو یسعیاہ ابن عاموز نے یہوداہ اور یروشلم کے بارے میں دیکھا۔\n2۔ اور آخری دنوں میں یہ ہوگا کہ خداوند کے گھر کا پہاڑ پہاڑوں کی چوٹی پر قائم ہو جائے گا، اور پہاڑوں سے بلند ہوگا؛ اور تمام قومیں اس کی طرف بہیں گی۔ {قائم: یا، تیار}\n3۔ اور بہت سے لوگ جائیں گے اور کہیں گے، آؤ اور ہم خداوند کے پہاڑ کی طرف چلو، یعقوب کے خدا کے گھر پر؛ اور وہ ہمیں اپنے راستے سکھائے گا، اور ہم اس کے راستے پر چلیں گے: کیونکہ صیہون سے شریعت اور یروشلم سے خداوند کا کلام نکلے گا۔\n4۔ اور وہ قوموں میں فیصلہ کرے گا، اور بہت سے لوگوں کو ڈانٹے گا: اور وہ اپنی تلواروں کو ہل میں ماریں گے، اور اپنے نیزے کو کانٹے دار میں تبدیل کریں گے: قوم قوم کے خلاف تلوار نہیں اٹھائے گی، اور نہ ہی وہ جنگ سیکھے گی۔ {تراشنے کے ہکس: یا، درانتی}\n5۔ اے یعقوب کے گھرانہ، آؤ اور خداوند کی روشنی میں چلیں۔\n6۔ اس لیے تم نے اپنے لوگوں کو یعقوب کے گھر کو چھوڑ دیا ہے، کیونکہ وہ مشرق سے دوبارہ آباد ہو چکے ہیں، اور فلسطینیوں کی طرح فالگو ہیں، اور وہ اجنبیوں کے بچوں میں خوش ہیں۔ {سے...: یا، اس سے بھی زیادہ} {براہ کرم...: یا، بھرمار سے بھرپور}\n7۔ ان کی زمین بھی چاندی اور سونے سے بھری ہوئی ہے، نہ ہی ان کے خزانے کا کوئی اختتام ہے؛ ان کی زمین بھی گھوڑوں سے بھری ہوئی ہے، نہ ہی ان کی رتھوں کا کوئی سرہ ہے:\n8۔ ان کی زمین بھی بتوں سے بھری ہوئی ہے؛ وہ اپنے ہاتھوں کے کام کی عبادت کرتے ہیں، جو ان کی انگلیوں نے بنایا ہے:\n9۔ اور ظالم آدمی جھک جاتا ہے، اور عظیم آدمی عاجز ہو جاتا ہے: اس لیے انہیں معاف نہ کرنا۔\n10۔ چٹان میں داخل ہو جاؤ، اور خود کو مٹی میں چھپا لو، خداوند کے خوف سے، اور اس کی عظمت کی شان کے لیے۔\n11۔ انسان کی بلند نظریں عاجز ہوں گی، اور لوگوں کی تکبر جھکی جائے گی، اور اس دن صرف خداوند کو بلند کیا جائے گا۔\n12. کیونکہ خداوند لشکروں کا دن ہر اس {ایک} پر ہوگا جو مغرور اور بلند ہے، اور ہر اس {جو ہے} پر ہوگا؛ اور اسے نیچا دکھایا جائے گا:\n13۔ اور لبنان کے تمام دیوداروں پر، جو بلند اور بلند ہیں، اور باشان کے تمام بلوط کے درختوں پر،\n14۔ اور تمام اونچے پہاڑوں پر، اور تمام بلند پہاڑوں پر،\n15۔ اور ہر اونچی مینار پر، اور ہر باڑ والی دیوار پر،\n16۔ اور ترشیش کے تمام جہازوں پر، اور تمام خوبصورت مناظر پر۔ {خوشگوار...: عبرانی۔ خواہش کی تصویریں}\n17۔ اور انسان کی بلندی کو جھکا دیا جائے گا، اور لوگوں کی تکبر کو نیچا دکھایا جائے گا: اور اس دن صرف خداوند بلند ہوگا۔\n18۔ اور بتوں کو وہ مکمل طور پر ختم کر دے گا۔ {وہ...: یا، مکمل طور پر ختم ہو جائے گا}\n19۔ اور وہ چٹانوں کے سوراخوں اور زمین کی غاروں میں جائیں گے، خداوند کے خوف سے، اور اس کی عظمت کی شان کے لیے، جب وہ زمین کو شدید ہلانے کے لیے اٹھے گا۔ {زمین کی: عبرانی۔ گرد و غبار کا}\n20۔ اس دن ایک آدمی اپنے چاندی کے بت اور سونے کے بت، جو انہوں نے اپنے لیے بنائے تھے، تلوں اور چمگادڑوں کو پھینکے گا؛ {اس کے چاندی کے بتے...: عبرانی۔ اس کے چاندی کے بت، وغیرہ} {ہر ایک...: یا، اس کے لیے}\n21۔ چٹانوں کی دراڑوں میں اور پھٹے ہوئے پتھروں کی چوٹیوں میں جانا، خداوند کے خوف سے، اور اس کی عظمت کی شان کے لیے، جب وہ زمین کو شدید ہلانے کے لیے اٹھے۔\n22. ایسے انسان سے دور ہو جاؤ جس کی سانس اس کی ناک میں ہے: اس کا حساب کس کے لیے ہے؟","1۔ کیونکہ دیکھو، خداوند، جو لشکروں کا رب ہے، یروشلم اور یہوداہ سے چھین لیتا ہے، پورا روٹی کا تختہ اور پورا پانی کا ذخیرہ چھین لیتا ہے،\n2۔ طاقتور آدمی، اور جنگ کا آدمی، قاضی، نبی، اور سمجھدار اور قدیم شخص،\n3۔ پچاس کا کپتان، معزز آدمی، مشیر، چالاک کاریگر، اور بلیغ مقرر۔ {معزز...: عبرانی۔ چہرے میں ممتاز شخص} {فصاحت...: یا، بولنے میں ماہر}\n4۔ اور میں بچوں کو ان کے شہزادے دوں گا، اور بچے ان پر حکمرانی کریں گے۔\n5۔ اور لوگ ظلم کریں گے، ہر ایک دوسرے سے، اور ہر ایک اپنے پڑوسی سے: بچہ قدیم کے خلاف فخر سے برتاؤ کرے گا، اور عزت داروں کے خلاف حقیر ہوگا۔\n6. جب کوئی آدمی اپنے باپ کے گھر کے بھائی کو پکڑ لے اور کہے: \"تو نے لباس پہنا ہے، تو ہمارا حکمران بنو، اور یہ بربادی {تمہارے ہاتھ میں} ہو جا:\n7۔ اس دن وہ قسم کھائے گا کہ میں شفا دینے والا نہیں بنوں گا؛ کیونکہ میرے گھر میں نہ روٹی ہے نہ کپڑے: مجھے عوام کا حکمران نہ بناؤ۔ {قسم کھاتا ہے: عبرانی۔ ہاتھ اٹھاؤ} {معالج: عبرانی۔ بائنڈر اپ}\n8۔ کیونکہ یروشلم تباہ ہو چکا ہے، اور یہوداہ گر گیا: کیونکہ ان کی زبان اور اعمال خداوند کے خلاف ہیں، تاکہ اس کی عظمت کی آنکھوں کو بھڑکایا جا سکے۔\n9۔ ان کے چہرے کی نمائش ان کے خلاف گواہی دیتی ہے؛ اور وہ اپنا گناہ سدوم قرار دیتے ہیں، وہ اسے چھپاتے نہیں۔ ان کی روح پر افسوس! کیونکہ انہوں نے اپنے لیے برائی کا صلہ دیا ہے۔\n10۔ نیک لوگوں سے کہو کہ یہ اس کے ساتھ اچھا ہوگا، کیونکہ وہ اپنے اعمال کا پھل کھائیں گے۔\n11۔ بدکاروں پر افسوس! {یہ اس کے ساتھ برا ہوگا}: کیونکہ اس کے ہاتھوں کا صلہ اسے ملے گا۔ {دیا گیا...: عبرانی۔ اس کے ساتھ کیا گیا}\n12۔ {جہاں تک} میرے لوگوں کا تعلق ہے، بچے {ہیں} ان کے ظالم، اور عورتیں ان پر حکمرانی کرتی ہیں۔ اے میرے لوگو، جو تمہیں گمراہ کرتے ہیں اور تمہارے راستے کو تباہ کرتے ہیں۔ {لیڈ...: یا، تمہیں مبارک کہو} {تباہ کریں: عبرانی۔ نگل لو}\n13. خداوند کھڑا ہو کر دعا کرتا ہے، اور لوگوں کا فیصلہ کرنے کے لیے کھڑا ہوتا ہے۔\n14۔ خداوند اپنے قوم کے قدیم لوگوں اور اس کے بادشاہوں کے ساتھ فیصلہ کرے گا: کیونکہ تم نے انگور کے باغ کو کھا لیا ہے؛ غریبوں کی مال غنیمت آپ کے گھروں میں ہے۔ {کھایا: یا، جلا ہوا}\n15. آپ کا کیا مطلب ہے کہ آپ میرے لوگوں کو ٹکڑے ٹکڑے کر دیتے ہیں، اور غریبوں کے چہرے پیستے ہیں؟ خداوند خدا لشکروں کا فرماتا ہے۔\n16۔ مزید یہ کہ خداوند فرماتا ہے، کیونکہ صیہون کی بیٹیاں مغرور ہیں، اور گردن پھیلا کر اور بے ہوش آنکھوں کے ساتھ چلتی ہیں، چلتی اور باریک کرتی ہیں {جیسا کہ وہ چلتی ہیں} اور اپنے قدموں سے جھنجھناہٹ کرتی ہیں: {بے حیا...: عبرانی۔ اپنی آنکھوں سے دھوکہ دینا} {باریک کرنا: یا، اچھے طریقے سے ٹھوکر کھانا}\n17. لہٰذا خداوند صیہون کی بیٹیوں کے سر کے تاج پر زخم سے وار کرے گا، اور خداوند ان کے خفیہ حصے دریافت کرے گا۔ {دریافت: عبرانی۔ ننگے ہو جاؤ}\n18۔ اس دن خداوند ان کے جھنجھناکتے زیورات {ان کے پیروں کے ارد}، {ان} کالز، اور {ان} گول ٹائروں کی بہادری چھین لے گا جیسے چاند، {کالز: یا، جال}\n19۔ زنجیریں، اور کنگن، اور مفلرز، {زنجیریں: یا، میٹھے بالز} {مفلرز: یا، چمکدار زیورات}\n20۔ ٹوپیاں، ٹانگوں کے زیورات، سر کے پٹے، تختیاں، اور بالیاں، {تختیاں: عبرانی۔ روح کے گھر}\n21۔ انگوٹھیاں، اور ناک کے زیورات،\n22۔ بدلنے والے لباس کے سوٹ، اور مینٹلز، وملز، اور کرسپنگ پنز،\n23۔ چشمے، عمدہ کپڑا، اور ہڈز، اور پردے۔\n24۔ اور یہ ہو جائے گا، {کہ} میٹھی خوشبو کی جگہ بدبو ہوگی؛ اور گرڈل کی جگہ کرایہ ہے؛ اور بالوں کا گنج پن کی بجائے؛ اور اسٹیونڈر کی جگہ ساک کلاتھ کی بند؛ {اور} خوبصورتی کی بجائے جلنا۔\n25۔ تمہارے آدمی تلوار سے مارے جائیں گے، اور تمہاری طاقت جنگ میں۔ {mighty: Hebrew. شاید}\n26۔ اور اس کے دروازے ماتم کریں گے اور ماتم کریں گے؛ اور وہ زمین پر بیٹھ جائے گی۔ {ویران: یا، خالی: عبرانی۔ صاف}","1۔ اور اس دن سات عورتیں ایک آدمی کو پکڑیں گی، کہیں گی، ہم اپنی روٹی کھائیں گے، اور اپنا لباس پہنیں گے: صرف ہمیں تیرے نام سے پکارا جائے گا، تاکہ ہماری سزا دور ہو جائے۔ {لیٹ...: عبوری۔ تیرا نام ہم پر پکارا جائے} {لے جائے...: یا، لے جاؤ}\n2۔ اس دن خداوند کی شاخ خوبصورت اور شاندار ہوگی، اور زمین کا پھل ان لوگوں کے لیے بہترین اور خوبصورت ہوگا جو اسرائیل سے بچ نکلیں گے۔ {خوبصورت...: عبرانی۔ خوبصورتی اور جلال} {وہ...: عبرانی۔ دی ایسکیپنگ}\n3۔ اور یہ ہو جائے گا کہ جو صہیون میں رہ گیا ہے، اور جو یروشلم میں رہتا ہے، اسے مقدس کہا جائے گا، {حتیٰ کہ} کہ یروشلم میں زندہ لوگوں میں لکھا ہوا ہر وہ شخص مقدس کہا جائے گا: {درمیان...: یا، زندگی کے لیے}\n4۔ جب خداوند صیون کی بیٹیوں کی گندگی کو دھو دے گا، اور یورشلیم کے خون کو اس کے درمیان سے فیصلے کی روح اور جلنے کی روح سے پاک کرے گا۔\n5۔ اور خداوند کوہ صیون کے ہر گھر پر، اور اس کے اجتماعات پر، دن میں بادل اور دھواں اور رات کو جلتی ہوئی آگ پیدا کرے گا: کیونکہ تمام جلال پر دفاع ہوگا۔ {سب پر: یا، سب سے بڑھ کر} {دفاع: عبرانی۔ کورنگ}\n6۔ اور دن کے وقت گرمی سے سایہ کے لیے ایک خیمہ ہوگا، اور پناہ گاہ کے لیے، اور طوفان اور بارش سے بچنے کے لیے۔","1. اب میں اپنے محبوب کو اپنے محبوب کے انگور کے باغ کو چھونے کا گانا گاؤں گا۔ میرے محبوب کے پاس ایک بہت زرخیز پہاڑی میں انگور کا باغ ہے: {ایک بہت...: عبرانی۔ تیل کے بیٹے کا سینگ}\n2۔ اور اس نے اسے باڑ لگایا، اس کے پتھر جمع کیے، اور اس میں بہترین بیل لگائی، اور اس کے بیچ ایک مینار بنایا، اور اس میں شراب کا منہ بھی بنایا، اور اس نے دیکھا کہ اس سے انگور نکل آئیں، اور اس نے جنگلی انگور نکالا۔ {باڑ لگا کر: یا، دیوار بنا دی} {بنایا: عبرانی۔ تراشے}\n3۔ اور اب، اے یروشلم کے باشندو، اور یہوداہ کے لوگو، میں تم سے دعا گو کہ میرے اور میرے انگور کے باغ کے درمیان فیصلہ کرو۔\n4. میرے انگور کے باغ کے ساتھ اور کیا کیا جا سکتا تھا جو میں نے اس میں نہ کیا ہو؟ کیوں جب میں نے دیکھا کہ وہ انگور نکالے، تو اس نے جنگلی انگور نکالائے؟\n5. اور اب آگے بڑھیں؛ میں تمہیں بتاؤں گا کہ میں اپنے انگور کے باغ کے ساتھ کیا کروں گا: میں اس کی باڑ ہٹا دوں گا، اور وہ کھا جائے گا؛ {اور} اس کی دیوار کو توڑ دو، اور اسے روند دیا جائے گا: {روندا...: عبرانی۔ چلنے کے لیے}\n6۔ اور میں اسے تباہ کر دوں گا: اسے نہ کاٹا جائے گا، نہ کھودا جائے گا؛ لیکن وہاں کانٹے اور کانٹے نکلیں گے: میں بادلوں کو حکم دوں گا کہ وہ اس پر بارش نہ برسائیں۔\n7۔ کیونکہ خداوند لشکروں کا باغ {ہے} اسرائیل کا گھر، اور یہوداہ کے لوگ اس کا خوشگوار پودا ہے: اور وہ فیصلے کی تلاش میں تھا، لیکن ظلم دیکھو؛ راستبازی کے لیے، لیکن ایک پکار دیکھو۔ {اس کا...: عبرانی اس کی خوشیوں کا پودا} {ظلم: عبرانی۔ ایک زخم}\n8۔ ان پر افسوس جو گھر گھر مل کر کھیت میں بچھاتے ہیں، یہاں تک کہ کوئی جگہ نہ رہے، تاکہ وہ زمین کے بیچ اکیلے رہ جائیں! {وہ: عبرانی۔ یہ}\n9۔ میرے کانوں میں لشکروں کے رب نے کہا، سچائی کے لیے بہت سے گھر ویران ہوں گے، {حتیٰ کہ} عظیم اور خوبصورت، بغیر کسی باشندے کے۔ {میں...: یا، یہ میرے کانوں میں ہے، خداوند فرماتا ہے، وغیرہ} {ایک...: عبرانی۔ اگر نہیں، وغیرہ}\n10۔ جی ہاں، دس ایکڑ انگور کے باغ سے ایک غسل ملے گا، اور ہومر کے بیج سے ایک ایفہ ملے گا۔\n11۔ ان پر افسوس جو صبح سویرے اٹھتے ہیں، {تاکہ} وہ تیز شراب کی پیروی کریں؛ جو رات تک جاری رہتا ہے، {جب تک شراب انہیں بھڑکا نہ دے!' {آگ: پیچھا کرنا}\n12۔ اور ہارپ، وائل، ٹیبرٹ، پائپ اور شراب ان کی تہواروں میں ہیں: لیکن وہ خداوند کے کام کو نہیں دیکھتے، نہ ہی اس کے ہاتھوں کے عمل کو دیکھتے ہیں۔\n13۔ اسی لیے میرے لوگ قید میں چلے گئے ہیں، کیونکہ {انہیں کوئی علم نہیں}: اور ان کے معزز لوگ بھوکے ہیں، اور ان کی تعداد پیاس سے خشک ہو گئی ہے۔ {معزز...: عبرانی۔ جلال ہی قحط کے لوگ ہیں}\n14۔ لہٰذا جہنم نے خود کو پھیلا دیا ہے، اور اس کا منہ بے حد کھول دیا ہے: اور ان کی عظمت، ان کی تعداد، ان کی شان و شوکت، اور جو خوش ہوتا ہے، وہ اس میں اتر جائے گا۔\n15۔ اور ظالم آدمی کو نیچے گرایا جائے گا، اور طاقتور آدمی عاجز ہو جائے گا، اور بلندوں کی نظریں عاجز ہو جائیں گی:\n16۔ لیکن لشکروں کا رب انصاف میں بلند ہوگا، اور پاک خدا راستبازی میں پاک ہوگا۔ {خدا...: یا، مقدس خدا: عبرانی۔ خدا مقدس}\n17۔ پھر بھیڑیں اپنے طریقے کے مطابق کھائیں گی، اور موٹے لوگوں کی جگہیں اجنبی کھائیں گے۔\n18۔ ان پر افسوس جو باطل کو باطل کی رسیوں سے کھینچتے ہیں، اور گناہ کرتے ہیں جیسے وہ گاڑی کی رسی سے ہو:\n19۔ جو کہتا ہے، وہ جلدی کرے، {اور} اپنا کام جلدی کرے، تاکہ ہم اسے دیکھ سکیں: اور اسرائیل کے مقدس ہستی کی نصیحت قریب آئے، تاکہ ہم جان سکیں!\n20۔ ان پر افسوس جو برائی کو اچھا اور اچھائی کو برا کہتے ہیں؛ جو روشنی کو تاریکی اور روشنی کو تاریکی کے لیے رکھتا ہے؛ جو تلخ کو میٹھا اور میٹھا کڑوا بناتا ہے! {کال...: عبوری۔ برائی کے بارے میں کہیں، یہ اچھا ہے، وغیرہ}\n21۔ ان پر افسوس جو اپنی نظر میں دانا اور اپنی نظر میں ہوشیار ہیں! {ان کی اپنی نظر میں: عبرانی۔ ان کے چہرے کے سامنے}\n22۔ ان پر افسوس جو شراب پینے میں طاقتور ہیں، اور طاقتور لوگ جو تیز شراب پیتے ہیں:\n23۔ جو بدکاروں کو انعام کے لیے جائز قرار دیتی ہیں، اور راستبازوں کی راستبازی اس سے چھین لیتی ہیں!\n24۔ اسی طرح جیسے آگ داڑھی کو کھا جاتی ہے، اور شعلہ بھوسے کو جلا دیتی ہے، اسی طرح ان کی جڑ سڑن کی طرح ہو جائے گی، اور ان کا پھول خاک کی طرح جل جائے گا: کیونکہ انہوں نے لشکروں کے رب کے قانون کو پھینک دیا ہے، اور اسرائیل کے مقدس ہستی کے کلام کو حقیر سمجھا ہے۔ {آگ: عبرانی۔ آگ کی زبان}\n25۔ اسی لیے خداوند کا غصہ اپنے لوگوں پر بھڑک اٹھا، اور اس نے ان پر ہاتھ بڑھایا اور انہیں مارا، اور پہاڑیاں کانپ گئیں، اور ان کی لاشیں گلیوں کے بیچ پھاڑ دی گئیں۔ ان سب کے باوجود اس کا غصہ نہیں ہٹا رہا، بلکہ اس کا ہاتھ اب بھی بڑھا ہوا ہے۔ {پھٹا ہوا: یا، گوبر کی طرح}\n26۔ اور وہ دور سے قوموں کے لیے ایک جھنڈا اٹھائے گا، اور زمین کے کونے سے انہیں سرگوشی کرے گا: اور دیکھتے ہیں وہ تیزی سے آئیں گے:\n27۔ کوئی ان میں سے تھکا یا ٹھوکر نہیں کھائے گا؛ کوئی نہیں سوتا اور نہ سوتا؛ نہ ان کی کمر کی بیلٹ کھلی جائے گی، نہ جوتوں کی لاچٹ ٹوٹی جائے گی:\n28۔ جن کے تیر تیز ہیں، اور ان کے تمام کمان مڑے ہوئے ہیں، ان کے گھوڑوں کے کھر چقماق کی طرح گنے جائیں گے، اور ان کے پہیے طوفان کی طرح ہوں گے:\n29۔ ان کی دہاڑ شیر کی طرح ہوگی، وہ شیر کی طرح دہاڑیں گے: ہاں، وہ دہاڑیں گے، شکار کو پکڑ لیں گے، اور اسے محفوظ لے جائیں گے، اور کوئی اسے بچا نہیں سکے گا۔\n30۔ اور اس دن وہ ان پر سمندر کی گرج کی طرح دھاڑیں گے: اور اگر {کو} زمین کی طرف دیکھے تو اندھیرا اور غم دیکھے، اور روشنی اس کے آسمانوں میں مدھم ہو جائے گی۔ {غم: یا، پریشانی} {اور روشنی...: یا، جب روشنی ہو، تو وہ اس کی تباہی میں تاریک ہو جائے گی}","1۔ اس سال جب بادشاہ عزیہ فوت ہوا، میں نے خداوند کو ایک تخت پر بیٹھا دیکھا، بلند اور بلند کیا ہوا، اور اس کی قطار مندر میں بھر گئی۔ {اس کے...: یا، اس کے اسکرٹ}\n2۔ اس کے اوپر سرافیم کھڑے تھے: ہر ایک کے چھ پر تھے؛ ٹوین سے اس نے اپنا چہرہ ڈھانپ لیا، اور دونوں سے اپنے پاؤں ڈھانپ لیے، اور دونوں سے وہ اڑ گیا۔\n3۔ اور ایک نے دوسرے کو پکارا، اور کہا، پاک، پاک، مقدس ہے، لشکروں کا رب ہے: پوری زمین اس کی شان سے بھری ہوئی ہے۔ {ایک...: عبرانی۔ یہ اس سے پکار رہا تھا} {پورا...: عبرانی اس کی شان پوری زمین کی تکمیل ہے}\n4۔ اور دروازے کے ستون اس کی آواز پر حرکت کرنے لگے، اور گھر دھوئیں سے بھر گیا۔ {دروازہ: عبوری۔ تھریش ہولڈز}\n5. پھر میں نے کہا، ہائے میرے لیے! کیونکہ میں ختم ہو چکا ہوں؛ کیونکہ میں ناپاک ہونٹوں والا آدمی ہوں، اور ناپاک ہونٹوں والے لوگوں کے درمیان رہتا ہوں: کیونکہ میری آنکھوں نے بادشاہ، رب لشکروں کو دیکھا ہے۔ {undone: عبرانی۔ کٹ آف}\n6۔ پھر ایک سرافیم میرے پاس آیا، جس کے ہاتھ میں زندہ کوئلہ تھا، {جو} اس نے چمٹے کے ساتھ قربان گاہ سے لیا تھا: {تھا...: عبرانی۔ اور اس کے ہاتھ میں ایک زندہ کوئلہ}\n7۔ اور اس نے میرے منہ پر رکھا اور کہا، دیکھو، یہ تمہارے ہونٹوں کو چھو گیا ہے؛ اور تمہاری گناہ چھین لی جاتی ہے، اور تمہارا گناہ پاک ہو جاتا ہے۔ {layed...: عبرانی اسے چھونے پر مجبور کیا}\n8۔ اور میں نے خداوند کی آواز سنی، کہہ رہی تھی، میں کس کو بھیجوں اور کون ہمارے لیے جائے گا؟ پھر میں نے کہا، یہاں {ہوں} میں؛ مجھے بھیجو۔ {یہاں...: عبرانی۔ دیکھو مجھے}\n9۔ اور اس نے کہا، جاؤ، اور اس قوم کو بتاؤ، تم واقعی سنو، لیکن نہ سمجھو؛ اور واقعی دیکھو، لیکن محسوس نہیں کرتے۔ {واقعی، لیکن سمجھو: یا، بغیر رکے، وغیرہ: عبرانی۔ سماعت میں وغیرہ}\n10۔ اس قوم کے دل کو موٹا کرو، ان کے کان بوجھل کرو، اور آنکھیں بند کرو؛ تاکہ وہ اپنی آنکھوں سے نہ دیکھیں، کانوں سے سنیں، دل سے سمجھیں، اور تبدیل ہو جائیں، اور شفا پائیں۔\n11۔ پھر میں نے کہا، اے خداوند، کتنے عرصے سے؟ اور اس نے جواب دیا، جب تک شہر بغیر کسی باشندے کے تباہ نہ ہو جائیں، اور گھر انسان سے خالی نہ ہو جائیں، اور زمین مکمل طور پر ویران نہ ہو جائے، {مکمل طور پر...: عبرانی۔ ویران اور ویرانی}\n12۔ اور خداوند نے انسانوں کو دور نکال دیا ہے، اور زمین کے بیچ میں ایک عظیم تباہی ہے۔\n13۔ لیکن پھر بھی اس میں {ہوگا} دسواں ہوگا، اور {و} واپس آئے گا، اور کھایا جائے گا: جیسے ایک ٹیل درخت، اور بلوط کی طرح، جس کا مادہ {ہے} جب وہ {اپنے پتے پھینکیں}؛ اسی طرح مقدس بیج {ہو} جائے گا اس کا مادہ۔ {اور وہ...: یا، جب اسے واپس کیا جائے، اور اسے توڑا جائے} {مادہ: یا، ذخیرہ، یا، تن}","1۔ اور یہ واقعہ آحاز کے زمانے میں ہوا، جو یوتھم کے بیٹے عوزیاہ کا بیٹا تھا، یہوداہ کا بادشاہ، {و} رزین، بادشاہ شام کا، اور پیکاہ رملیاہ کا بیٹا، اسرائیل کا بادشاہ، یروشلم کی طرف گیا تاکہ اس کے خلاف جنگ کرے، لیکن اس پر غالب نہ آ سکا۔\n2۔ اور داؤد کے گھر کو بتایا گیا کہ شام افریم کے ساتھ اتحاد کر رہا ہے۔ اور اس کا دل اور اس کے لوگوں کا دل متاثر ہوا، جیسے جنگل کے درخت ہوا کے ساتھ حرکت کرتے ہیں۔ {کنفیڈریٹ ہے...: عبرانی۔ آرام کرتے ہیں}\n3۔ پھر خداوند نے یسعیاہ سے فرمایا، اب آہاز اور اپنے بیٹے شیرجاشب سے ملنے جاؤ، جو اوپر والے تالاب کے راستے پر ہے، فلر کے میدان کی سڑک پر؛ {شیئرجشب: یعنی، باقی ماندہ واپس آئے گا} {ہائی وے: یا، کاز وے}\n4۔ اور اسے کہو، خبردار رہو اور خاموش رہو؛ نہ ڈرو، نہ ہی ان دھواں دار آگ برداروں کی دو دموں کے لیے، ریزن کے شام پر شدید غصے اور رملیہ کے بیٹے کے لیے بھی۔ {نہ ہی...: عبرانی تمہارا دل نرم نہ ہو}\n5۔ کیونکہ شام، افرائیم اور رملیاہ کے بیٹے نے تمہارے خلاف برا مشورہ دیا ہے اور کہا ہے،\n6۔ آئیے یہوداہ کے خلاف جائیں، اسے پریشان کریں، اور اس میں شگاف کریں، اور اس کے بیچ میں ایک بادشاہ قائم کریں، {حتیٰ کہ} تابعل کا بیٹا: {vex: یا، بیدار}\n7۔ خداوند خدا یوں فرماتا ہے، یہ قائم نہیں رہے گا، اور نہ ہی ہوگا۔\n8۔ شام کے سربراہ {ہے} دمشق کے لیے، اور دمشق کا سر {ہے} ریزن؛ اور تین سو پانچ سال کے اندر افرائیم ٹوٹ جائے گا، تاکہ وہ قوم نہ رہے۔ {وہ...: عببرانی۔ ایک قوم سے}\n9۔ اور افرائیم کا سر {ہے} سامریہ، اور سامریہ کا سر {ہے} رملیاہ کا بیٹا۔ اگر تم ایمان نہیں رکھو گے تو تم ثابت نہیں ہو سکو گے۔ {اگر...: یا، کیا تم ایمان نہیں رکھتے؟ یہ اس لیے ہے کہ تم مستحکم نہیں ہو}\n10۔ مزید یہ کہ خداوند نے آہاز سے دوبارہ فرمایا، {مزید یہ کہ...: عبرانی۔ اور خداوند نے بولنے کے لیے اضافہ کیا}\n11۔ خداوند اپنے خدا کی کوئی نشانی مانگو؛ یا تو گہرائی میں پوچھیں، یا اوپر کی اونچائی میں۔ {پوچھو...: یا، اپنی درخواست گہری کرو}\n12۔ لیکن آحاز نے کہا، میں نہ مانگوں گا، نہ ہی خداوند کو آزماؤں گا۔\n13۔ اور اس نے کہا، اے داؤد کے گھر، اب سنو؛ کیا مردوں کو تھکا دینا تمہارے لیے چھوٹی بات ہے، لیکن کیا تم میرے خدا کو بھی تھکا دو گے؟\n14۔ لہٰذا خداوند خود آپ کو ایک نشان دے گا؛ دیکھو، ایک کنواری حاملہ ہوگی، اور بیٹا پیدا کرے گی، اور اس کا نام عمانوئیل رکھے گی۔ {پکار رہے گا: یا، تم، اے کنواری، پکارو گے}\n15۔ مکھن اور شہد کھائے گا، تاکہ وہ سمجھے کہ برائی سے انکار کرے، اور اچھائی کا انتخاب کرے۔\n16۔ کیونکہ اس سے پہلے کہ بچہ برائی کو رد کرنے اور اچھائی کا انتخاب کرنے کو جانے، وہ زمین جسے تم ناپسند کرتے ہو، دونوں بادشاہوں سے چھوڑ دی جائے گی۔\n17۔ خداوند تم پر، تمہارے لوگوں پر، اور تمہارے باپ کے گھر پر وہ دن لائے گا جو ابھی نہیں آئے، اس دن سے جب افرائیم یہوداہ سے روانہ ہوا؛ {حتیٰ کہ} آشور کا بادشاہ۔\n18۔ اور اسی دن یہ ہو جائے گا، {کہ} خداوند اس مکھی کے لیے سرگوشی کرے گا جو مصر کی دریاؤں کے سب سے کونے میں ہے، اور اس مکھی کے لیے جو {ہے} سرزمین آشور میں۔\n19۔ اور وہ آئیں گے، اور سب کو ویران وادیوں، چٹانوں کے سوراخوں میں، تمام کانٹوں پر، اور تمام جھاڑیوں میں آرام دیں گے۔ {جھاڑیاں: یا، قابل تعریف درخت}\n20۔ اسی دن خداوند ایک ریزر سے شیو کرے گا جو دریا کے پار ان کے ہاتھوں کرایہ پر لیا گیا ہے، آشور کے بادشاہ نے سر اور پاؤں کے بال بھی، اور یہ داڑھی کو بھی نگل جائے گا۔\n21۔ اور اسی دن یہ ہوگا کہ ایک آدمی ایک نوجوان گائے اور دو بھیڑیں پالے گا؛\n22۔ اور یہ ہو جائے گا، کیونکہ دودھ کی فراوانی {جو وہ دیں گے} وہ مکھن کھائے گا: کیونکہ مکھن اور شہد ہر وہ کھائے گا جو زمین میں بچا ہے۔ {زمین: عبرانی۔ زمین کے بیچ}\n23۔ اور اسی دن یہ ہو جائے گا، {کہ} ہر جگہ ہوگی، جہاں ہزار بیلیں تھیں، ہزاروں چاندی کے درختوں پر، وہاں کانٹوں اور کانٹوں کے لیے بھی ہوگا۔\n24۔ تیر اور کمان لے کر {آدمی} وہاں آئیں گے؛ کیونکہ ساری زمین کانٹے اور کانٹے بن جائے گی۔\n25۔ اور {جتنی پہاڑیاں مٹی سے کھودی جائیں گی} وہاں کانٹوں اور کانٹوں کا خوف نہیں آئے گا، بلکہ وہ بیل بھیجنے اور چھوٹے مویشی کے قدموں کے لیے ہوگا۔","1۔ مزید یہ کہ خداوند نے مجھ سے فرمایا، ایک بڑا رول لے لو، اور اس میں ایک آدمی کے قلم سے مہرشلالہشباز کے بارے میں لکھو۔ {مہرشلالہشباز: عبرانی۔ شکار کی رفتار حاصل کرنے میں وہ شکار کو تیز کرتا ہے، یا، رفتار حاصل کرو، وغیرہ۔\n2۔ اور میں نے وفادار گواہوں کو اپنے پاس لیا تاکہ وہ یوریاہ کاهن اور زکریا یبریخیا کے بیٹے کو ریکارڈ کریں۔\n3۔ اور میں نبی کے پاس گیا؛ اور وہ حاملہ ہوئی، اور ایک بیٹا پیدا ہوا۔ پھر خداوند نے مجھ سے کہا، اس کا نام مہر شللالہباز کہہ دے۔ {گیا: ہیب۔ اپروچ کیا گیا}\n4۔ کیونکہ بچے کو پکارنے کے لیے علم ہونے سے پہلے، میرے والد اور میری ماں، دمشق کی دولت اور سامریہ کی مال غنیمت آشور کے بادشاہ کے سامنے چھین لی جائے گی۔ {دولت...: یا، جو آشور کے بادشاہ کے سامنے ہے وہ دولت لے جائے وغیرہ}\n5۔ خداوند نے مجھ سے دوبارہ کہا،\n6۔ چونکہ یہ لوگ شیلوح کے نرم پانی سے انکار کرتے ہیں اور ریزن اور رملیہ کے بیٹے پر خوش ہوتے ہیں؛\n7۔ اب دیکھو، خداوند ان پر دریا کے پانی کو مضبوط اور کثرت سے لاتا ہے، {حتیٰ کہ} آشور کا بادشاہ بھی، اور اپنی ساری شان بھی، اور وہ اپنے تمام راستوں کے اوپر سے گزرے گا، اور اپنے تمام کناروں پر جائے گا:\n8۔ اور وہ یہوداہ سے گزرے گا؛ وہ بھر جائے گا اور اوپر جائے گا، وہ گردن تک پہنچے گا؛ اور اس کے پروں کی پھیلائی تیرے ملک کی چوڑائی کو بھر دے گی، اے عمانوئیل۔ {کھینچتے ہوئے...: عببرانی۔ تمہاری زمین کی وسعت اس کے پروں کی پھیلائی ہوگی۔\n9۔ اے لوگو، خود کو جوڑ لو، اور تم ٹکڑے ٹکڑے ہو جاؤ گے؛ اور سنو، اے دور دراز ملکوں کے: خود کو تیار کرو، اور تم ٹکڑے ٹکڑے ہو جاؤ گے؛ اپنے آپ کو تیار کرو، اور تم ٹکڑے ٹکڑے ہو جاؤ گے۔ {لوگ اور: یا، لوگ، ابھی تک}\n10۔ مل کر مشورہ کریں، اور یہ بے سود ہوگا؛ کلام کہو، اور یہ قائم نہیں رہے گا: کیونکہ خدا ہمارے ساتھ ہے۔\n11۔ کیونکہ خداوند نے مجھ سے یہ بات مضبوط ہاتھ سے کہی اور مجھے ہدایت دی کہ میں اس قوم کے راستے میں نہ چلوں، اور کہا، {ساتھ...: عبرانی۔ ہاتھ کی طاقت میں}\n12۔ یہ نہ کہو، ایک کنفیڈریسی، ان سب کو جنہیں یہ لوگ کہیں گے، ایک کنفیڈریسی؛ نہ ان سے ڈرو، نہ ڈرو۔\n13۔ لشکروں کے رب کو خود مقدس کرو؛ اور اسے اپنا خوف بننے دو، اور اسے تمہارا خوف بننے دو۔\n14. اور وہ ایک پناہ گاہ کے لیے ہوگا؛ لیکن لڑکھڑانے کا پتھر اور اسرائیل کے دونوں خاندانوں کے لیے توہین کا پتھر اور یروشلم کے باشندوں کے لیے ایک جن اور جال کے لیے۔\n15۔ اور ان میں سے بہت سے لڑکھڑائیں گے، گریں گے، ٹوٹ جائیں گے، پھنسے جائیں گے، اور پکڑے جائیں گے۔\n16۔ گواہی کو باندھو، میرے شاگردوں میں قانون کو مہر بند کرو۔\n17۔ اور میں اس خداوند کا انتظار کروں گا، جو اپنا چہرہ یعقوب کے گھر سے چھپاتا ہے، اور میں اسے تلاش کروں گا۔\n18۔ دیکھو، میں اور وہ بچے جنہیں خداوند نے مجھے دیا ہے، اسرائیل میں معجزات اور معجزات کے لیے ہیں، خداوند لشکروں کی طرف سے، جو کوہ صیون میں بستا ہے۔\n19۔ اور جب وہ تم سے کہیں گے، ان سے تلاش کرو جن کی روحیں مانوس ہیں، اور ان جادوگروں سے جو جھانکتے ہیں اور بڑبڑاتے ہیں: کیا ایک قوم کو اپنے خدا کی تلاش نہیں کرنی چاہیے؟ زندہ لوگوں کے لیے مردوں تک؟\n20۔ شریعت اور گواہی کے لیے: اگر وہ اس لفظ کے مطابق نہیں بولتے تو {یہ ہے} کیونکہ {ان میں روشنی نہیں ہے}۔ {نہیں...: عبرانی۔ کوئی صبح نہیں}\n21۔ اور وہ اس سے گزریں گے، بمشکل اور بھوکے ہوئے: اور یہ ہوگا کہ جب وہ بھوکے ہوں گے، تو خود کو پریشان کریں گے، اپنے بادشاہ اور خدا کو لعنت دیں گے، اور اوپر دیکھیں گے۔\n22۔ اور وہ زمین کی طرف دیکھیں گے؛ اور دیکھو مصیبت اور تاریکی، اذیت کی مدھم؛ اور {وہ اندھیرے میں دھکیل دیے جائیں گے۔","1۔ تاہم وہ مدھم پن {ویسی نہیں ہوگی} جیسی {تھی} جب اس نے پہلے زبولون کی زمین اور نفتالی کی سرزمین کو ہلکا سا نقصان پہنچایا، اور بعد میں اس نے سمندر کے راستے کو، اردن کے پار، قوموں کی گلیل میں زیادہ شدید تکلیف دی۔ {قوموں میں: یا، آبادی والی}\n2۔ جو لوگ تاریکی میں چلتے تھے انہوں نے عظیم روشنی دیکھی ہے: جو موت کے سائے کی سرزمین میں بستے ہیں، ان پر روشنی چمکی ہے۔\n3۔ تم نے قوم کو بڑھا دیا ہے، {اور} خوشی میں اضافہ نہیں کیا: وہ تمہارے سامنے فصل کی خوشی کے مطابق خوش ہوتے ہیں، {اور} جیسے {لوگ} جب مال بانٹتے ہیں تو خوش ہوتے ہیں۔ {نہیں: یا، اس کے لیے}\n4۔ کیونکہ تم نے اس کے بوجھ کا جوا توڑ دیا، اور اس کے کندھے کی چھڑی، اس کے ظالم کی چھڑی توڑ دی، جیسا کہ مدیان کے زمانے میں تھا۔ {کیونکہ...: یا، جب تم ٹوٹتے ہو}\n5۔ ہر جنگجو کی لڑائی میں الجھن بھرے شور کے ساتھ، اور خون میں لپٹے ہوئے کپڑے؛ لیکن {یہ} جلتا ہوا {اور} آگ کے ایندھن کے ساتھ ہوگا۔ {لیے...: یا، جب پوری جنگجو کی جنگ ہوئی، وغیرہ} {لیکن...: یا، اور وہ تھا، وغیرہ} {ایندھن: ہیب۔ گوشت}\n6۔ کیونکہ ہمارے لیے ایک بچہ پیدا ہوتا ہے، ہمیں ایک بیٹا دیا جاتا ہے: اور حکومت اس کے کندھے پر ہوگی: اور اس کا نام کمال بخش، مشیر، طاقتور خدا، ابدی باپ، امن کا شہزادہ کہا جائے گا۔\n7۔ اس کی حکومت اور امن کے بڑھنے کا کوئی اختتام نہیں ہوگا، داؤد کے تخت پر، اور اس کی بادشاہی پر، اسے حکم دینے، اور اسے ہمیشہ کے لیے فیصلے اور انصاف کے ساتھ قائم کرنے کے لیے۔ لشکروں کے رب کا جوش یہ کام کرے گا۔\n8۔ خداوند نے یعقوب میں ایک پیغام بھیجا، اور وہ اسرائیل پر روشن ہو گیا۔\n9۔ اور سب لوگ جانیں گے، حتیٰ کہ افرایم اور سامریہ کے باشندے بھی، جو غرور اور دل کی مضبوطی سے کہتے ہیں،\n10۔ اینٹیں گر چکی ہیں، لیکن ہم تراشے ہوئے پتھروں سے تعمیر کریں گے: چاپلوس کاٹے جائیں گے، لیکن ہم انہیں دیودار میں بدل دیں گے۔\n11. لہٰذا خداوند ریزن کے دشمنوں کو اس کے خلاف کھڑا کرے گا، اور اس کے دشمنوں کو متحد کرے گا؛ {شامل ہوں: عببرانی۔ منڈل}\n12۔ شامی پہلے اور فلسطینی پیچھے؛ اور وہ اسرائیل کو کھلے منہ سے نگلیں گے۔ ان سب کے باوجود اس کا غصہ نہیں ہٹا رہا، بلکہ اس کا ہاتھ اب بھی بڑھا ہوا ہے۔ {کھولو: عبوری۔ مکمل\n13۔ کیونکہ لوگ اس کی طرف نہیں مڑتے جو انہیں مارتا ہے، نہ ہی وہ لشکروں کے رب کی تلاش کرتے ہیں۔\n14۔ لہٰذا خداوند ایک دن میں اسرائیل سے سر اور دم، شاخ اور دوڑ کاٹ دے گا۔\n15۔ قدیم اور معزز ہے، وہ {ہے} سر؛ اور وہ نبی جو جھوٹ سکھاتا ہے، وہ دم ہے۔\n16۔ کیونکہ اس قوم کے رہنما {ان} کو غلطی پر مجبور کرتے ہیں؛ اور {جو ہیں} ان میں سے {تباہ ہو جاتے ہیں}۔ {رہنما: یا، وہ جو انہیں بابرکت کہتے ہیں} {قیادت میں: یا، جسے مبارک کہا جاتا ہے} {تباہ شدہ: عبرانی۔ نگل لیا گیا}\n17۔ لہٰذا خداوند ان کے نوجوانوں میں خوشی نہیں پائے گا، نہ ہی ان کے یتیم اور بیواؤں پر رحم کرے گا: کیونکہ ہر کوئی منافق اور بدکار ہے، اور ہر منہ بے وقوفی کہتا ہے۔ ان سب کے باوجود اس کا غصہ نہیں ہٹا رہا، بلکہ اس کا ہاتھ اب بھی بڑھا ہوا ہے۔ {فولی: یا، ولنی}\n18۔ کیونکہ برائی آگ کی طرح جلتی ہے: یہ کانٹوں اور کانٹوں کو کھا جائے گی، اور جنگل کے جھاڑیوں میں جل جائے گی، اور وہ دھواں اٹھانے کی طرح اوپر اٹھے گی۔\n19۔ لشکروں کے رب کے غضب سے زمین تاریک ہو گئی ہے، اور لوگ آگ کا ایندھن ہوں گے: کوئی بھی اپنے بھائی کو معاف نہیں کرے گا۔ {ایندھن: ہیب۔ گوشت}\n20۔ اور وہ دائیں ہاتھ سے پکڑے گا، اور بھوکا رہے گا؛ اور وہ بائیں ہاتھ سے کھائے گا، اور وہ مطمئن نہیں ہوں گے: وہ ہر شخص کو اس کے بازو کا گوشت کھائیں گے: {چھینا: عبرانی کٹ}\n21. مناسے، افرائیم؛ اور افرائیم، منسیہ: {اور} وہ سب مل کر یہوداہ کے خلاف ہوں گے۔ ان سب کے باوجود اس کا غصہ نہیں ہٹا رہا، بلکہ اس کا ہاتھ اب بھی بڑھا ہوا ہے۔","1۔ ان پر افسوس جو ناجائز احکام کا حکم دیتے ہیں، اور جو سخت لکھتے ہیں {جو انہوں نے مقرر کیا ہے}؛ {جو لکھتے ہیں...: یا، ان لکھاریوں کے لیے جو سنجیدگی لکھتے ہیں}\n2۔ محتاجوں کو فیصلے سے دور کرنا، اور اپنے لوگوں کے غریبوں سے حق چھیننا، تاکہ بیوائیں ان کا شکار بن سکیں، اور یتیم کو لوٹ سکیں!\n3۔ اور آپ ملاقات کے دن اور اس ویرانی میں کیا کریں گے جو دور سے آئے گی؟ تم مدد کے لیے کس کے پاس بھاگو گے؟ اور تم اپنی شان کہاں چھوڑو گے؟\n4۔ میرے بغیر وہ قیدیوں کے سامنے جھک جائیں گے، اور وہ مارے جانے والوں کے سامنے گر جائیں گے۔ ان سب کے باوجود اس کا غصہ نہیں ہٹا رہا، بلکہ اس کا ہاتھ اب بھی بڑھا ہوا ہے۔\n5. اے آشوری، میرے غصے کی چھڑی اور ان کے ہاتھ میں چھڑی میری ناراضگی ہے۔ {O...: یا، آشوریوں پر افسوس: عبرانی۔ آشور} {اور: یا، لیکن}\n6۔ میں اسے ایک منافق قوم کے خلاف بھیجوں گا، اور اپنے غضب کے لوگوں کے خلاف اسے حکم دوں گا، کہ وہ مال لوٹے، شکار کو پکڑے، اور انہیں سڑکوں کی دلدل کی طرح روند دے۔ {ٹریڈ...: ہیب۔ انہیں موقع دو}\n7۔ چاہے اس کا مطلب ایسا نہ ہو، اس کا دل بھی ایسا نہیں سوچتا؛ لیکن {یہ} اس کے دل میں ہے کہ وہ چند قوموں کو تباہ اور کاٹ دے۔\n8۔ کیونکہ وہ کہتا ہے، {کیا} میرے شہزادے بادشاہ نہیں ہیں؟\n9. {کیا} کالنو کارکیمش کے طور پر نہیں ہے؟ {کیا} ہاماتھ بطور آرپاد نہیں ہے؟ {کیا} سامریہ دمشق کے طور پر نہیں ہے؟\n10۔ جیسا کہ میرے ہاتھ نے بتوں کی بادشاہتوں کو پایا ہے، جن کی کندہ شدہ تصاویر یروشلم اور سامریہ سے بہتر تھیں؛\n11۔ کیا میں ویسے ہی نہیں کروں گا جیسے میں نے سامریا اور اس کے بتوں کے ساتھ کیا، ویسا ہی یروشلم اور اس کے بتوں کے ساتھ بھی؟\n12۔ اسی لیے یہ ہوگا کہ جب خداوند اپنا پورا کام کوہ صیون اور یروشلم پر کر دے، تو میں آشور کے بادشاہ کے مضبوط دل کے پھل اور اس کی بلند نظروں کی شان کو سزا دوں گا۔ {سزا: عبرانی۔ وزٹ پر} {موٹا...: عبرانی۔ دل کی عظمت}\n13۔ کیونکہ وہ کہتا ہے، میں نے اپنے ہاتھ کی طاقت سے اور اپنی حکمت سے کیا ہے؛ کیونکہ میں محتاط ہوں: اور میں نے لوگوں کی حدود ہٹا دی ہیں، ان کے خزانے لوٹے ہیں، اور میں نے باشندوں کو بہادر انسان کی طرح نیچا دکھایا: {ایک بہادر...: یا، بہت سے لوگ}\n14۔ اور میرے ہاتھ نے لوگوں کی دولت کو گھونسلے کی طرح ڈھونڈ لیا ہے: اور جب کوئی باقی انڈے جمع کرتا ہے، میں نے ساری زمین جمع کی ہے؛ اور کوئی بھی ایسا نہیں تھا جس نے پر کو حرکت دی، منہ کھولا، یا جھانکا۔\n15. کیا کلہاڑی اس کے خلاف فخر کرے گی جو اس کے ساتھ ہے؟ {یا} کیا آری اس کے خلاف بڑھے گی جو اسے ہلائے؟ گویا چھڑی خود کو ان کے خلاف ہلاتی ہے جو اسے اٹھاتی ہیں، یا جیسے عصا خود کو اٹھا لے، جیسے کوئی لکڑی نہ ہو۔ {چھڑی...: یا، ایک چھڑی انہیں ہلاتی ہے جو اسے اٹھاتی ہے} {خود، جیسے...: یا، وہ جو لکڑی نہیں ہے}\n16۔ لہٰذا خداوند، رب لشکروں، اپنے موٹے پتلے لوگوں کے درمیان بھیجے گا؛ اور اپنی شان کے نیچے وہ آگ کی طرح جلتا ہوا شعلہ بھڑکائے گا۔\n17۔ اور اسرائیل کی روشنی آگ کے لیے ہوگی، اور اس کی مقدس ہستی آگ کے لیے: اور وہ ایک دن میں اس کے کانٹے اور کانٹے جلا دے گی؛\n18۔ اور اپنے جنگل کی شان و شوکت اور زرخیز کھیت کو کھا جائے گا، روح اور جسم دونوں: اور وہ ایسے ہوں گے جیسے کوئی پرچم بردار بے ہوش ہو جائے۔ {دونوں...: عبرانی۔ روح سے، اور یہاں تک کہ جسم تک}\n19۔ اور اس کے جنگل کے باقی درخت کم ہوں گے، تاکہ کوئی بچہ انہیں لکھ سکے۔ {چند: عبوری۔ نمبر}\n20۔ اور اسی دن یہ ہوگا کہ اسرائیل کے باقیات اور جو لوگ یعقوب کے گھر سے بچ نکلے ہیں، وہ دوبارہ اس پر نہیں رہیں گے جس نے انہیں مارا؛ بلکہ وہ سچ میں خداوند پر قائم رہے گا، جو اسرائیل کا مقدس ہے۔\n21. باقی ماندہ، حتیٰ کہ یعقوب کے باقیات بھی، عظیم خدا کے پاس واپس آئیں گے۔\n22۔ اگرچہ تمہاری قوم اسرائیل سمندر کی ریت کی طرح ہے، {پھر بھی} ان کی باقیات واپس آئیں گی: جو کھانا مقرر کیا گیا ہے وہ راستبازی سے بھر جائے گا۔ {ان میں سے: عبرانی۔ in, or, among, etc} {with: or, in}\n23. کیونکہ خداوند خدا لشکروں کے لیے تمام زمین کے بیچ میں پختہ ارادے کے ساتھ کھانا ہوگا۔\n24۔ لہٰذا خداوند خدا لشکروں کا فرماتا ہے، اے میرے لوگ جو صیون میں بستے ہیں، آشوری سے نہ ڈرو: وہ تمہیں لاٹھی سے مارے گا، اور مصر کی طرح اپنی عصا تمہارے خلاف اٹھائے گا۔ {اور کرے گا...: یا، لیکن وہ اپنا عصا اٹھائے گا}\n25۔ ابھی تھوڑے ہی عرصے کے لیے، اور غصہ ختم ہو جائے گا، اور ان کی تباہی میں میرا غصہ ہوگا۔\n26۔ اور لشکروں کا رب اس کے لیے مدیان کے قتل عام کے مطابق اورب کی چٹان پر عذاب برپا کرے گا: اور جیسے اس کی چھڑی سمندر پر تھی، ویسے ہی وہ اسے مصر کے طریقے سے اٹھائے گا۔\n27۔ اور اسی دن یہ ہو جائے گا کہ اس کا بوجھ تمہارے کندھے سے ہٹا دیا جائے گا، اور اس کا جوا تمہارے گردن سے ہٹا دیا جائے گا، اور اس کا جوا مسح کرنے کی وجہ سے ختم ہو جائے گا۔ {لے لیا جائے...: عبرانی۔ ہٹانا}\n28۔ وہ آیاتھ آیا، اسے میگرون کے حوالے کر دیا گیا؛ میخماش میں اس نے اپنی گاڑیاں رکھ دی ہیں:\n29۔ وہ راستے سے گزر چکے ہیں: انہوں نے گیبا میں رہائش اختیار کر لی ہے؛ رامہ خوفزدہ ہے؛ ساؤل کی گیبیاہ فرار ہو جاتی ہے۔\n30۔ اے گالیم کی بیٹی، اپنی آواز بلند کرو، اسے لیش تک پہنچاؤ، اے غریب اناتھوتھ۔ {لفٹ...: عبرانی زور زور سے رونا}\n31. مدمناہ کو ہٹا دیا جاتا ہے؛ گبم کے باشندے خود کو جمع کر کے فرار ہو جاتے ہیں۔\n32۔ اس دن وہ اب بھی نوب میں رہے گا: وہ یروشلم کی پہاڑی صیون کی بیٹی کے پہاڑ پر ہاتھ ملائے گا۔\n33۔ دیکھو، خداوند، لشکروں کا رب، شاخ کو خوف سے کاٹ دے گا: اور بلند قد والے لوگ کاٹ دیے جائیں گے، اور مغرور عاجز ہوں گے۔\n34۔ اور وہ جنگل کی جھاڑیوں کو لوہے سے کاٹے گا، اور لبنان ایک طاقتور ہتھیار سے گر جائے گا۔ {بائی...: یا، بہت زیادہ}","1۔ اور یسوع کی شاخ سے ایک چھڑی نکلے گی، اور اس کی جڑوں سے ایک شاخ نکلے گی:\n2۔ اور خداوند کی روح اس پر آرام کرے گی، حکمت اور سمجھ کی روح، مشورے اور طاقت کی روح، علم کی روح اور خداوند کے خوف کی روح؛\n3۔ اور خدا کے خوف میں اسے فوری سمجھ دار بنا دے: اور وہ اس کی آنکھوں کی نظر سے فیصلہ نہیں کرے گا، نہ کانوں کی سماعت کے بعد ملامت کرے گا: {جلدی...: عبرانی۔ خوشبو یا خوشبو}\n4۔ لیکن وہ راستبازی کے ساتھ غریبوں کا فیصلہ کرے گا، اور زمین کے عاجزوں کے لیے انصاف سے سزا دے گا: اور وہ زمین کو اپنے منہ کی چھڑی سے مارے گا، اور اپنے ہونٹوں کی سانس سے بدکاروں کو قتل کرے گا۔ {سرزنش: یا، بحث کرو}\n5۔ اور راستبازی اس کی کمر کی بیلٹ ہوگی، اور وفاداری اس کی لگام کی بیلٹ ہوگی۔\n6۔ بھیڑیا بھیڑ کے ساتھ رہے گا، اور چیتا بچے کے ساتھ لیٹے گا؛ اور بچھڑا اور نوجوان شیر اور موٹا ایک ساتھ؛ اور ایک چھوٹا بچہ ان کی قیادت کرے گا۔\n7۔ اور گائے اور ریچھ خوراک لیں گے؛ ان کے بچے ایک ساتھ لیٹیں گے: اور شیر بیل کی طرح بھوسہ کھائے گا۔\n8۔ اور چوسنے والا بچہ ایسپ کے سوراخ پر کھیلے گا، اور دودھ چھڑانے والا بچہ اپنا ہاتھ مرغی کے غار پر رکھے گا۔ {کاکاٹریس': یا، ایڈرز کا}\n9۔ وہ میرے تمام مقدس پہاڑوں میں نقصان نہیں پہنچائیں گے اور نہ ہی تباہ کریں گے: کیونکہ زمین خداوند کے علم سے بھری ہوگی، جیسے پانی سمندر کو ڈھانپے گا۔\n10۔ اور اس دن یسوع کی ایک جڑ ہوگی، جو لوگوں کے ایک جھنڈے کی نمائندگی کرے گی؛ غیر یہودی اس کی تلاش کریں گے: اور اس کی آرام شان دار ہوگی۔ {شاندار: عبرانی۔ جلال}\n11۔ اور اس دن یہ ہوگا کہ خداوند دوسری بار اپنا ہاتھ اٹھائے گا تاکہ اپنی قوم کے باقی ماندہ حصے کو واپس لے سکے، جو آشور، مصر، پاتھروس، کش، ایلام، شینار، حماث اور سمندر کے جزیروں سے بچ جائیں گے۔\n12۔ اور وہ قوموں کے لیے ایک نشان لگائے گا، اور اسرائیل کے بے دخل لوگوں کو جمع کرے گا، اور یہوداہ کے بکھرے ہوئے لوگوں کو زمین کے چاروں کونوں سے جمع کرے گا۔ {کونے: عبوری۔ ونگز}\n13۔ افرائیم کی حسد بھی ختم ہو جائے گی، اور یہوداہ کے مخالفین کاٹ دیے جائیں گے: افرائیم یہوداہ سے حسد نہیں کرے گا، اور یہوداہ افرایم کو پریشان نہیں کرے گا۔\n14۔ لیکن وہ فلسطینیوں کے کندھوں پر مغرب کی طرف اڑیں گے؛ وہ مل کر انہیں مشرق سے لوٹیں گے: وہ ایڈم اور موآب پر ہاتھ رکھیں گے؛ اور آمون کے بچے ان کی اطاعت کریں گے۔ {وہ لوگ: عبوری۔ بچے {وہ لائیں گے...: عبرانی ایڈوم اور موآب ان کے ہاتھ رکھنے والے ہوں گے} {اطاعت کریں گے...: عبرانی۔ ان کی اطاعت}\n15۔ اور خداوند مصری سمندر کی زبان کو مکمل طور پر تباہ کر دے گا؛ اور اپنی طاقتور ہوا کے ساتھ وہ دریا پر ہاتھ ہلائے گا، اور اسے سات ندیوں میں مارے گا، اور {انسانوں} کو خشک جوتے پر لے جائے گا۔ {ڈرائی شوڈ: ہیب۔ جوتوں میں}\n16۔ اور اس کی قوم کے باقیات کے لیے ایک شاہراہ ہوگی، جو آشور سے چھوڑی جائے گی؛ جیسے وہ دن اسرائیل کے لیے تھا جب وہ مصر کی سرزمین سے باہر آیا تھا۔","1۔ اور اس دن تم کہو گے، اے خداوند، میں تیری تعریف کروں گا: اگرچہ تم مجھ سے ناراض تھے، تمہارا غصہ دور ہو گیا، اور تو نے مجھے تسلی دی۔\n2. دیکھو، خدا میری نجات ہے؛ میں بھروسہ کروں گا، اور ڈروں گا نہیں: کیونکہ خداوند یہووا میری طاقت اور میرا گیت ہے؛ وہ میری نجات بھی بن چکا ہے۔\n3۔ لہٰذا تم خوشی سے نجات کے کنوؤں سے پانی نکالو گے۔\n4۔ اور اس دن تم کہو گے، خداوند کی تعریف کرو، اس کا نام پکارو، اس کے اعمال کو لوگوں میں بیان کرو، اور اس کا نام بلند کرو گے۔ {پکارو...: یا، اعلان کرو}\n5. خداوند کے لیے گاؤ؛ کیونکہ اس نے اچھے کام کیے ہیں: یہ {ہے} پوری زمین میں معلوم ہے۔\n6۔ پکار کرو اور پکارو، اے صیون کے باشندے: کیونکہ تمہارے درمیان اسرائیل کا مقدس عظیم ہے۔ {رہائشی: عبرانی۔ آبادکار}","1۔ بابل کا بوجھ، جسے یسعیاہ ابن عاموز نے دیکھا۔\n2۔ اونچے پہاڑ پر جھنڈا اٹھاؤ، آواز بلند کرو، ہاتھ ملاؤ، تاکہ وہ اشرافیہ کے دروازے میں داخل ہو سکیں۔\n3۔ میں نے اپنے مقدس لوگوں کو حکم دیا ہے، میں نے اپنے طاقتور لوگوں کو بھی اپنے غصے کے لیے بلایا ہے، {حتیٰ کہ} ان کو بھی جو میری عظمت میں خوش ہیں۔\n4۔ پہاڑوں میں ہجوم کی آواز، جیسے کوئی عظیم قوم؛ قوموں کے بادشاہتوں کے جمع ہونے کی شور و غل کی آواز: لشکروں کا رب جنگ کی فوج کو جمع کرتا ہے۔ {جیسے...: عبرانی۔ جس کی مشابہت ہے}\n5۔ وہ ایک دور دراز ملک سے، آسمان کے اختتام سے، {حتیٰ کہ} خداوند اور اس کے غصے کے ہتھیاروں سے آتے ہیں، تاکہ پوری زمین کو تباہ کر سکیں۔\n6. ہاؤل یے؛ کیونکہ خداوند کا دن قریب آ رہا ہے؛ یہ قادر مطلق کی طرف سے تباہی کی صورت میں آئے گا۔\n7. اس لیے تمام ہاتھ کمزور ہو جائیں گے، اور ہر انسان کا دل پگھل جائے گا: {بے ہوش ہو جاؤ: یا گر جاؤ}\n8۔ اور وہ ڈریں گے: درد اور غم انہیں گھیر لیں گے؛ وہ ایک عورت کی طرح تکلیف میں ہوں گے: وہ ایک دوسرے پر حیران ہوں گے؛ ان کے چہرے شعلوں کی طرح ہوں گے۔ {حیران ہو جاؤ: عبرانی۔ حیرت} {ایک...: عبرانی۔ ہر آدمی اپنے پڑوسی کے پاس} {شعلے: عبرانی۔ شعلوں کے چہرے}\n9۔ دیکھو، خداوند کا دن آتا ہے، ظالم غصے اور شدید غصے کے ساتھ، تاکہ زمین کو ویران کر دے: اور وہ اس کے گناہ گاروں کو وہاں سے نکال دے گا۔\n10۔ کیونکہ آسمان کے ستارے اور ان کے برج اپنی روشنی نہیں دیں گے: سورج روانہ ہوتے ہوئے تاریک ہو جائے گا، اور چاند اپنی روشنی نہیں دکھائے گا۔\n11۔ اور میں دنیا کو ان کی برائی کی سزا دوں گا، اور بدکاروں کو ان کے گناہوں کے لیے؛ اور میں مغرور لوگوں کی تکبر کو ختم کر دوں گا، اور خوفناک لوگوں کی تکبر کو نیچا دبا دوں گا۔\n12۔ میں ایک آدمی کو سونے سے زیادہ قیمتی بنا دوں گا؛ یہاں تک کہ اوفیر کے سنہری ٹکڑے سے بھی ایک مرد۔\n13۔ اسی لیے میں آسمانوں کو ہلا دوں گا، اور زمین اپنی جگہ سے ہٹ جائے گی، لشکروں کے رب کے غضب میں، اور اس کے شدید غضب کے دن۔\n14۔ اور یہ ایسے ہوگا جیسے شکار کیے گئے ہجو، اور بھیڑ کی طرح جسے کوئی نہیں اٹھائے گا: وہ ہر شخص اپنے لوگوں کی طرف رجوع کرے گا، اور ہر ایک کو اپنی زمین میں بھاگ جائے گا۔\n15۔ جو بھی ملے گا، اسے اندر سے گزارا جائے گا؛ اور جو بھی ان سے جڑا ہوگا وہ تلوار کے ہاتھوں مارا جائے گا۔\n16۔ ان کے بچے بھی ان کی آنکھوں کے سامنے ٹکڑے ٹکڑے ہو جائیں گے؛ ان کے گھر خراب ہو جائیں گے، اور ان کی بیویاں لوٹ چکی ہوں گی۔\n17۔ دیکھو، میں میدوں کو ان کے خلاف بھڑکاؤں گا، جو چاندی کو نظر انداز کریں گے؛ اور سونے کے لیے، وہ اس میں خوش نہیں ہوں گے۔\n18۔ ان کے کمان بھی نوجوانوں کو ٹکڑے ٹکڑے کر دیں گے؛ اور وہ رحم کے پھل پر رحم نہیں کریں گے؛ ان کی آنکھ بچوں کو نہیں بخشے گی۔\n19۔ اور بابل، بادشاہتوں کی شان، کلدیوں کی عظمت کی خوبصورتی، ویسی ہی ہوگی جیسے خدا نے سدوم اور عمورہ کو گرا دیا تھا۔ {یعنی...: عبرانی جیسا کہ تختہ الٹنا}\n20۔ یہ کبھی آباد نہیں ہوگا، نہ ہی نسل در نسل آباد ہوگا؛ نہ ہی وہاں عربی خیمہ لگائے جائیں گے؛ نہ ہی چرواہے وہاں اپنی جماعت بنائیں گے۔\n21. لیکن صحرا کے جنگلی جانور وہاں پڑے ہوں گے؛ اور ان کے گھر غمگین مخلوقات سے بھرے ہوں گے؛ اور وہاں الو رہیں گے، اور سیٹرز وہاں رقص کریں گے۔ {wild...: عبرانی زیم} {اداس...: عبرانی۔ اوچم} {الو: یا، شتر مرغ: عبرانی۔ بیٹیاں آف دی آول}\n22۔ اور جزیروں کے جنگلی جانور اپنے ویران گھروں میں روتے رہیں گے، اور اژدہے ان کے خوبصورت محلوں میں: اور اس کا وقت قریب ہے، اور اس کے دن لمبے نہیں ہوں گے۔ {دی وائلڈ...: عبرانی۔ iim} {ویران...: یا، محلیں}","1۔ کیونکہ خداوند یعقوب پر رحم کرے گا، اور پھر بھی اسرائیل کو چنے گا، اور انہیں ان کے اپنے ملک میں آباد کرے گا: اور اجنبی ان کے ساتھ شامل ہو جائیں گے، اور وہ یعقوب کے گھر سے چمٹ جائیں گے۔\n2۔ اور لوگ انہیں لے کر ان کی جگہ لے آئیں گے، اور اسرائیل کا گھر انہیں خداوند کی زمین میں غلاموں اور خادماؤں کے طور پر قبضہ کرے گا، اور وہ انہیں قیدی بنائیں گے، جن کے قیدی وہ تھے؛ اور وہ اپنے ظالموں پر حکومت کریں گے۔ {کون...: عبرانی جس نے انہیں قیدی بنا لیا تھا}\n3۔ اور یہ اس دن ہوگا جب خداوند تمہیں تمہارے غم، تمہارے خوف اور اس سخت غلامی سے آرام دے گا جس میں تمہیں خدمت کے لیے بنایا گیا تھا،\n4۔ کہ تم بابل کے بادشاہ کے خلاف یہ کہاوت لے کر کہو گے، ظالم کیسے رکا! گولڈن سٹی ختم ہو گیا! {کہاوت: یا، طنزیہ گفتگو} {سنہری...: یا، سونے کی بالکل}\n5۔ خداوند نے بدکاروں کی چھڑی توڑ دی، {اور} حکمرانوں کی عصا بھی۔\n6۔ جو لوگوں کو مسلسل غصے میں مارا جاتا ہے، جو غصے میں قوموں پر حکومت کرتا ہے، وہ ستایا جاتا ہے، {اور} کوئی رکاوٹ نہیں رکھتا۔ {ایک مسلسل...: عبرانی۔ ایک فالج بغیر ہٹائے ہٹے}\n7. پوری زمین آرام میں ہے، {اور} خاموش ہے: وہ گانے میں پھٹ پڑتے ہیں۔\n8. ہاں، صنوبر کے درخت تم پر خوش ہوتے ہیں، {اور} لبنان کے دیودار، {کہتے ہیں}، جب سے تم زمین پر پڑے ہو، کوئی آدمی ہمارے خلاف نہیں آیا۔\n9۔ جہنم نیچے سے آتا ہے تاکہ آپ آپ سے ملیں: یہ آپ کے لیے مردوں کو جگاتا ہے، {حتیٰ کہ} زمین کے تمام اہم لوگوں کے لیے؛ اس نے قوموں کے تمام بادشاہوں کو ان کے تختوں سے اٹھا دیا ہے۔ {جہنم: یا، قبر} {چیف...: عببرانی۔ رہنما، یا عظیم بکریاں\n10۔ جو وہ تم سے کہیں گے اور کہیں گے، کیا تم بھی ہماری طرح کمزور ہو رہے ہو؟ کیا تم ہمارے جیسے ہو گئے ہو؟\n11. تمہاری شان و شوکت قبر تک لائی جاتی ہے، {اور} تمہاری وائلز کی آواز: کیڑا تمہارے نیچے پھیلا ہوتا ہے، اور کیڑے تمہیں ڈھانپ لیتے ہیں۔\n12. اے لوسیفر، صبح کے بیٹے، تم آسمان سے کیسے گر گئے ہو! تم کیسے زمین بوس ہو گئے، جس نے قوموں کو کمزور کر دیا! {او لوسیفر: یا، اے ڈے اسٹار}\n13۔ کیونکہ تم نے اپنے دل میں کہا ہے، میں آسمان پر چڑھوں گا، میں اپنے تخت کو خدا کے ستاروں سے بلند کروں گا: میں جماعت کے پہاڑ پر بھی بیٹھوں گا، شمال کے کناروں پر:\n14. میں بادلوں کی بلندیوں سے بلند ہوں گا؛ میں سب سے زیادہ بلند ہوں گا۔\n15۔ پھر بھی تمہیں جہنم میں لے جایا جائے گا، گڑھے کے کناروں پر۔\n16. جو تمہیں دیکھیں گے وہ تمہیں غور سے دیکھیں گے، {اور} تمہیں غور کریں گے، {کہیں، کیا یہی وہ شخص ہے جس نے زمین کو ہلا دیا، جس نے سلطنتوں کو ہلا دیا؛\n17۔ {جس نے} دنیا کو ایک ویران بنا دیا، اور اس کے شہروں کو تباہ کر دیا؛ {جو} نے اپنے قیدیوں کے گھر کو نہیں کھولا؟ {کھولا...: یا، اپنے قیدیوں کو گھر واپس جانے نہیں دیا؟}\n18۔ قوموں کے تمام بادشاہ، {حتیٰ کہ} سب بھی، جلال میں لیٹے ہوئے ہیں، ہر ایک اپنے گھر میں۔\n19۔ لیکن تم اپنی قبر سے ایک مکروہ شاخ کی طرح نکالے گئے ہو، {اور ان مارے گئے کپڑوں کی طرح} جو تلوار سے گھونپے جاتے ہیں، جو گڑھے کے پتھروں تک پہنچتے ہیں؛ جیسے پیروں تلے روند دی گئی لاش کی طرح۔\n20۔ تم ان کے ساتھ دفن نہیں ہو گے، کیونکہ تم نے اپنی زمین تباہ کی، اور اپنے لوگوں کو قتل کیا: بدکاروں کی نسل کبھی مشہور نہیں ہوگی۔\n21۔ اپنے بچوں کے لیے ان کے باپوں کی ناانصافی کے لیے ذبح کی تیاری کرو؛ کہ وہ نہ اٹھتے ہیں، نہ زمین پر قبضہ کرتے ہیں، نہ دنیا کے چہرے کو شہروں سے بھر دیتے ہیں۔\n22۔ کیونکہ میں ان کے خلاف اٹھوں گا، خداوند لشکروں فرماتا ہے، اور بابل سے نام اور باقیات، بیٹا اور بھتیجا کاٹ دوں گا، خداوند فرماتا ہے۔\n23. میں اسے بٹن کے لیے ملکیت اور پانی کے تالاب بھی بناؤں گا: اور میں اسے تباہی کے بیس سے صاف کر دوں گا، لشکروں کے رب فرماتا ہے۔\n24۔ لشکروں کے رب نے قسم کھائی ہے اور کہا، جیسا کہ میں نے سوچا ہے، ویسا ہی ہوگا؛ اور جیسا کہ میں نے ارادہ کیا ہے، {ویسے} یہ برقرار رہے گا:\n25۔ کہ میں اپنے ملک میں آشوری کو توڑ دوں گا، اور اپنے پہاڑوں پر اس کے قدموں کے نیچے چلوں گا: پھر اس کا جوا ان سے ہٹ جائے گا، اور اس کا بوجھ ان کے کندھوں سے اتر جائے گا۔\n26. یہی وہ مقصد ہے جو پوری زمین پر مقرر کیا گیا ہے: اور یہ وہ ہاتھ ہے جو تمام قوموں پر پھیلا ہوا ہے۔\n27۔ کیونکہ لشکروں کے رب نے ارادہ کیا ہے، اور کون اسے منسوخ کرے گا؟ اور اس کا ہاتھ بڑھایا گیا ہے، اور کون اسے واپس موڑے گا؟\n28۔ جس سال بادشاہ آحاز فوت ہوئے اس بوجھ پر یہ بوجھ تھا۔\n29۔ خوش نہ ہو، پورے فلسطینینا، کیونکہ جس نے تمہیں مارا اس کی چھڑی ٹوٹ گئی ہے: کیونکہ سانپ کی جڑ سے ایک کاکٹریس نکلے گا، اور اس کا پھل ایک آگ کا اڑتا ہوا سانپ ہوگا۔ {کاکاٹریس: یا، ایڈر}\n30۔ اور غریبوں میں سے پہلا بچہ کھائے گا، اور محتاج محفوظ لیٹ جائے گا: اور میں تمہاری جڑ کو قحط سے مار دوں گا، اور وہ تمہاری باقیات کو مار ڈالے گا۔\n31۔ ہاؤل، او گیٹ؛ رو، اے شہر؛ تم، پورا فلسطین، ختم ہو چکا ہے: کیونکہ شمال سے دھواں آئے گا، اور کوئی بھی اپنے مقررہ وقت میں اکیلا نہیں ہوگا۔ {کوئی نہیں...: ورنہ، وہ اکیلا نہیں رہے گا} {مقرر...: یا، اسمبلیز}\n32. پھر قوم کے پیغامبروں کو کیا جواب دے گا؟ کہ خداوند نے صیون کی بنیاد رکھی ہے، اور اس کے لوگوں کے غریب اس پر بھروسہ کریں گے۔ {بھروسہ...: یا، خود کو اس پر قائم رکھیں}","1. موآب کا بوجھ۔ کیونکہ رات کو موآب کا آر تباہ ہو جاتا ہے، {اور} خاموش ہو جاتا ہے؛ کیونکہ رات کے وقت موآب کا کیر تباہ ہو جاتا ہے، {اور} خاموش ہو جاتا ہے؛ {لایا...: یا، کاٹ دیا}\n2۔ وہ باجیت اور دیبون، اونچی جگہوں پر چلا جاتا ہے، رونے کے لیے: موآب نیبو اور مدیبا پر چیخے گا: ان سب کے سروں پر گنجا ہوگا، اور ہر داڑھی کاٹ دی جائے گی۔\n3۔ اپنی گلیوں میں وہ تھیلے کے کپڑے پہنیں گے: اپنے گھروں کی چھتوں پر، اور اپنی گلیوں میں، ہر کوئی زور زور سے روتے ہوئے چیخے گا۔ {روتے ہوئے...: عبرانی رونے میں اترنا، یا، رونے کے ساتھ نیچے آنا}\n4۔ اور ہیشبون پکارے گا، اور علعلہ: ان کی آواز جہاز تک بھی سنی جائے گی؛ اس لیے موآب کے مسلح سپاہی پکار اٹھیں گے؛ اس کی زندگی اس کے لیے تکلیف دہ ہوگی۔\n5. میرا دل موآب کے لیے پکار رہا ہے؛ اس کے فرار ہونے والے زوار کی طرف بھاگ جائیں گے، جو تین سال کی گائے ہے: کیونکہ لوہیت پر روتے ہوئے چڑھ کر وہ اوپر جائیں گے؛ کیونکہ ہورونیم کے راستے میں وہ تباہی کی پکار اٹھائیں گے۔ {اس کی...: یا، اس کی سرحدوں تک، حتیٰ کہ زوار کے لیے، ایک گائے کی طرح} {تباہی: عبرانی۔ بریکنگ}\n6۔ کیونکہ نمرم کا پانی ویران ہو جائے گا: کیونکہ گھاس مرجھا جاتی ہے، گھاس ختم ہو جاتی ہے، کوئی سبز چیز نہیں رہتی۔ {ویران آواز: عبرانی۔ ویرانی}\n7۔ لہٰذا جو فراوانی انہیں ملی ہے، اور جو کچھ انہوں نے جمع کیا ہے، وہ بید کے ندی تک لے جائیں گے۔ {نال...: یا، عربیوں کی وادی}\n8۔ کیونکہ موآب کی سرحدوں کے گرد پکار ختم ہو چکی ہے؛ اس کی چیخیں ایگلیم کو، اور بیرلیم کو اس کی چیخیں۔\n9۔ کیونکہ دیمون کے پانی خون سے بھر جائیں گے: کیونکہ میں دیمون پر مزید شیر لاؤں گا، جو موآب سے بھاگے گا اور زمین کے باقیات پر بھی۔ {مزید: عبوری۔ اضافات}","1۔ تم بکرا کو سیلا سے بیابان تک زمین کے حکمران کو بھیجو، صیہون کی بیٹی کے پہاڑ پر۔ {سیلا: یا، پیٹرا: عبرانی۔ ایک پتھر}\n2۔ کیونکہ یہ، {و} جیسے گھونسلے سے نکالا گیا آوارہ پرندہ، {ویسے} موآب کی بیٹیاں آرنون کے گزرگاہوں پر ہوں گی۔ {cast...: یا، ایک گھونسلہ چھوڑا گیا}\n3۔ وکیل لینا، فیصلہ نافذ کرنا؛ اپنا سایہ دوپہر کے بیچ رات کی طرح بنا دے؛ بے گھر لوگوں کو چھپانا؛ جو بھٹکتا ہے اس پر نظر نہ رکھو۔ {ٹیک: عبوری۔ لے آؤ}\n4۔ میرے بے گھر لوگوں کو تیرے ساتھ رہنے دو، موآب؛ تم ان کے سامنے ایک چھپاؤ بنو جو خراب کرنے والے کے چہرے پر ہو: کیونکہ بلیک خور ختم ہو چکا ہے، خراب کرنے والا رک جاتا ہے، ظالم زمین سے نکال دیے جاتے ہیں۔ {بھتہ خور: عبرانی۔ wringer} {دی آپریسرز: عبرانی ٹریڈرز ڈاؤن}\n5۔ اور رحمت میں تخت قائم کیا جائے گا: اور وہ اس پر سچائی سے داؤد کے خیمے میں بیٹھے گا، فیصلہ کرے گا، فیصلہ کرے گا، اور نیکی کی جلدی کرے گا۔ {قائم: یا، تیار}\n6۔ ہم نے موآب کے غرور کے بارے میں سنا ہے؛ {و} بہت فخر کرتا ہے: {حتی} اپنی تکبر، غرور اور غصے پر بھی: {لیکن} اس کے جھوٹ {نہیں ہوں گے}\n7۔ اسی لیے موآب موآب کے لیے چلائے، سب چیخیں گے: کیونکہ کیرارسیت کی بنیادوں پر تم ماتم کرو گے؛ یقینا {وہ} متاثر ہوں گے۔ {ماتم کرنا: یا، بڑبڑانا}\n8۔ کیونکہ ہیشبون کے کھیت زوال پذیر ہیں، {اور} سیبمہ کی انگور: کافروں کے سرداروں نے ان کے اہم پودے توڑ دیے ہیں، وہ یازر تک پہنچ چکے ہیں، وہ بیابان میں بھٹکتے رہے: اس کی شاخیں پھیلی ہوئی ہیں، وہ سمندر کے پار جا چکی ہیں۔ {کھینچی...: یا، اٹھا کر}\n9۔ اسی لیے میں یازر کے رونے سے سبمہ کی بیل کا رونا مناؤں گا: اے حشبون، اور ایلیالہ، میں اپنے آنسوؤں سے تمہیں پانی دوں گا: کیونکہ تمہارے موسم گرما کے پھلوں اور تمہاری فصل کے گرنے کے لیے پکار رہی ہے۔ {چیخ و پکار...: یا، الارم لگا ہوا ہے، وغیرہ}\n10۔ اور خوشی چھین لی جاتی ہے، اور خوشی فراوان میدان سے نکل جاتی ہے؛ اور انگور کے باغات میں کوئی گانا نہیں ہوگا، نہ چیخ و پکار ہوگی: چلنے والے اپنے پریس میں شراب نہیں چلائیں گے؛ میں نے {ان کے پرانے} شور کو بند کر دیا ہے۔\n11۔ اسی لیے میری آنتیں موآب کے لیے ہارپ کی طرح سنائی دیں گی، اور میرے اندرونی حصے کرہاریش کے لیے۔\n12۔ اور جب یہ دیکھا جائے گا کہ موآب اونچی جگہ پر تھکا ہوا ہے، تو وہ اپنے مقدس مقام پر دعا کے لیے آئے گا؛ لیکن وہ کامیاب نہیں ہوگا۔\n13. یہ وہ کلام ہے جو خداوند نے اس وقت سے موآب کے بارے میں کہا ہے۔\n14۔ لیکن اب خداوند نے فرمایا ہے، کہتا ہے، تین سال کے اندر، جیسے مزدور کے سال اور موآب کی شان کو اس عظیم کثرت کے ساتھ منسوخ کیا جائے گا؛ اور باقی ماندہ {بہت چھوٹا} {اور} کمزور ہوگا۔ {کمزور: یا، زیادہ نہیں}","1. دمشق کا بوجھ۔ دیکھو، دمشق کو {شہر} سے چھین لیا گیا ہے، اور یہ ایک تباہ کن ڈھیر بن جائے گا۔\n2۔ آروئر کے شہر چھوڑ دیے گئے ہیں: وہ ریوڑ کے لیے ہوں گے، جو لیٹیں گے، اور کوئی انہیں خوفزدہ نہیں کرے گا۔\n3۔ قلعہ بھی افرایم سے ختم ہو جائے گا، اور سلطنت دمشق سے، اور شام کے باقیات سے: وہ سب بنی اسرائیل کی شان کی طرح ہوں گے، لشکروں کے رب فرماتا ہے۔\n4۔ اور اسی دن یہ ہو جائے گا، {کہ} یعقوب کی شان پتلی ہو جائے گی، اور اس کے جسم کی چربی پتلی ہو جائے گی۔\n5۔ اور ایسا ہی ہوگا جیسے فصل کاٹنے والا اناج جمع کرے اور اپنے بازو سے کان کاٹے؛ اور یہ ویسا ہی ہوگا جیسے وہ ریفائیم کی وادی میں کان جمع کرتا ہے۔\n6۔ پھر بھی اس میں انگور اگنے والے چھوڑے جائیں گے، جیسے زیتون کے درخت کی ہلچل سے، سب سے اوپر والی شاخ کے اوپر دو یا تین بیریز ہوں گے، اور اس کی سب سے زیادہ پھلدار شاخوں میں چار یا پانچ پھل دار شاخوں میں ہوں گے، خداوند اسرائیل کا فرماتا ہے۔\n7۔ اس دن آدمی اپنے خالق کی طرف دیکھے گا، اور اس کی آنکھیں اسرائیل کے مقدس وجود کی عزت کریں گی۔\n8۔ اور وہ قربان گاہوں کی طرف نہیں دیکھے گا، جو اس کے ہاتھوں کا کام ہے، اور نہ ہی اس کی عزت کرے گا جو اس کی انگلیوں نے بنائی ہے، چاہے وہ جھنڈ ہوں یا مجسمے۔ {تصاویر: یا، سورج کی تصاویر}\n9۔ اس دن اس کے مضبوط شہر ایک ترک شدہ شاخ اور سب سے اوپر کی شاخ کی طرح ہوں گے، جو انہوں نے بنی اسرائیل کی وجہ سے چھوڑ دی تھی: اور وہاں ویرانی ہوگی۔\n10۔ کیونکہ تم نے اپنی نجات کے خدا کو بھلا دیا ہے، اور اپنی طاقت کی چٹان کا خیال نہیں رکھا، اس لیے تم خوبصورت پودے لگاؤ گے، اور اسے عجیب و غریب پھسلوں کے ساتھ سجائیں گے:\n11۔ دن میں تم اپنے پودے کو اگاؤ گے، اور صبح اپنے بیج کو پھولو گے: {لیکن} فصل غم اور غم کے دن ایک ڈھیر ہوگی۔ {ایک ڈھیر...: یا، وراثت کے دن ہٹا دیا جائے، اور وہاں مہلک غم ہوگا}\n12۔ افسوس، بہت سے لوگوں پر جو سمندر کی آواز کی طرح شور کرتے ہیں؛ اور قوموں کی دوڑ کے لیے، {جو} ایک بہاؤ کو عظیم پانیوں کی بہاؤ کی طرح بناتی ہے! {کثیر: یا، شور} {طاقتور: یا، بہت سے}\n13۔ قومیں ایسے دوڑیں گی جیسے کئی پانیوں کی بہاؤ: لیکن {خدا} انہیں ڈانٹے گا، اور وہ دور دور بھاگ جائیں گے، اور پہاڑوں کی کھال کی طرح ہوا کے سامنے اور طوفان کے سامنے گھومتی ہوئی چیز کی طرح پیچھا کیے جائیں گے۔ {ایک رولنگ...: یا، تھسل ڈاؤن}\n14۔ اور دیکھو شام کی مد کے وقت مصیبت؛ {اور} صبح سے پہلے وہ {نہیں} ہے۔ یہی وہ حصہ ہے جو ہمیں بگاڑتا ہے، اور وہ سب جو ہمیں لوٹتے ہیں۔","1. اس سرزمین پر افسوس جو پروں سے سایہ دار ہے، جو ایتھوپیا کی ندیوں کے پار ہے:\n2۔ جو سمندر کے راستے سفیر بھیجتا ہے، حتیٰ کہ پانی پر بلرش کے جہازوں میں بھی، {کہتا ہے}، اے تیز پیغامبروں، ایک ایسی قوم کی طرف جاؤ جو بکھری ہوئی اور چھلکی ہوئی ہے، ایک ایسی قوم کے پاس جو اپنی ابتدا سے ہی خوفناک تھی؛ ایک قوم جسے سزا دی گئی اور روند دی گئی، جس کی زمین کو دریاؤں نے برباد کیا! {بکھرا ہوا...: یا، پھیلا ہوا اور پالش کیا گیا} {meted...: یا، جو باہر نکلتا ہے اور نیچے آتا ہے: عبرانی۔ لائن، لائن، اور قدموں کے نیچے چلنے کی} {have...: or, desdesse}\n3۔ اے تمام دنیا کے باشندے اور زمین پر رہنے والے، دیکھو جب وہ پہاڑوں پر پرچم اٹھاتا ہے؛ اور جب وہ بگل بجائے تو سنو۔\n4۔ کیونکہ خداوند نے مجھ سے کہا، میں آرام کروں گا، اور اپنے گھر میں جڑی بوٹیوں پر صاف گرمی کی طرح محسوس کروں گا، {اور} فصل کی گرمی میں شبنم کے بادل کی طرح۔ {غور کریں...: یا، میرے گھر کو دیکھیں} {اوپر...: یا، بارش کے بعد}\n5۔ فصل سے پہلے، جب کلی مکمل ہو جائے اور کھٹا انگور پھول میں پک رہا ہو، تو وہ کانٹے تراشنے کے کانٹے سے ٹہنیاں کاٹے گا اور شاخیں کاٹے گا۔\n6۔ انہیں پہاڑوں کے پرندوں اور زمین کے جانوروں کے لیے ایک ساتھ چھوڑ دیا جائے گا، اور پرندے ان پر موسم گرما گزاریں گے، اور زمین کے تمام جانور ان پر سردیوں میں گزاریں گے۔\n7۔ اس وقت تحفہ خداوند کے سامنے لایا جائے گا، ایک ایسی قوم کی فوجوں کی جو بکھری ہوئی اور اترتی ہوئی ہے، اور ایک ایسی قوم سے جو ابتدا سے اب تک خوفناک رہی ہے؛ ایک قوم جو پیدل چلتی رہی، جس کی زمین کو دریاؤں نے برباد کیا، رب لشکروں کے نام کی جگہ پر پہنچتی ہے، جو پہاڑ صیون ہے۔ {بکھرا ہوا...: یا، پھیلا ہوا اور پالش کیا گیا}","1. مصر کا بوجھ۔ دیکھو، خداوند ایک تیز بادل پر سوار ہے، اور مصر میں آئے گا: اور مصر کے بتوں کو اس کی موجودگی میں حرکت دی جائے گی، اور مصر کا دل اس کے بیچ پگھل جائے گا۔\n2۔ اور میں مصریوں کو مصریوں کے خلاف کھڑا کروں گا: اور وہ سب کو اس کے بھائی کے خلاف لڑیں گے، اور ہر ایک کو اپنے پڑوسی کے خلاف؛ شہر کے مقابلے میں شہر، {اور} سلطنت کے خلاف بادشاہت۔ {سیٹ: عبرانی منڈل}\n3۔ اور مصر کی روح اس کے درمیان ناکام ہو جائے گی؛ اور میں اس کی نصیحت کو ختم کر دوں گا: اور وہ بتوں، جادوگروں، اور جن کی روحیں مانوس ہیں، اور جادوگروں کی طرف رجوع کریں گے۔ {ناکام: عبرانی خالی ہو جاؤ} {تباہ: عبرانی۔ نگل لو}\n4۔ اور مصریوں کو میں ایک ظالم سردار کے حوالے کر دوں گا؛ اور ایک سخت بادشاہ ان پر حکومت کرے گا، خداوند فرماتا ہے، رب لشکروں سے۔ {دو...: یا، چپ ہو جاؤ}\n5۔ اور پانی سمندر سے بہہ جائے گا، اور دریا ضائع اور خشک ہو جائے گا۔\n6۔ اور وہ دریاؤں کو دور موڑ دیں گے؛ {اور} دفاع کی ندیاں خالی اور خشک ہو جائیں گی: سرکنڈے اور جھنڈے مرجھا جائیں گے۔\n7۔ کاغذی سرکنڈے ندیوں کے پاس، ندیوں کے دہانے کے پاس، اور جو کچھ ندی ندیوں کے بوئے گا، مرجھا جائے گا، دور جائے گا، اور {اب} نہیں رہے گا۔ {اور ہو...: عبرانی۔ اور ایسا نہیں ہوگا}\n8۔ ماہی گیر بھی سوگ منائیں گے، اور جو بھی ندیوں میں زاویہ ڈالے گا وہ ماتم کرے گا، اور جو پانیوں پر جال بچھائیں گے وہ کمزور پڑ جائیں گے۔\n9۔ مزید برآں، جو باریک فلیکس میں کام کرتے ہیں اور جو جال بنتے ہیں، وہ الجھ جائیں گے۔ {نیٹ ورکس: یا، وائٹ ورکس}\n10۔ اور وہ سب جو مچھلی کے لیے سلوئس بناتا ہے {اور} تالابوں کے لیے اس مقصد کے لیے توڑ دیا جائے گا۔ {مقاصد: عبرانی۔ بنیادیں} {مچھلی کے لیے: عبرانی۔ زندہ چیزوں کا\n11. یقینا زوان کے شہزادے بیوقوف ہیں، فرعون کے دانا مشیروں کی نصیحت سخت ہو گئی ہے: تم فرعون سے کیا کہتے ہو، میں {ہوں} دانا کا بیٹا، قدیم بادشاہوں کا بیٹا؟\n12۔ وہ کہاں ہیں؟ تمہارے عقلمند کہاں ہیں؟ اور اب وہ تمہیں بتائیں، اور بتائیں کہ رب لشکروں نے مصر پر کیا ارادہ کیا ہے۔\n13۔ زوان کے شہزادے بیوقوف بن جاتے ہیں، نوف کے شہزادے دھوکہ کھا جاتے ہیں؛ انہوں نے مصر کو بھی بہکایا ہے، {یہاں تک کہ} کہ وہ قبائل بھی ہیں جو اس کے قیاد ہیں۔ {وہ جو...: یا، گورنرز: عبرانی کارنرز}\n14۔ خداوند نے ان کے درمیان ایک بگڑی ہوئی روح کو ملا دیا ہے: اور انہوں نے مصر کو ہر کام میں غلطی پر مجبور کیا، جیسے نشے میں دھت انسان اپنی قے میں لڑکھڑاتا ہے۔ {ایک منحرف...: عبرانی۔ انحرافات کی روح}\n15. مصر کے لیے کوئی {کوئی} کام نہیں ہوگا، جو سر یا دم، شاخ یا دوڑ کر سکتا ہے۔\n16۔ اس دن مصر عورتوں جیسا ہوگا: اور وہ خداوند لشکروں کے ہاتھ کے مصافحے کی وجہ سے خوفزدہ اور خوفزدہ ہوگا، جسے وہ اس پر مصافحہ کرتا ہے۔\n17۔ اور یہوداہ کی سرزمین مصر کے لیے خوف ہوگی، جو بھی اس کا ذکر کرے گا وہ اپنے آپ میں خوفزدہ ہو جائے گا، کیونکہ رب لشکروں کی نصیحت کی وجہ سے جو اس نے اس کے خلاف مقرر کی ہے۔\n18۔ اس دن مصر کی سرزمین کے پانچ شہر کنعان کی زبان بولیں گے، اور لشکروں کے رب کی قسم کھائیں گے؛ ایک کو تباہی کا شہر کہا جائے گا۔ {زبان: عبوری۔ ہونٹ} {تباہی کا: یا، ہیرس کا، یا، سورج کا}\n19۔ اس دن مصر کی سرزمین کے بیچ خداوند کے لیے ایک قربان گاہ ہوگی، اور اس کے کنارے خداوند کے لیے ایک ستون ہوگا۔\n20۔ اور یہ ایک نشانی اور مصر کی سرزمین میں لشکروں کے رب کے سامنے گواہی کے لیے ہوگا، کیونکہ وہ ظلم کرنے والوں کی وجہ سے خداوند سے پکاریں گے، اور وہ انہیں ایک نجات دہندہ اور عظیم بھیجے گا، اور وہ انہیں نجات دے گا۔\n21۔ اور خداوند مصر کے لیے جانا جائے گا، اور مصری اس دن خداوند کو جانیں گے، اور قربانی اور قربانی دیں گے؛ ہاں، وہ خداوند کے لیے قسم کھائیں گے، اور اسے پورا کریں گے۔\n22۔ اور خداوند مصر کو مارے گا: وہ اسے مارے گا اور شفا دے گا، اور وہ دوبارہ خداوند کے پاس واپس آئیں گے، اور وہ ان سے دعا کرے گا اور انہیں شفا دے گا۔\n23۔ اس دن مصر سے آشور تک ایک شاہراہ ہوگی، اور آشوری مصر میں آئیں گے، اور مصری آشور میں، اور مصری آشوریوں کے ساتھ خدمت کریں گے۔\n24۔ اس دن اسرائیل مصر اور آشور کے ساتھ تیسرا ہوگا، {حتیٰ کہ} زمین کے بیچ میں ایک برکت بھی:\n25۔ جسے لشکروں کا رب برکت دے گا، کہے، مبارک ہو مصر میرے لوگ، اور آشور کو میرے ہاتھوں کا کام، اور اسرائیل میری میراث ہو۔","1۔ اس سال جب تارتان اشدود آیا، (جب آشور کے بادشاہ سرگون نے اسے بھیجا)، اور اشدود کے خلاف لڑا اور اسے فتح کیا؛\n2۔ اسی وقت خداوند نے اموز کے بیٹے یسعیاہ کے ذریعے فرمایا، کہا کہ جاؤ اور اپنی کمر سے تھیلی کا کپڑا اتار دو، اور اپنے جوتے کو اپنے پاؤں سے اتار دو۔ اور اس نے ایسا کیا، ننگے اور ننگے پاؤں چلتے ہوئے۔ {بذریعہ: عبرانی ہاتھوں سے}\n3۔ اور خداوند نے فرمایا، جیسے میرا خادم یسعیاہ تین سال ننگے اور ننگے پاؤں چل رہا ہے {کیونکہ مصر اور ایتھوپیا پر ایک معجزہ اور معجزہ ہے؛\n4. اسی طرح آشور کا بادشاہ مصریوں کو قیدیوں اور ایتھوپیا کے قیدیوں، جوان اور بوڑھے، ننگے اور ننگے پاؤں لے جائے گا، یہاں تک کہ ان کے کولہوں کے بغیر بھی، مصر کی شرمندگی کے لیے۔ {مصری...: عبرانی۔ مصر کی قید} {شرم کی بات ہے: عبرانی۔ ننگا پن}\n5۔ اور وہ ایتھوپیا سے اپنی توقعات اور مصر کی شان سے ڈریں گے اور شرمندہ ہوں گے۔\n6۔ اور اس جزیرے کے باشندے اس دن کہیں گے، دیکھو، یہی ہماری توقع ہے، جہاں ہم مدد کے لیے بھاگ رہے ہیں تاکہ آشور کے بادشاہ سے بچ سکیں: اور ہم کیسے بچیں گے؟ {جزیرہ: یا، ملک}","1۔ سمندر کے صحرا کا بوجھ۔ جب جنوب میں طوفان گزرتے ہیں؛ {تو} یہ صحرا سے آیا ہے، ایک خوفناک زمین سے۔\n2۔ ایک خوفناک خواب میرے سامنے آتا ہے؛ دھوکہ باز ڈیلر دھوکہ دہی کرتا ہے، اور سپوائلر خراب کرتا ہے۔ اوپر جاؤ، اے ایلام: محاصرہ، اے میڈیا؛ اس کی ساری آہیں میں نے روک دی ہیں۔ {گریویس: عبدی۔ مشکل}\n3۔ اسی لیے میری کمر درد سے بھر گئی ہے: درد نے مجھ پر قبضہ کر لیا ہے، جیسے کسی عورت کے درد جو تڑپتی ہے: میں اس کی سماعت پر جھک گیا تھا؛ مجھے یہ دیکھ کر مایوسی ہوئی۔\n4۔ میرا دل دھڑک اٹھا، خوف نے مجھے ڈرا دیا: میری خوشی کی رات وہ میرے لیے خوف میں بدل گئی۔ {دل...: یا، ذہن بھٹک گیا} {مڑا: عببرانی۔ رکھو}\n5۔ میز تیار کرو، نگرانی کے مینار میں نگرانی کرو، کھاؤ، پیو: اٹھو، اے شہزادوں، {اور} ڈھال کو مسح کرو۔\n6۔ کیونکہ خداوند نے مجھ سے یہی فرمایا، جاؤ، ایک چوکیدار مقرر کرو، جو وہ دیکھتا ہے وہ بیان کرے۔\n7۔ اور اس نے ایک رتھ دیکھی جس میں دو سوار تھے، گدھوں کا ایک رتھ، اور اونٹوں کا ایک رتھ؛ اور اس نے پوری توجہ سے سنا:\n8۔ اور اس نے پکارا، ایک شیر: میرے آقا، میں دن کے وقت مسلسل نگرانی کے مینار پر کھڑا رہتا ہوں، اور ساری راتیں اپنی حفاظت میں رہتا ہوں: {وہ...: یا، شیر کی طرح پکارتا ہے} {مکمل...: یا، ہر رات}\n9۔ اور دیکھو، مردوں کا ایک رتھ آ رہا ہے، {ساتھ} دو گھڑ سواروں کے ساتھ۔ اور اس نے جواب دیا اور کہا، بابل گر چکا ہے، گر چکا ہے؛ اور اس کے دیوتاؤں کی تمام کندہ شدہ تصاویر کو اس نے زمین پر توڑ دیا ہے۔\n10۔ اے میری تھریشنگ، اور میرے فرش کی داہ: جو کچھ میں نے رب لشکروں، اسرائیل کے خدا کے بارے میں سنا ہے، میں نے تم سے اعلان کیا ہے۔ {کارن: عبوری۔ بیٹا}\n11۔ دومہ کا بوجھ۔ وہ مجھے سیئر سے بلاتا ہے، واچ مین، رات کا کیا ہوا؟ واچ مین، رات کا کیا ہوا؟\n12۔ چوکیدار نے کہا، صبح آتی ہے، اور رات بھی: اگر تم پوچھو تو پوچھو: واپس آؤ، آؤ۔\n13۔ عرب پر بوجھ۔ عرب کے جنگل میں تم رہو گے، اے دیدانیم کے مسافر گروہوں کو۔\n14۔ تیما کی سرزمین کے باشندے پیاسے کو پانی لاتے تھے، اور اپنی روٹی سے فرار ہونے والے کو روک دیتے تھے۔ {لایا گیا: یا، لے آؤ}\n15۔ کیونکہ وہ تلواروں، نکالی ہوئی تلوار، جھکی ہوئی کمان سے، اور جنگ کی شدت سے بھاگ گئے۔ {تلواروں سے: یا، خوف کے لیے، وغیرہ: عبرانی۔ چہرے سے وغیرہ}\n16۔ کیونکہ خداوند نے مجھ سے یوں کہا ہے، ایک سال کے اندر، مزدور کی عمر کے مطابق، اور کیدار کی ساری شان ختم ہو جائے گی:\n17۔ اور تیر اندازوں کی تعداد کی باقیات کم ہو جائے گی، جو کیدار کے بچوں کے طاقتور آدمیوں تھے، کیونکہ خداوند خدا اسرائیل نے کہا ہے۔ {تیر انداز: عبرانی جھکاؤ}","1. وادی بصارت کا بوجھ۔ اب تمہیں کیا ہوا ہے کہ تم مکمل طور پر گھروں کی چھتوں تک پہنچ گئے ہو؟\n2. تم جو ہنگامے سے بھرے ہو، ایک ہنگامہ خیز شہر، ایک خوشی بھرا شہر: تیرے مارے گئے {لوگ} تلوار سے مارے نہیں گئے، نہ ہی جنگ میں مارے گئے۔\n3. تمہارے تمام حکمران ایک ساتھ بھاگ گئے، وہ تیر اندازوں کے بندھے ہوئے ہیں: جو کچھ تم میں پایا جاتا ہے وہ ایک دوسرے سے بندھا ہوا ہے، {جو} دور سے بھاگے ہیں۔ {بذریعہ...: عبرانی۔ کمان کا}\n4۔ لہٰذا میں نے کہا، مجھ سے دور دیکھو؛ میں تلخی سے روؤں گا، مجھے تسلی دینے کی کوشش نہیں کروں گا، کیونکہ میری قوم کی بیٹی نے بگاڑ دیا ہے۔ {رونا...: عبرانی۔ روتے ہوئے تلخ ہو جاؤ}\n5۔ کیونکہ یہ مصیبتوں کا دن ہے، اور خدا خدا کی طرف سے وادی میں لشکروں کی الجھن، دیواریں توڑنے، اور پہاڑوں کی طرف پکار کرنے کا دن ہے۔\n6۔ اور ایلام نے آدمیوں اور گھڑ سواروں کے رتھ کے ساتھ ترکش اٹھایا، اور کر نے ڈھال کھولی۔ {بے پردہ: عبوری۔ برہنہ بنایا گیا}\n7۔ اور یہ ہو جائے گا کہ تمہاری پسندیدہ وادیاں رتھوں سے بھری ہوں گی، اور گھڑ سوار دروازے پر قطار میں کھڑے ہوں گے۔ {تمہاری...: عببری۔ تیری وادیوں کا انتخاب} {AT: یا، کی طرف}\n8۔ اور اس نے یہوداہ کا پردہ دریافت کیا، اور اس دن تم نے جنگل کے گھر کی زرہ کو دیکھا۔\n9۔ تم نے داؤد کے شہر کی دراڑیں بھی دیکھی ہیں، جو بہت زیادہ ہیں: اور تم نے نچلے تالاب کے پانی کو جمع کیا۔\n10۔ اور تم نے یروشلم کے گھروں کو گنا ہے، اور ان گھروں کو دیوار کو مضبوط کرنے کے لیے توڑ دیا ہے۔\n11۔ تم نے پرانے تالاب کے پانی کے لیے دونوں دیواروں کے درمیان ایک کھائی بھی بنائی: لیکن تم نے اس کے بنانے والے کی طرف نہیں دیکھا، نہ ہی اس کی عزت کی جس نے اسے بہت پہلے بنایا تھا۔\n12۔ اور اسی دن لشکروں کے خداوند خدا نے رونے، سوگ، گنج پن اور تھیلے کے کپڑے پہننے کی دعوت دی:\n13۔ اور دیکھو خوشی اور خوشی، بیل مارنا، بھیڑیں مارنا، گوشت کھانا اور شراب پینا: آؤ کھائیں اور پیئیں؛ کیونکہ کل ہم مر جائیں گے۔\n14۔ اور میرے کانوں میں لشکروں کے رب نے ظاہر کیا، یقینا یہ گناہ تم سے پاک نہیں ہوگا جب تک تم مر نہ جاؤ، خداوند خدا لشکروں کا فرماتا ہے۔\n15. یوں فرماتا خداوند خدا لشکروں کے لیے، جاؤ، اس خزانے دار کے پاس جاؤ، {حتی} شبنا کے پاس بھی، جو {گھر} پر ہے، {اور کہو}،\n16. یہاں کیا ہے؟ اور یہاں کون ہے، جس نے یہاں قبر تراشی ہے، {ویسے} جیسے وہ اسے اونچی قبر بناتا ہے، {اور} اپنے لیے چٹان میں رہائش بناتا ہے؟ {جیسے...: یا، او ہی}\n17۔ دیکھو، خداوند تمہیں ایک زبردست قید میں لے جائے گا، اور یقینا تمہیں ڈھانپے گا۔ {اٹھائے گا...: یا، جس نے تمہیں خوبصورت چادر سے ڈھانپ دیا، اور تمہیں خوبصورت لباس پہنایا، (اگلا مصرعہ) یقینا کرے گا، وغیرہ} {ایک زبردست...: عبرانی۔ ایک آدمی کی قید}\n18۔ وہ یقینا زور سے پلٹے گا اور تمہیں ایک بڑے ملک میں گیند کی طرح پھینکے گا: وہاں تم مر جاؤ گے، اور وہاں تمہاری عظمت کی رتھ تمہارے آقا کے گھرانے کی شرمندگی ہوں گی۔ {بڑا: عبوری۔ بڑی جگہیں\n19۔ اور میں تمہیں تمہاری حالت سے نکالوں گا، اور وہ تمہیں نیچے کھینچے گا۔\n20۔ اور اسی دن میں اپنے خادم الیاکیم کو حلقیاہ کا بیٹا کہوں گا:\n21۔ اور میں اسے تمہاری چادر پہناؤں گا، اپنی بیلٹ سے مضبوط کروں گا، اور تمہاری حکومت اس کے ہاتھ میں سونپ دوں گا: اور وہ یروشلم کے باشندوں اور یہوداہ کے گھر کا باپ بنے گا۔\n22۔ اور داؤد کے گھر کی چابی میں اس کے کندھے پر رکھوں گا؛ تو وہ کھولے گا، اور کوئی بند نہیں ہوگا؛ اور وہ بند ہو جائے گا، اور کوئی نہیں کھلے گا۔\n23۔ اور میں اسے ایک مضبوط جگہ پر کیل کی طرح باندھ دوں گا؛ اور وہ اپنے والد کے گھر کے لیے شاندار تخت کے لیے ہوگا۔\n24۔ اور وہ اس پر اس کے والد کے گھرانے کی تمام عظمت، اولاد اور اولاد کی تمام چھوٹی مقدار کے برتن، پیالے کے برتنوں سے لے کر تمام فلیگن کے برتنوں تک لٹکائیں گے۔ {فلگونز کے برتن: یا، وائلز کے آلات}\n25۔ اس دن، لشکروں کے رب فرماتا ہے، جو کیل اس جگہ پر لگا ہوا ہے اسے ہٹایا جائے گا، کاٹا جائے گا اور گر جائے گا؛ اور جو بوجھ اس پر تھا اسے کاٹ دیا جائے گا: کیونکہ خداوند نے کہا ہے۔","1۔ صور کا بوجھ۔ چلاؤ، اے ترشیش کے جہازوں؛ کیونکہ وہ تباہ ہو چکا ہے، یہاں تک کہ کوئی گھر نہیں، کوئی داخلہ نہیں: چتیم کی زمین سے یہ ان پر ظاہر ہوتا ہے۔\n2. خاموش رہو، اے جزیرے کے باشندو؛ تم جسے زیدون کے تاجروں نے، جو سمندر پار سے گزرتے ہیں، دوبارہ بھر دیا ہے۔ {اب بھی: عبرانی۔ خاموش}\n3۔ اور عظیم پانیوں سے سیہور کا بیج، دریا کی فصل، اس کی آمدنی ہے؛ اور وہ ایک مارٹ آف نیشنز ہے۔\n4۔ اے زیدون، شرم کرو، کیونکہ سمندر نے سمندر کی طاقت کو بھی کہا ہے، کہہ رہا ہوں، میں نہ تنگ کرتا ہوں، نہ بچے پیدا کرتا ہوں، نہ جوانوں کو پالتا ہوں، نہ کنواریوں کی پرورش کرتا ہوں۔\n5۔ جیسے مصر کی رپورٹ میں، {ویسے} وہ صور کی رپورٹ پر شدید دکھ محسوس کریں گے۔\n6۔ ترشیش کو منتقل کرو؛ آؤ، اے جزیرے کے باشندو۔\n7. {کیا} یہ آپ کا خوش {شہر} ہے، جس کی قدامت {قدیم زمانوں} کی ہے؟ اس کے اپنے قدم اسے دور لے جائیں گے تاکہ وہ وہاں قیام کرے۔ {دور سے...: عبرانی۔ دور سے}\n8۔ کس نے یہ مشورہ صور کے خلاف لیا ہے، تاج پوش {شہر}، جس کے تاجر {ہیں} شہزادے، جن کے اسمگلرز {زمین} کے معزز ہیں؟\n9۔ لشکروں کے رب نے یہ ارادہ کیا ہے کہ وہ تمام جلال کے غرور کو داغدار کرے، {اور} زمین کے تمام معزز لوگوں کو حقیر کرے۔ {داغ لگانے کے لیے: عبوری۔ آلودہ کرنا}\n10. اے ترشیش کی بیٹی، اپنی سرزمین سے دریا کی طرح گزرو: {اب کوئی طاقت نہیں}۔ {طاقت: عبرانی۔ گرڈل}\n11۔ اس نے سمندر پر ہاتھ بڑھایا، بادشاہتوں کو ہلایا: خداوند نے تاجر {شہر} کے خلاف حکم دیا ہے کہ وہ اس کے مضبوط قلعے تباہ کر دے۔ {خلاف...: یا، ایک تاجر جہاز کے بارے میں} {تاجر شہر: عبرانی کنعان} {مضبوط...: یا، طاقتیں}\n12۔ اور اس نے کہا، اے مظلوم کنواری، زیدون کی بیٹی، اب تم خوش نہ ہو: اٹھو، چتیم کی طرف چلی جاؤ؛ وہاں بھی تمہیں آرام نہیں ملے گا۔\n13۔ کلدانیوں کی زمین دیکھو؛ یہ لوگ نہیں تھے، {جب تک }آشوری نے اسے ان کے لیے قائم نہ کیا جو بیابان میں رہتے تھے: انہوں نے وہاں کے مینار بنائے، ان کے محل تعمیر کیے؛ {اور} اس نے اسے برباد کر دیا۔\n14. اے ترشیش کے جہازوں کو چلانے کی آواز: کیونکہ تمہاری طاقت تباہ ہو گئی ہے۔\n15۔ اور اسی دن یہ ہوگا کہ صور ستر سال بھلا دیا جائے گا، ایک بادشاہ کے دنوں کے مطابق: ستر سال کے بعد صور ایک بدکار کی طرح گائے گا۔ {کیا صور...: عبرانی۔ یہ صور کے لیے ایک طوائف کے گیت کی طرح ہوگا}\n16۔ ہارپ لے کر شہر میں گھومو، اے بھولی ہوئی بدکار عورت؛ میٹھا دھن بنائیں، بہت سے گانے گائیں، تاکہ آپ کو یاد رکھا جائے۔\n17۔ اور ستر سال مکمل ہونے کے بعد یہ ہوگا کہ خداوند صور آئے گا، اور وہ اپنی مزدوری کی طرف رجوع کرے گی، اور زمین پر دنیا کی تمام بادشاہتوں کے ساتھ کرے گی۔\n18۔ اور اس کا سامان اور اس کا اجرت خداوند کے لیے پاکیزگی ہوگی: نہ تو اسے سنبھالا جائے گا اور نہ ہی رکھا جائے گا؛ کیونکہ اس کا سامان ان لوگوں کے لیے ہوگا جو خداوند کے حضور بستے ہیں، تاکہ وہ کافی کھائیں اور پائیدار لباس کے لیے۔ {پائیدار: عبوری۔ پرانا}","1۔ دیکھو، خداوند زمین کو خالی کر دیتا ہے، اسے برباد کر دیتا ہے، اسے الٹ پلٹ کر دیتا ہے، اور اس کے باشندوں کو باہر بکھیر دیتا ہے۔ {turneth...: عبرانی۔ اس کے چہرے کو بگاڑ دیتا ہے}\n2۔ اور یہ لوگوں کی طرح، پادری کے ساتھ بھی ہوگا؛ جیسے نوکر کے ساتھ ہوتا ہے، ویسے ہی اپنے مالک کے ساتھ؛ جیسے نوکرانی کے ساتھ، ویسے ہی اس کی مالکن کے ساتھ؛ جیسے خریدار کے ساتھ ہوتا ہے، ویسے ہی بیچنے والے کے ساتھ بھی؛ جیسے قرض دہندہ کے ساتھ ہوتا ہے، ویسے ہی قرض لینے والے کے ساتھ بھی؛ جیسے سود لینے والے کے ساتھ، ویسے ہی سود دینے والے کے ساتھ۔ {پادری: یا، شہزادہ}\n3۔ زمین مکمل طور پر خالی اور مکمل طور پر برباد ہو جائے گی: کیونکہ خداوند نے یہ کلام کہا ہے۔\n4۔ زمین سوگ مناتی ہے {اور} مٹ جاتی ہے، دنیا سست ہو جاتی ہے {اور} مدھم ہو جاتی ہے، زمین کے مغرور لوگ زوال پذیر ہوتے ہیں۔ {مغرور...: عبرانی۔ لوگوں کی بلندی}\n5۔ زمین بھی اس کے باشندوں کے نیچے آلودہ ہے؛ کیونکہ انہوں نے قوانین کی خلاف ورزی کی، حکم بدل دیا، اور ابدی عہد توڑا۔\n6۔ اسی لیے لعنت نے زمین کو نگل لیا ہے، اور اس میں رہنے والے ویران ہیں، اس لیے زمین کے باشندے جل جاتے ہیں اور چند لوگ باقی رہ جاتے ہیں۔\n7۔ نئی شراب سوگوار ہوتی ہے، بیل کمزور پڑ جاتی ہے، سب خوش مزاج آہ بھرتے ہیں۔\n8۔ ٹیبریٹس کی خوشی رک جاتی ہے، خوش ہونے والوں کی شور ختم ہو جاتی ہے، ہارپ کی خوشی ختم ہو جاتی ہے۔\n9۔ وہ گانے کے ساتھ شراب نہیں پئیں گے؛ جو اسے پیتے ہیں ان کے لیے تیز مشروب کڑوا ہوگا۔\n10۔ انتشار کا شہر ٹوٹ جاتا ہے: ہر گھر بند کر دیا جاتا ہے تاکہ کوئی آدمی اندر نہ آ سکے۔\n11۔ سڑکوں پر شراب کی پکار ہے؛ ساری خوشی مدھم ہو جاتی ہے، زمین کی خوشی ختم ہو جاتی ہے۔\n12۔ شہر میں ویران رہ گیا ہے، اور دروازہ تباہی سے بھر گیا ہے۔\n13۔ جب یہ زمین کے بیچ میں لوگوں کے درمیان ہوگا، {ایسا ہوگا} جیسے زیتون کے درخت کی ہلچل ہو، {اور} انگور اگنے کے بعد جب شراب ختم ہو جائے۔\n14۔ وہ اپنی آواز بلند کریں گے، خداوند کی عظمت کے لیے گائیں گے، وہ سمندر سے بلند آواز میں پکاریں گے۔\n15۔ لہٰذا تم آگ میں خداوند کی جلال کرو، {حتیٰ کہ} کہ سمندر کے جزیروں میں اسرائیل کے خداوند خدا کا نام بھی ہو۔ {آگ: یا، وادیاں}\n16۔ ہم نے زمین کے بالکل کونے سے گانے سنے ہیں، {حتیٰ کہ راستبازوں کی شان}۔ لیکن میں نے کہا، میری دبلا پن، میری دبلا پن، میرے لیے افسوس! دھوکہ باز سوداگر نے دھوکہ دہی کی ہے؛ ہاں، دھوکہ باز ڈیلرز نے بہت دھوکہ دہی کی ہے۔ {سب سے زیادہ...: عببرانی۔ ونگ} {میری دبلی پتلی: عبرانی۔ میرے لیے دبلا پن، یا، میرے لیے میرا راز}\n17. خوف، اور گڑھا، اور جال، تم پر ہیں، اے زمین کے باشندے۔\n18۔ اور ایسا ہوگا کہ جو خوف کی آواز سے بھاگے گا وہ گڑھے میں گر جائے گا؛ اور جو کھائی کے بیچ سے نکلے گا وہ جال میں لے جائے گا: کیونکہ اونچی کھڑکیاں کھلی ہیں، اور زمین کی بنیادیں ہلتی ہیں۔\n19۔ زمین مکمل طور پر ٹوٹ پھوٹ کا شکار ہے، زمین صاف اور تحلیل ہو چکی ہے، زمین بہت زیادہ حرکت کرتی ہے۔\n20۔ زمین نشے میں دھت کی طرح ادھر ادھر گھومے گی، اور ایک جھونپڑی کی طرح ہٹا دی جائے گی؛ اور اس کی زیادتی اس پر بھاری ہوگی؛ اور وہ گر جائے گا، اور دوبارہ نہیں اٹھے گا۔\n21۔ اور اسی دن یہ ہوگا کہ خداوند اعلیٰ طبقے کے لشکر اور زمین پر موجود بادشاہوں کو سزا دے گا۔ {سزا: عبرانی۔ ملاحظہ کریں}\n22۔ اور انہیں اکٹھا کیا جائے گا، جیسے قیدی گڑھے میں جمع کیے جاتے ہیں، اور قید میں بند کیے جائیں گے، اور کئی دنوں بعد ان سے ملاقات کی جائے گی۔ {قیدیوں کے طور پر...: عبرانی۔ قیدیوں کے اجتماع کے ساتھ} {گڑھا: یا، تہہ خانہ} {دورہ کیا: یا، ناکافی پایا گیا}\n23۔ پھر چاند الجھا دیا جائے گا، اور سورج شرمندہ ہوگا، جب لشکروں کا رب کوہ صیون میں، یروشلم میں، اور اپنے قدیم لوگوں کے سامنے جلال سے حکومت کرے گا۔ {اس سے پہلے...: یا، اس کے قدیم لوگوں کے سامنے جلال ہوگا}","1. اے خداوند، تو میرا خدا ہے؛ میں تمہیں بلند کروں گا، تمہارے نام کی تعریف کروں گا؛ کیونکہ تم نے حیرت انگیز کام کیے ہیں؛ تمہاری پرانی نصیحتیں وفاداری اور سچائی ہیں۔\n2۔ کیونکہ تم نے ایک شہر کو ڈھیر بنا دیا ہے؛ ایک محفوظ شہر، ایک کھنڈر: اجنبیوں کا محل جو شہر نہ ہو؛ یہ کبھی تعمیر نہیں ہوگا۔\n3۔ اسی لیے طاقتور لوگ تیری جلال بخشیں گے، خوفناک قوموں کا شہر تم سے ڈرے گا۔\n4۔ کیونکہ تم غریبوں کے لیے طاقت، محتاجوں کے لیے اس کی مصیبت میں طاقت، طوفان سے پناہ گاہ، گرمی سے سایہ رہے ہو، جب خوفناک لوگوں کا جھٹکا دیوار کے خلاف طوفان کی طرح ہو۔\n5۔ تم اجنبیوں کی شور کو خشک جگہ کی گرمی کی طرح کم کرو گے؛ {حتیٰ کہ} بادل کے سائے کے ساتھ گرمی: خوفناک لوگوں کی شاخ نیچے لائی جائے گی۔\n6۔ اور اس پہاڑ میں لشکروں کے رب سب لوگوں کے لیے موٹے سامان کی ضیافت، لیز پر شراب، گودے سے بھری موٹی چیزوں کی ضیافت، اور خوبصورت نفیس شرابوں کی ضیافت بنائے گا۔\n7۔ اور وہ اس پہاڑ میں سب لوگوں پر پڑی چادر اور تمام قوموں پر پھیلی ہوئی پردہ کو تباہ کر دے گا۔ {تباہ کریں: عبرانی۔ نگل لو} {کاسٹ: ہیب۔ کورڈ}\n8. وہ موت کو فتح میں نگل جائے گا؛ اور خداوند خدا تمام چہروں سے آنسو پونچھ دے گا؛ اور اپنے لوگوں کی سرزنش کو وہ زمین سے چھین لے گا: کیونکہ خداوند نے کہا ہے۔\n9۔ اور اس دن کہا جائے گا، دیکھو، یہ ہمارا خدا ہے؛ ہم نے اس کا انتظار کیا ہے، اور وہ ہمیں بچا لے گا: یہ {ہے} خداوند ہے؛ ہم نے اس کا انتظار کیا ہے، ہم اس کی نجات پر خوش ہوں گے اور خوش ہوں گے۔\n10۔ کیونکہ اس پہاڑ پر خداوند کا ہاتھ آرام کرے گا، اور موآب اس کے نیچے روند دیا جائے گا، جیسے بھوسہ گوبر کے ڈھیر کے لیے روند دیا جاتا ہے۔ {نیچے سے روندا گیا: یا، تھریشڈ وغیرہ} {کچلا گیا...: یا، میڈمناہ میں تھریڈ کیا گیا}\n11۔ اور وہ اپنے ہاتھ ان کے درمیان پھیلائے گا، جیسے تیرنے والا تیرنے کے لیے اپنے ہاتھوں کو پھیلاتا ہے: اور وہ ان کے غرور کو ان کے ہاتھوں کی لوٹ مار کے ساتھ گرا دے گا۔\n12۔ اور تیری دیواروں کے اونچے قلعے کا قلعہ وہ گرا دے گا، نیچے کرے گا، {اور} زمین پر گرا دے گا، {حتیٰ کہ} خاک میں بھی۔","1۔ اسی دن یہ گیت یہوداہ کی سرزمین میں گایا جائے گا؛ ہمارے پاس ایک مضبوط شہر ہے؛ نجات {خدا} دیواروں اور قلعوں کے لیے مقرر کرے گی۔\n2. دروازے کھولو، تاکہ وہ نیک قوم جو سچائی کو برقرار رکھتی ہے، اندر آ سکے۔ {سچائی: عبرانی۔ سچائی}\n3. تم {اسے} کو مکمل سکون میں رکھو گے، {جس کا ذہن {تمہارے اوپر} رکا ہے: کیونکہ وہ تم پر بھروسہ کرتا ہے۔ {کامل...: عبوری۔ امن، امن} {ذہن: یا، خیال، یا، تخیل}\n4. ہمیشہ کے لیے خداوند پر بھروسہ کرو: کیونکہ خداوند یہوواہ میں ہمیشہ کی طاقت ہے: {ابدی...: عبرانی۔ دی راک آف ایجز}\n5۔ کیونکہ وہ ان لوگوں کو نیچے اتارتا ہے جو اونچے مقام پر رہتے ہیں؛ بلند شہر کو، وہ اسے نیچا دکھاتا ہے؛ وہ اسے زمین پر گرا دیتا ہے؛ وہ اسے {حتیٰ کہ} مٹی میں لے آتا ہے۔\n6. پاؤں اس پر چلے، {حتیٰ کہ} غریبوں کے قدموں پر، {اور} محتاجوں کے قدم۔\n7۔ نیک راستوں کا راستہ راست بازی ہے: تو، سب سے زیادہ سیدھا، نیک لوگوں کے راستے کو تولتے ہو۔\n8۔ جی ہاں، اے خداوند، تیرے فیصلوں کے راستے میں ہم نے تیرے انتظار کیا؛ {ہماری} روح کی خواہش {ہے} تیرے نام کے لیے، اور تیری یاد کے لیے۔\n9۔ میں نے رات میں اپنی جان سے تمہیں چاہا؛ ہاں، اپنی روح کے ساتھ میں تمہیں جلدی تلاش کروں گا: کیونکہ جب تمہارے فیصلے زمین پر ہوں گے، دنیا کے باشندے راستبازی سیکھیں گے۔\n10۔ بدکاروں پر احسان کیا جائے، {لیکن} وہ راستبازی نہیں سیکھے گا: راستبازی کی سرزمین میں وہ ناانصافی کرے گا، اور خداوند کی عظمت کو نہیں دیکھے گا۔\n11۔ اے خداوند، {جب} تیرا ہاتھ اٹھایا جائے گا، وہ نہیں دیکھیں گے: {لیکن} وہ دیکھیں گے، اور لوگوں سے حسد پر شرمندہ ہوں گے؛ ہاں، تمہارے دشمنوں کی آگ انہیں نگل جائے گی۔ {پر...: یا، اپنے لوگوں کی طرف}\n12۔ اے خداوند، تو ہمارے لیے امن قائم کرو گا: کیونکہ تو نے بھی ہمارے تمام اعمال ہم میں کیے ہیں۔ {ہمارے اندر: یا، ہمارے لیے}\n13. اے خداوند ہمارے خدا، {تیرے علاوہ} دوسرے خداوندوں نے ہم پر حکمرانی کی ہے: {لیکن} صرف تیرے ذریعے ہی ہم تیرا نام یاد کریں گے۔\n14. {وہ} مر چکے ہیں، وہ زندہ نہیں رہیں گے؛ {وہ} مر چکے ہیں، وہ دوبارہ زندہ نہیں ہوں گے: اس لیے تم نے ان کا دورہ کیا اور انہیں تباہ کیا، اور ان کی تمام یادیں ختم کر دیں۔\n15۔ اے خداوند، تو نے قوم کو بڑھا دیا ہے: تو جلال یافتہ ہو: تو نے اسے زمین کے تمام کناروں تک دور کر دیا ہے۔\n16۔ اے خداوند، مصیبت میں وہ تیرے پاس آئے، انہوں نے دعا کی {جب} تیرا عذاب ان پر نازل ہوا۔ {دعا: عبرانی۔ خفیہ تقریر}\n17۔ جیسے ایک عورت جس کے بچے ہیں، {جو} اپنی پیدائش کے وقت قریب آتی ہے، درد میں مبتلا ہوتی ہے، {اور} اپنے درد میں روتی ہے؛ اسی طرح ہم تیرے سامنے تھے، اے خداوند۔\n18۔ ہم حاملہ تھے، ہم درد میں تھے، ہم نے ہوا کو جنم دیا؛ ہم نے زمین پر کوئی نجات نہیں دی؛ نہ ہی دنیا کے باشندے گر چکے ہیں۔\n19۔ تمہارے مردہ {لوگ} زندہ ہوں گے، {میرے مردہ جسم کے ساتھ} وہ زندہ ہوں گے۔ جاگو اور گاؤ، اے جو خاک میں بستے ہو: کیونکہ تمہاری شبنم جڑی بوٹیوں کی شبنم کی طرح ہے، اور زمین مردوں کو نکال دے گی۔\n20۔ آؤ، میرے لوگو، اپنے کمروں میں داخل ہو جاؤ، اور اپنے دروازے بند کر دو: اپنے آپ کو ایک لمحے کے لیے چھپا لو، جب تک غصہ ختم نہ ہو جائے۔\n21. کیونکہ دیکھو، خداوند اپنی جگہ سے نکل کر زمین کے باشندوں کو ان کی گناہوں کی سزا دیتا ہے: زمین بھی اپنا خون ظاہر کرے گی، اور اپنے قتل شدہ کو مزید نہیں ڈھانپے گی۔ {خون: عبرانی۔ bloods}","1۔ اس دن خداوند اپنی دردناک، عظیم اور مضبوط تلوار کے ساتھ لیویاتھن کو سزا دے گا، جو چبھتا ہوا سانپ ہے، حتیٰ کہ اس ٹیڑھے سانپ کو بھی؛ اور وہ اس اژدہے کو مار ڈالے گا جو سمندر میں ہے۔ {چبھنے والا: یا، بار کی طرح پار کرنا}\n2۔ اس دن اس کے لیے گاؤ، سرخ شراب کا باغ۔\n3۔ میں خداوند اسے سنبھالتا ہوں؛ میں اسے ہر لمحہ پانی دوں گا: کہیں کوئی اسے نقصان نہ پہنچائے، میں اسے دن رات رکھوں گا۔\n4. غصہ {ہے} مجھ میں نہیں: کون میرے خلاف کانٹے اور کانٹے لڑائے گا؟ میں ان میں سے گزرتا، انہیں ایک ساتھ جلا دیتا۔ {جاؤ...: یا، اس کے خلاف مارچ کرو}\n5۔ یا اسے میری طاقت پر قبضہ کرنے دو، {تاکہ} وہ مجھ سے صلح کر سکے؛ {اور} وہ میرے ساتھ صلح کرے گا۔\n6۔ وہ یعقوب کے آنے والوں کو جڑ پکڑنے دے: اسرائیل کھلے گا اور پھول نکلے گا، اور دنیا کا چہرہ پھل سے بھر دے گا۔\n7۔ کیا اس نے اسے مارا، جیسے اس نے ان لوگوں کو مارا جنہوں نے اسے مارا؟ {یا} کیا وہ ان لوگوں کے قتل کے مطابق مارا جاتا ہے جو اس کے ہاتھوں مارے جاتے ہیں؟ {یعنی...: عبرانی اسٹروک کے مطابق}\n8۔ جب وہ باہر نکلے گا، تو تم اس سے بحث کرو گے: وہ اپنی تیز ہوا کو مشرقی ہوا کے دن میں روکے گا۔ {یہ گولی چلاتی ہے...: یا، تم اسے بھیجتے ہو} {وہ...: یا، جب وہ اسے ہٹاتا ہے}\n9۔ اسی طرح یعقوب کی بدکاری کو پاک کیا جائے گا؛ اور یہ وہ تمام پھل ہے جو اس کے گناہ کو دور کر سکتا ہے؛ جب وہ قربان گاہ کے تمام پتھروں کو چاک پتھر کی طرح بنائے گا جو ٹکڑوں میں ماٹے گئے ہوں، تو جھنڈ اور مجسمے کھڑے نہیں ہوں گے۔ {تصاویر: یا، سورج کی تصاویر}\n10۔ پھر بھی محفوظ شہر ویران ہو جائے گا، اور رہائش ویران ہو جائے گی، اور بیابان کی طرح چھوڑ دی جائے گی: وہاں بچھڑا کھائے گا، اور وہاں لیٹ جائے گا، اور اس کی شاخیں کھا جائے گا۔\n11۔ جب اس کی شاخیں مرجھا جائیں گی، تو انہیں توڑ دیا جائے گا: عورتیں آئیں گی اور انہیں آگ لگا دیں گی: کیونکہ یہ ایک بے سمجھ قوم ہے؛ اس لیے جس نے انہیں بنایا ہے وہ ان پر رحم نہیں کرے گا، اور جس نے انہیں بنایا ہے وہ انہیں کوئی فضل نہیں دے گا۔\n12۔ اور اسی دن یہ ہو جائے گا، {کہ} خداوند دریا کے راستے سے مصر کی ندی تک پہنچ جائے گا، اور تم سب ایک ایک کر کے جمع ہو جاؤ گے، اے بنی اسرائیل۔\n13۔ اور اس دن یہ ہو جائے گا کہ عظیم بگل بجائی جائے گی، اور وہ لوگ آئیں گے جو آشور کی سرزمین میں فنا ہونے کو تیار تھے، اور مصر کی سرزمین میں بے گھر لوگوں کو بھی، اور وہ یروشلم کے مقدس پہاڑ میں خداوند کی عبادت کریں گے۔","1. فخر کے تاج پر افرائیم کے نشے میں دھت لوگوں پر افسوس ہو، جن کی شاندار خوبصورتی ایک مدھم پھول ہے، جو ان موٹی وادیوں کے سر پر ہیں جو شراب سے مغلوب ہیں! {مغلوب: عبرانی۔ ٹوٹا ہوا}\n2۔ دیکھو، خداوند کے پاس ایک طاقتور اور طاقتور خدا ہے، {جو} اولے کے طوفان کی طرح {اور} تباہ کن طوفان، جیسے عظیم پانیوں کا سیلاب ہاتھ سے زمین پر گرا دے گا۔\n3. فخر کا تاج، افرائیم کے نشے میں دھت لوگ، پیروں تلے روند دیا جائے گا: {نیچے...: عبرانی۔ پاؤں کے ساتھ}\n4۔ اور وہ شاندار خوبصورتی، جو موٹی وادی کے سرے پر ہے، ایک مدھم پھول بن جائے گی، {اور} جیسے گرمیوں سے پہلے جلدی پھل؛ جو {جب} جو اسے دیکھتا ہے وہ دیکھتا ہے، جب وہ ابھی اس کے ہاتھ میں ہوتا ہے تو وہ اسے کھا جاتا ہے۔ {کھانا: عبرانی۔ نگل لوئی}\n5۔ اس دن لشکروں کا رب جلال کا تاج اور خوبصورتی کا تاج اپنے لوگوں کے باقیات کے لیے ہوگا،\n6۔ اور اس کے لیے فیصلہ کرنے کی روح کے لیے جو بیٹھتا ہے، اور ان کے لیے طاقت کے لیے جو جنگ کو دروازے کی طرف موڑتے ہیں۔\n7۔ لیکن انہوں نے شراب کے ذریعے بھی غلطی کی ہے، اور تیز شراب کے ذریعے راستے سے ہٹ گئے ہیں؛ کاهن اور نبی نے تیز شراب سے غلطی کی ہے، وہ شراب میں نگل لیے جاتے ہیں، وہ تیز شراب سے ہٹ جاتے ہیں؛ وہ وژن میں غلطی کرتے ہیں، فیصلہ کرنے میں ٹھوکر کھاتے ہیں۔\n8۔ کیونکہ تمام میزیں قے {اور} گندگی سے بھری ہوتی ہیں، {تاکہ کوئی جگہ {صاف} نہ رہے۔\n9۔ وہ کس کو علم سکھائیں؟ اور وہ کس کو عقیدہ سمجھانے پر مجبور کرے گا؟ {جو ہیں} دودھ سے دودھ چھڑاتے ہیں، {اور} دودھ سے نکالے جاتے ہیں۔ {عقیدہ: عبرانی۔ سماعت؟}\n10۔ کیونکہ اصول {لازم} پر اصول، حکم پر حکم؛ لائن در لائن، لائن در لائن؛ یہاں تھوڑا سا، {اور} وہاں تھوڑا سا: {ہونا چاہیے: یا، رہا ہے}\n11۔ کیونکہ وہ ہچکچاتے ہونٹوں اور دوسری زبان کے ساتھ اس قوم سے بات کرے گا۔ {ہچکچاتے ہوئے...: عبرانی۔ ہونٹوں کی ہچکچاہٹ} {ارادہ...: یا، اس نے کہا ہے}\n12۔ جس سے اس نے کہا، یہ {ہے} باقی {جس سے} تم تھکے ہوئے لوگوں کو آرام دے سکتے ہو؛ اور یہ {تازگی} ہے: پھر بھی وہ سننے کو تیار نہیں تھے۔\n13۔ لیکن خداوند کا کلام ان کے لیے ایک پر حکم، ایک پر حکم تھا؛ لائن در لائن، لائن در لائن؛ یہاں تھوڑا سا، {اور} وہاں تھوڑا سا؛ تاکہ وہ جا سکیں، پیچھے گر جائیں، ٹوٹ جائیں، پھنسے جائیں، اور پکڑ لیں۔\n14۔ اسی لیے اے تحقیر کرنے والے لوگو، خداوند کا کلام سنو، جو اس قوم پر حکومت کرتے ہیں جو یروشلم میں ہے۔\n15۔ کیونکہ تم نے کہا ہے، ہم نے موت کے ساتھ عہد کیا ہے، اور جہنم کے ساتھ ہم متفق ہیں؛ جب یہ عذاب گزرے گا، تو وہ ہمیں نہیں پہنچے گا: کیونکہ ہم نے جھوٹ کو پناہ دی ہے، اور جھوٹ کے نیچے چھپ گئے ہیں:\n16۔ لہٰذا خداوند خدا یہ فرماتا ہے، دیکھو، میں نے صیہون میں بنیاد کے لیے ایک پتھر، آزمودہ پتھر، قیمتی گوشہ {پتھر}، ایک پختہ بنیاد رکھی ہے: جو ایمان لاتا ہے جلدی نہیں کرے گا۔\n17۔ میں فیصلہ بھی دکھاؤں گا، اور راستبازی کو گرنے کے لیے: اور اولے جھوٹ کے پناہ گاہ کو بہا لے جائیں گے، اور پانی چھپنے کی جگہ پر بہا جائے گا۔\n18۔ اور تمہارا موت کے ساتھ عہد ختم ہو جائے گا، اور جہنم کے ساتھ تمہارا معاہدہ قائم نہیں رہے گا؛ جب یہ وبا گزرے گی، تب تم اس کے نیچے آ جاؤ گے۔ {پیدل چلنا...: عبرانی۔ ایک قدم اٹھانا}\n19۔ جب سے یہ نکلے گا، یہ آپ کو لے جائے گا: کیونکہ صبح بہ صبح یہ گزرے گا، دن اور رات: اور صرف رپورٹ کو سمجھنا ایک تکلیف دہ ہوگا۔ {کو...: یا، جب وہ تمہیں عقیدہ سمجھائے}\n20۔ کیونکہ بستر اس سے چھوٹا ہے {آدمی} خود کو اس پر کھینچ سکتا ہے: اور اس سے تنگ پردہ وہ خود کو {اس میں لپیٹ سکتا ہے}۔\n21۔ کیونکہ خداوند پہاڑ پیرازیم کی طرح اٹھے گا، وہ گبعون کی وادی کی طرح غصے میں ہوگا، تاکہ وہ اپنا کام، اپنا عجیب کام کرے؛ اور اس کے عمل کو عملی جامہ پہنانا، اس کا عجیب عمل۔\n22۔ اب مذاق نہ اڑاؤ، ورنہ تمہارے دستے مضبوط ہو جائیں گے: کیونکہ میں نے خداوند خدا کی لشکریوں سے سنا ہے، جو پوری زمین پر مقدر ہے۔\n23. سنو اور میری آواز سنو؛ سنو، اور میری تقریر سنو۔\n24۔ کیا ہل چلانے والا سارا دن ہل چلاتا ہے تاکہ بوائی کرے؟ کیا وہ اپنی زمین کے گچھے کھولتا اور توڑتا ہے؟\n25۔ جب اس نے اس کا چہرہ واضح کر دیا ہے، تو کیا وہ فچز کو باہر نہیں پھینکتا، اور کامین کو بکھیر دیتا ہے، اور ان کی جگہ اصل گندم، مقررہ جو اور ری ڈال دیتا ہے؟ {اصل مقام...: یا، اصل جگہ پر گندم، اور مقررہ جگہ پر جو} {ری: یا، ہجے میں} {جگہ: عبرانی۔ بارڈر؟}\n26۔ کیونکہ اس کا خدا اسے احتیاط کی ہدایت دیتا ہے، {اور} اسے سکھاتا ہے۔ {کیونکہ...: یا، اور وہ اسے اس طرح باندھتا ہے جیسا اس کا خدا اسے سکھاتا ہے}\n27۔ کیونکہ فچز کو تھریشنگ آلے سے نہیں گھمایا جاتا، نہ ہی گاڑی کا پہیہ کمن پر گھومتا ہے؛ لیکن فچز کو چھڑی سے مارا جاتا ہے، اور کممن کو چھڑی سے مارا جاتا ہے۔\n28۔ روٹی {مکئی} زخمی ہو جاتی ہے؛ کیونکہ وہ کبھی اسے تھریس نہیں کرے گا، نہ ہی اپنی گاڑی کے پہیے سے توڑے گا، نہ ہی اپنے گھڑ سواروں سے اسے زخمی کرے گا۔\n29۔ یہ بھی لشکروں کے رب کی طرف سے نکلتا ہے، {جو} مشورے میں شاندار ہے، {اور} کام میں بہترین ہے۔","1. ارئیل پر افسوس، ایریل پر، وہ شہر {جہاں} داؤد رہتا تھا! سال بہ سال جمع کرو؛ انہیں قربانیوں کو مارنے دو۔ {افسوس...: یا، اے ایریئل، یعنی خدا کا شیر} {شہر: یا، شہر کا} {قتل: عبرانی۔ کے سر کاٹ دینا}\n2۔ پھر بھی میں ایریل کو پریشان کروں گا، اور وہاں بوجھ اور غم ہوگا: اور یہ میرے لیے ایریل کی طرح ہوگا۔\n3۔ اور میں تمہارے ارد گرد کیمپ لگاؤں گا، اور تمہارے خلاف گھوڑے سے محاصرہ کروں گا، اور تمہارے خلاف قلعے کھڑے کروں گا۔\n4۔ اور تم نیچے آؤ گے، {اور} زمین سے بولو گے، اور تمہاری گفتگو مٹی سے دھیمی ہو گی، اور تمہاری آواز زمین سے ایک مانوس روح کی طرح ہوگی، اور تمہاری بات خاک سے سرگوشی کرے گی۔ {سرگوشی: عبرانی۔ پیپ، یا، چرپ}\n5۔ مزید برآں، تمہارے اجنبی کی کثرت چھوٹی خاک کی طرح ہو جائے گی، اور خوفناک لوگوں کی کثرت بھوسے کی طرح ہو جائے گی جو گزر جاتی ہے: ہاں، یہ اچانک ختم ہو جائے گی۔\n6۔ خداوند لشکروں کی طرف سے تمہیں گرج، زلزلہ، اور شدید شور، طوفان اور آگ کی آگ کی آگ سے سامنا کرنا پڑے گا۔\n7۔ اور وہ تمام قومیں جو ایریل کے خلاف لڑتی ہیں، حتیٰ کہ وہ سب جو اس کے اور اس کے گولہ بارود کے خلاف لڑتے ہیں، اور جو اسے پریشان کرتے ہیں، وہ ایک خواب کی مانند ہوں گے جو رات کی نظر کا خواب ہو۔\n8۔ یہ ویسا ہی ہوگا جیسے بھوکا انسان خواب دیکھے، اور دیکھتے ہوئے کھاتا ہے؛ لیکن وہ جاگتا ہے، اور اس کی روح خالی ہوتی ہے: یا جیسے پیاسا آدمی خواب دیکھتا ہے، اور دیکھتا ہے وہ پیتا ہے؛ لیکن وہ جاگتا ہے، اور دیکھو، {وہ} بے ہوش ہے، اور اس کی روح کو بھوک ہے: اسی طرح وہ تمام قومیں ہوں گی جو کوہ صیون کے خلاف لڑ رہی ہیں۔\n9. اپنے آپ کو سنبھالیں، اور سوچیں؛ تم پکارو، اور چیلو: وہ نشے میں ہیں، لیکن شراب سے نہیں؛ وہ لڑکھڑاتے ہیں، لیکن تیز شراب کے ساتھ نہیں۔ {روتے ہو...: یا، اپنی خوشی لو، اور ہنگامہ کرو}\n10۔ کیونکہ خداوند نے تم پر گہری نیند کی روح بہا دی ہے، اور تمہاری آنکھیں بند کر دی ہیں: نبی اور تمہارے حکمران، دیکھنے والوں نے اسے ڈھانپ دیا ہے۔ {حکمران: عبرانی۔ ہیڈز}\n11۔ اور سب کا وژن تمہارے لیے ایسے ہو جاتا ہے جیسے ایک مہر بند کتاب کے الفاظ، جسے {لوگ} کسی عالم کو پہنچاتے ہیں، کہتا ہے، یہ پڑھو، میں تم سے دعا کرتا ہوں: اور وہ کہتا ہے، میں نہیں پڑھ سکتا؛ کیونکہ یہ {ہے} مہر بند ہے: {کتاب: یا، خط}\n12۔ اور کتاب اس کے پاس دی جاتی ہے جو علم نہیں کرتا، کہتا ہے، یہ پڑھو، میں تم سے دعا کرتا ہوں: اور وہ کہتا ہے، میں عالم نہیں ہوں۔\n13۔ اسی لیے خداوند نے فرمایا، چونکہ یہ لوگ اپنے منہ اور ہونٹوں سے مجھ سے قریب آتے ہیں، لیکن اپنے دل کو مجھ سے دور کر چکے ہیں، اور ان کا مجھ سے خوف انسانوں کے حکم سے سکھایا جاتا ہے:\n14۔ لہٰذا، دیکھو، میں اس قوم کے درمیان ایک شاندار کام کرنے جا رہا ہوں، {حتیٰ کہ} ایک حیرت انگیز کام اور ایک عجوبہ بھی: کیونکہ ان کے عقلمندوں کی حکمت ختم ہو جائے گی، اور ان کے محتاط لوگوں کی سمجھ چھپی رہے گی۔ {آگے بڑھیں: عبرانی۔ add}\n15۔ ان پر افسوس جو اپنی نصیحت کو خداوند سے چھپانے کی کوشش کرتے ہیں، اور ان کے اعمال اندھیرے میں ہیں، اور کہتے ہیں، کون ہمیں دیکھتا ہے؟ اور کون ہمیں جانتا ہے؟\n16. یقینا آپ کا چیزوں کو الٹا کرنا مٹی کی طرح عزت پائے گا: کیونکہ کیا کام اس کے بارے میں کہے گا جس نے یہ بنایا، اس نے مجھے نہیں بنایا؟ یا وہ چیز جو فریم کی گئی تھی، اس کے بارے میں کہے گی جس نے اسے فریم کیا تھا، اسے کوئی سمجھ نہیں تھی؟\n17. {کیا} ابھی بہت کم وقت باقی ہے، اور لبنان ایک زرخیز کھیت میں بدل جائے گا، اور زرخیز کھیت کو جنگل کی طرح سراہا جائے گا؟\n18۔ اور اس دن بہرے کتاب کے الفاظ سنیں گے، اور نابینا کی آنکھیں گنامی اور اندھیرے سے دیکھیں گی۔\n19۔ عاجز بھی خداوند میں اپنی خوشی بڑھائیں گے، اور انسانوں میں سے غریب اسرائیل کے مقدس وجود میں خوشی منائیں گے۔ {اضافہ: عبوری۔ add}\n20۔ کیونکہ خوفناک شخص ختم ہو جاتا ہے، اور مذاق کرنے والا ختم ہو جاتا ہے، اور جو بھی بدکاری کا انتظار کر رہا ہوتا ہے اسے کاٹ دیا جاتا ہے:\n21۔ جو کسی کو ایک بات پر مجرم بناتا ہے، اور جو سرزنش کرتا ہے اس کے لیے دروازے پر جال بچھاتے ہیں، اور انصاف کو بے کار چیز کے لیے رد کر دیتے ہیں۔\n22. لہٰذا خداوند نے یعقوب کے گھر کے بارے میں کہا ہے، جس نے ابراہیم کو نجات دی ہے، اب یعقوب شرمندہ نہیں ہوگا، اور نہ ہی اس کا چہرہ سفید پڑے گا۔\n23۔ لیکن جب وہ اپنے بچوں کو، جو میرے ہاتھوں کا کام ہے، اپنے درمیان دیکھے گا، تو وہ میرا نام پاک کریں گے، یعقوب کے مقدس کو پاک کریں گے، اور اسرائیل کے خدا سے ڈریں گے۔\n24۔ جو لوگ روحانی طور پر غلطی کرتے ہیں وہ سمجھ میں آتے ہیں، اور جو سرگوشی کرتے ہیں وہ تعلیمات سیکھیں گے۔ {آؤ...: عبرانی۔ سمجھ بوجھ جاننا}","1۔ خداوند فرماتا ہے کہ باغی بچوں پر افسوس ہو جو مشورہ دیتے ہیں، لیکن مجھ سے نہیں؛ اور وہ پردہ ڈھانپ دے، لیکن میری روح کا نہیں، تاکہ وہ گناہ کو گناہ میں شامل کر سکیں:\n2۔ جو مصر میں نیچے جانے کے لیے چلتے ہیں، اور میرے منہ سے نہیں پوچھا؛ فرعون کی طاقت میں خود کو مضبوط کرنے کے لیے، اور مصر کے سائے پر بھروسہ کرنے کے لیے!\n3. لہٰذا فرعون کی طاقت تمہاری شرمندگی ہوگی، اور مصر کے سائے {تمہارا} الجھن پر بھروسہ۔\n4۔ کیونکہ اس کے شہزادے زوآن میں تھے، اور اس کے سفیر ہینس آ گئے۔\n5۔ وہ سب اس قوم سے شرمندہ تھے جو، نہ تو انہیں فائدہ پہنچا سکتی تھی، نہ ہی فائدہ پہنچا سکتی تھی، بلکہ شرمندگی اور ملامت بھی تھی۔\n6۔ جنوب کے جانوروں کا بوجھ: مصیبت اور اذیت کی سرزمین میں، جہاں سے نوجوان اور بوڑھا شیر، سانپ اور آگ اڑتا ہوا سانپ آئے گا، وہ اپنی دولت کو نوجوان گدھوں کے کندھوں پر اور اپنے خزانے اونٹوں کے گچھوں پر لے جائیں گے، ایک ایسی قوم کے لیے جو ان کے لیے فائدہ مند نہیں ہوں گی۔\n7۔ کیونکہ مصری بے سود مدد کریں گے، اور بے سود: اسی لیے میں نے اس پر پکار کر کہا، ان کی طاقت یہ ہے کہ وہ خاموش بیٹھیں۔ {تشویش...: یا، اس کے لیے}\n8۔ اب جاؤ، اسے ان کے سامنے ایک میز میں لکھو، اور کتاب میں نوٹ کرو، تاکہ یہ ہمیشہ کے لیے آنے والے وقت کے لیے ہو: {the...: عبرانی۔ آخری دن}\n9۔ کہ یہ {ایک باغی} قوم ہے، جھوٹے بچے ہیں، بچے {جو} خداوند کے قانون کو نہیں سنیں گے:\n10۔ جو دیکھنے والوں سے کہتے ہیں، دیکھو مت؛ اور نبیوں کو، ہمیں صحیح باتوں کی پیش گوئی نہ کرو، ہم سے صاف باتیں کرو، نبوت کرو دھوکہ دے:\n11۔ تمہیں راستے سے ہٹا دوں، راستے سے ہٹ جاؤ، اور اسرائیل کے مقدس وجود کو ہمارے سامنے سے روک دو۔\n12۔ اسی لیے اسرائیل کے مقدس وجود نے یوں فرمایا، کیونکہ تم اس کلام سے نفرت کرتے ہو، ظلم و فحش پر بھروسہ کرتے ہو، اور اسی پر قائم رہتے ہو: {ظلم: یا، دھوکہ}\n13. اس لیے یہ گناہ تمہارے لیے ایک دراڑ کی طرح ہوگی جو گرنے کو تیار ہے، جو ایک اونچی دیوار میں پھولے گی، جس کا ٹوٹنا اچانک ایک لمحے میں آئے گا۔\n14۔ اور وہ اسے ایسے توڑے گا جیسے کمہاروں کے برتن کے ٹکڑوں میں ٹوٹ جائے؛ وہ کبھی نہیں چھوڑے گا: تاکہ اس کے پھٹنے میں کوئی ٹکڑا نہ ملے جو آگ لے سکے، یا گڑھے سے پانی نکالے۔ {کمھارز...: عبرانی۔ دی بوتل آف پوٹرز\n15۔ کیونکہ خداوند خدا، اسرائیل کا پاک، یہی فرماتا ہے؛ واپس آ کر اور آرام کر کے تم نجات پاؤ گے؛ خاموشی اور اعتماد میں تمہاری طاقت ہوگی: اور تم نہیں چاہتے۔\n16۔ لیکن تم نے کہا، نہیں؛ کیونکہ ہم گھوڑوں پر بھاگ جائیں گے؛ لہٰذا تم بھاگو گے: اور ہم تیز رفتار پر سوار ہوں گے؛ اسی لیے جو آپ کا پیچھا کریں گے وہ جلدی کریں گے۔\n17. ایک ہزار {بھاگ جائیں گے} ایک کی سرزنش پر؛ پانچ کی سزا پر تم بھاگ جاؤ گے: جب تک تم پہاڑ کی چوٹی پر روشنی کی طرح نہ رہ جاؤ، اور پہاڑی پر نشان کی طرح۔ {ایک مینار: یا، شاخوں سے خالی درخت، یا، شاخیں: یا، ایک مستول}\n18۔ اور اس لیے خداوند انتظار کرے گا، تاکہ وہ آپ پر مہربان ہو سکے، اور اس لیے وہ بلند ہو جائے گا، تاکہ وہ آپ پر رحم کرے: کیونکہ خداوند {ہے} انصاف کا خدا ہے: مبارک ہیں وہ سب جو اس کا انتظار کرتے ہیں۔\n19۔ کیونکہ لوگ یروشلم میں صہیون میں رہیں گے: اب تم نہ روؤ: وہ تمہارے پکار کی آواز پر تمہارے ساتھ بہت مہربان ہوگا؛ جب وہ اسے سنے گا، وہ تمہیں جواب دے گا۔\n20. اور {اگر} خداوند تمہیں مصیبت کی روٹی اور مصیبت کا پانی دے دے، پھر بھی تمہارے اساتذہ کو مزید کونے میں نہیں ڈالا جائے گا، بلکہ تمہاری آنکھیں تمہارے اساتذہ کو دیکھیں گی: {مصیبت: یا، ظلم}\n21. اور تمہارے کان تمہارے پیچھے سے کوئی لفظ سنیں گے، جو کہتا ہے: یہی راستہ ہے، تم اس میں چلو، جب تم دائیں ہاتھ مڑو اور جب تم بائیں طرف مڑو۔\n22۔ تم اپنی چاندی کی تراشی ہوئی تصویروں کی تہہ اور اپنے پگھلے ہوئے سونے کے مجسموں کے زیور کو بھی آلودہ کرو گے: انہیں حیض کے کپڑے کی طرح پھینک دو؛ تم اس سے کہو گے، یہاں سے نکل جاؤ۔ {تمہارا کندہ کردہ...: عبرانی۔ تیری چاندی کی کندہ شدہ تصویریں} {کاسٹ: عبرانی۔ بکھراؤ}\n23۔ پھر وہ تمہارے بیج کی بارش دے گا، جس سے تم زمین بوؤ گے؛ اور زمین کی افزائش کی روٹی، اور وہ موٹی اور بھرپور ہوگی: اس دن تمہارے مویشی بڑے چراگاہوں میں کھلائیں گے۔\n24۔ بیل بھی اسی طرح اور وہ نوجوان گدھے جو زمین کو کان لگاتے ہیں، صاف پروونڈر کھائیں گے، جو بیلچے اور پنکھے سے چھایا گیا ہو۔ {صاف: یا، نمکین: عبوری۔ خمیر شدہ}\n25۔ اور ہر اونچے پہاڑ اور ہر اونچی پہاڑی پر دریا ہوں گے {اور} بڑے قتل عام کے دن جب مینار گریں گے۔ {ہائی ہل: عبرانی۔ اٹھایا ہوا وغیرہ}\n26۔ مزید یہ کہ چاند کی روشنی سورج کی روشنی کی طرح ہوگی، اور سورج کی روشنی سات گنا ہو گی، سات دن کی روشنی کے طور پر، اس دن جب خداوند اپنے لوگوں کی دراڑ کو باندھ دے گا اور ان کے زخم کا شفا دے گا۔\n27۔ دیکھو، خداوند کا نام دور سے آتا ہے، اپنے غصے کے ساتھ جل رہا ہے، اور اس کا بوجھ بھاری ہے: اس کے ہونٹ غصے سے بھرے ہوئے ہیں، اور اس کی زبان آگ کی طرح ہے: {بوجھ...: یا، شدید آگ} {بھاری: عبرانی۔ بھاری پن}\n28۔ اور اس کی سانس، ایک بہتی ہوئی ندی کی طرح، گردن کے بیچ تک پہنچے گی، قوموں کو فضول پن سے چھانٹنے کے لیے: اور لوگوں کے جبڑوں میں ایک لگام ہوگی، جو انہیں گمراہ کرے گی۔\n29۔ تمہیں ایک گانا ہوگا، جیسے رات میں {جب} مقدس رسم ادا کی جاتی ہے؛ اور دل کی خوشی، جیسے کوئی پائپ لے کر خداوند کے پہاڑ میں داخل ہونے جائے، اسرائیل کے طاقتور ہستی کے پاس۔ {mighty...: عبرانی راک}\n30۔ اور خداوند اپنی جلالی آواز کو سنائے، اور اپنے بازو کی روشنی دکھائے گا، [اپنی} غصے کے ساتھ، اور {نگلتی آگ کی آگ کے ساتھ} بکھرنا، طوفان، اور اولے کے ساتھ۔ {اس کا شاندار...: عبرانی۔ اس کی آواز کی شان}\n31۔ کیونکہ خداوند کی آواز سے آشوری کو شکست دی جائے گی، {جو} کو لاٹھی سے مارا جائے گا۔\n32۔ اور ہر جگہ جہاں زمین پر لاٹھی ہوئی چھڑی گزرے گی، جسے خداوند اس پر رکھے گا، وہ تختوں اور ہارپ سے ہوگی: اور جھٹکوں کی لڑائیوں میں وہ اس کے ساتھ لڑے گا۔ {ہر...: عبرانی میں۔ چھڑی کا ہر گزرنا} {lay...: عبرانی۔ وجہ جس پر آرام کیا جائے} {اس کے ساتھ: یا، ان کے خلاف}\n33۔ کیونکہ ٹوفیٹ {پرانے زمانے میں مقرر کیا گیا ہے}؛ ہاں، بادشاہ کے لیے یہ تیار ہے؛ اس نے اسے گہرا اور بڑا بنایا ہے: اس کا ڈھیر آگ اور بہت سا لکڑی ہے؛ خداوند کی سانس، گندھک کی دھار کی طرح، اسے روشن کرتی ہے۔ {پرانے: عبرانی۔ کل سے}","1۔ ان پر افسوس جو مدد کے لیے مصر جاتے ہیں؛ اور گھوڑوں پر رہو، اور رتھوں پر بھروسہ کرو، کیونکہ {وہ} بہت ہیں؛ اور گھڑ سواروں میں، کیونکہ وہ بہت طاقتور ہیں؛ لیکن وہ اسرائیل کے مقدس وجود کی طرف نہیں دیکھتے، نہ ہی خداوند کی طلب کرتے ہیں!\n2۔ پھر بھی وہ دانا ہے، اور برائی لائے گا، اور اپنے الفاظ واپس نہیں لے گا، بلکہ بدکاروں کے گھرانے اور بدکاروں کی مدد کے خلاف اٹھے گا۔ {کال...: عبوری۔ ہٹانا}\n3۔ اب مصری انسان ہیں، خدا نہیں؛ اور ان کے گھوڑے گوشت تھے، روح نہیں۔ جب خداوند اپنا ہاتھ بڑھائے گا، تو جو مدد کرے گا وہ گر جائے گا، اور جو ہولپن ہے وہ گر جائے گا، اور وہ سب مل کر ناکام ہوں گے۔\n4۔ کیونکہ خداوند نے مجھ سے یہی بات کی ہے، جیسے شیر اور نوجوان شیر اپنے شکار پر دھاڑتے ہیں، جب چرواہوں کی بڑی تعداد اس کے خلاف آتی ہے، {و} ان کی آواز سے نہیں ڈرے گا، نہ ہی ان کی شور پر خود کو ذلیل کرے گا: یوں لشکروں کا رب پہاڑ صیون کے لیے لڑنے کے لیے نیچے آئے گا،  اور اس کے پہاڑی کے لیے۔ {شور: یا، کثرت}\n5۔ جیسے پرندے اڑتے ہیں، اسی طرح رب لشکریوں یروشلم کی حفاظت کرے گا؛ دفاع بھی کرتے ہوئے وہ اسے دے گا؛ اور} گزر کر اسے محفوظ رکھے گا۔\n6۔ تم اس کی طرف رجوع کرو جس سے بنی اسرائیل نے شدید بغاوت کی ہے۔\n7۔ کیونکہ اس دن ہر آدمی اپنے چاندی کے بتوں اور سونے کے بتوں کو پھینک دے گا، جو تمہارے ہاتھوں نے تمہارے لیے گناہ کے طور پر بنائے ہیں۔ {اس کے سونے کے بتے: عبرانی۔ اس کے سونے کے بتے}\n8۔ پھر آشوری تلوار کے ساتھ مارا جائے گا، نہ کہ طاقتور آدمی کی؛ اور تلوار، جو کسی حقیر آدمی کی نہیں، اسے کھا جائے گی: لیکن وہ تلوار سے بھاگ جائے گا، اور اس کے نوجوان پریشان ہوں گے۔ {سے: یا، خوف کی وجہ سے} {پریشان: یا، شاخ: عبرانی۔ پگھلانے کے لیے، یا، خراج کے لیے}\n9۔ اور وہ خوف کے مارے اپنے مضبوط قلعے میں چلا جائے گا، اور اس کے شہزادے پرچم سے ڈریں گے، خداوند فرماتا ہے، جس کی آگ صیون میں ہے اور اس کی بھٹی یروشلم میں۔ {وہ...: عبرانی۔ اس کا پتھر خوف کی وجہ سے ختم ہو جائے گا} {اس کی مضبوط گرفت: یا، اس کی طاقت}","1. دیکھو، ایک بادشاہ راستبازی میں حکومت کرے گا، اور شہزادے فیصلے میں حکومت کریں گے۔\n2۔ اور انسان ہوا سے چھپنے کی جگہ اور طوفان سے چھپنے کی طرح ہوگا؛ خشک جگہ میں پانی کی ندیوں کی طرح، ایک تھکی ہوئی زمین میں ایک عظیم چٹان کا سایہ۔ {زبردست: عبوری۔ ہیوی}\n3۔ اور دیکھنے والوں کی آنکھیں مدھم نہیں ہوں گی، اور سننے والوں کے کان سنیں گے۔\n4۔ جلد بازی کرنے والے کا دل بھی علم کو سمجھے گا، اور ہکلانے والوں کی زبان صاف بولنے کے لیے تیار ہوگی۔ {راش: عبوری۔ جلدی میں} {سادہ طور پر: یا، خوبصورتی سے}\n5۔ بدکردار شخص کو مزید فراخ دل نہیں کہا جائے گا، اور نہ ہی وہ شخص جسے فیاض کہا جائے گا۔\n6۔ کیونکہ بدکردار شخص بدتمیزی کرے گا، اور اس کا دل بدکاری کرے گا، منافقت کرے گا، اور خداوند کے خلاف غلطی کرے گا، بھوکے کی روح کو خالی کرے گا، اور پیاسے کے مشروب کو ناکام بنا دے گا۔\n7۔ کرل کے آلات بھی برے ہیں: وہ غریبوں کو جھوٹ بول کر تباہ کرنے کے لیے برے طریقے بناتا ہے، چاہے محتاج صحیح بولے۔ {محتاج...: یا، وہ غریبوں کے خلاف فیصلے میں بولتا ہے}\n8۔ لیکن لبرل لبرل چیزیں سوچتا ہے؛ اور وہ آزادانہ چیزوں کے ساتھ کھڑا ہوگا۔ {کھڑے ہو جاؤ: یا، قائم ہو جاؤ}\n9. اٹھو، اے آرام دہ عورتوں؛ میری آواز سنو، اے لاپرواہ بیٹیو؛ میری بات سنو۔\n10۔ تم بہت دنوں اور سالوں تک پریشان رہو گی، اے لاپرواہ عورتیں: کیونکہ شراب ختم ہو جائے گی، جمع نہیں ہوگا۔ {بہت سے...: عبرانی۔ سال سے اوپر کے دن}\n11. کانپ جاؤ، اے آرام دہ عورتوں؛ پریشان ہو جاؤ، اے لاپرواہ لوگو: اپنے کپڑے اتارو، اور تمہیں ننگا کر دو، اور اپنے جسم پر {تھیل} پہن لو۔\n12۔ وہ چھاتوں، خوشگوار کھیتوں، اور پھلدار بیل کے لیے ماتم کریں گے۔ {خوشگوار...: عبرانی۔ خواہشات کے میدان}\n13۔ میرے لوگوں کی زمین پر کانٹے اور کانٹے اگیں گے؛ ہاں، خوشی کے تمام گھروں پر: {ہاں...: یا، جلتے ہوئے}\n14۔ کیونکہ محل ترک کر دیے جائیں گے؛ شہر کی اکثریت چھوڑ دی جائے گی؛ قلعے اور مینار ہمیشہ کے لیے غاروں کے لیے ہوں گے، جنگلی گدھوں کی خوشی، ریوڑوں کا چراگا؛ {قلعے...: یا، کلفٹس اور واچ ٹاورز}\n15۔ جب تک روح ہم پر بلند سے نہ برسی جائے، اور بیابان زرخیز میدان نہ بن جائے، اور زرخیز میدان جنگل شمار نہ ہو جائے۔\n16۔ پھر فیصلہ صحرا میں رہے گا، اور راستبازی زرخیز میدان میں رہے گی۔\n17۔ اور راستبازی کا کام امن ہوگا؛ اور ہمیشہ کے لیے راستبازی، خاموشی اور یقین کا اثر۔\n18۔ اور میرے لوگ پرامن رہائش گاہوں، یقینی رہائش گاہوں اور پرسکون آرام گاہوں میں رہیں گے؛\n19۔ جب جنگل پر اولے پڑیں گے؛ اور شہر ایک نیچی جگہ پر نیچے ہوگا۔ {کم میں...: یا، بالکل ذلیل ہو کر}\n20. مبارک ہو وہ لوگ جو تمام پانیوں کے کنارے بیج بوتے ہیں، جو بیل اور گدھے کے پاؤں بھیجتے ہیں۔","1. تم پر افسوس جو سب سے زیادہ بگاڑتا ہے، اور تم نے خراب نہیں کیا؛ اور دھوکہ دہی سے پیش آیا، اور انہوں نے تمہارے ساتھ دھوکہ نہیں دیا! جب تم خراب ہونا بند کرو گے، تو تم بگڑ جاؤ گے؛ {اور} جب تم دھوکہ دہی کا خاتمہ کرو گے، تو وہ تمہارے ساتھ دھوکہ کریں گے۔\n2. اے خداوند، ہم پر مہربان ہو؛ ہم نے تمہارا انتظار کیا ہے: ہر صبح تو ان کا بازو بنو، ہماری نجات بھی مشکل وقت میں۔\n3۔ ہنگامے کی آواز پر لوگ بھاگ گئے؛ جب آپ نے خود کو اٹھایا تو قومیں بکھر گئیں۔\n4۔ اور تمہارا مال جمع کیا جائے گا {ویسے} جیسے کیٹرپیلر کے جمع کرنے والے کے ساتھ: جیسے وہ ٹڈی دل کے دوڑتے ہوئے ان پر دوڑے گا۔\n5. خداوند بلند ہے؛ کیونکہ وہ بلند مقام پر رہتا ہے: اس نے صیون کو انصاف اور راستبازی سے بھر دیا ہے۔\n6۔ اور حکمت اور علم تیرے زمانے کی استحکام ہوں گے، {اور} نجات کی طاقت: خداوند کا خوف {ہے} اس کا خزانہ۔ {نجات: عبرانی۔ نجات}\n7۔ دیکھو، ان کے بہادر باہر پکار رہے ہیں: امن کے سفیر تلخ روتے ہیں۔ {بہادر...: یا، پیغامبر}\n8۔ راستے ویران ہو جاتے ہیں، مسافر رک جاتا ہے: اس نے عہد توڑ دیا ہے، اس نے شہروں سے نفرت کی ہے، وہ کسی کو نہیں دیکھتا۔\n9. زمین غمگین ہے {اور} زوال پذیر ہے: لبنان شرمندہ ہے {اور} کاٹ دیا گیا ہے: شارون ایک صحرا کی مانند ہے؛ اور باشان اور کارمل اپنے پھلوں کو جھاڑتے ہیں۔ {کٹا ہوا...: یا، مرجھا گیا}\n10۔ اب میں اٹھوں گا، خداوند فرماتا ہے؛ اب میں بلند ہوں گا؛ اب میں خود کو اٹھاؤں گا۔\n11۔ تم بھوسے کو حاملہ کرو گے، تم داڑھی نکالو گے: تمہاری سانس، {آگ} کی طرح، تمہیں نگل جائے گی۔\n12۔ اور لوگ چونے کے جلنے کی طرح ہوں گے: جیسے کانٹے کٹے جائیں گے، انہیں آگ میں جلایا جائے گا۔\n13. سنو، اے دور ہو، کہ میں نے کیا کیا ہے؛ اور، تم لوگ جو قریب ہو، میری طاقت کو تسلیم کرو۔\n14۔ صہیون کے گناہ گار خوفزدہ ہیں؛ خوف نے منافقوں کو حیران کر دیا ہے۔ ہم میں سے کون اس آگ کے ساتھ رہے گا؟ ہم میں سے کون ہمیشہ کے لیے جلنے کے ساتھ رہے گا؟\n15۔ جو راستبازی سے چلتا ہے اور صاف گوئی سے بولتا ہے؛ جو ظلم کے فائدے سے نفرت کرتا ہے، جو رشوت لینے سے ہاتھ ہلاتا ہے، جو خون کی باتیں سننے سے اس کے کانوں کو روک دیتا ہے، اور برائی دیکھنے سے اپنی آنکھیں بند کر لیتا ہے؛ {درستگی سے: عبرانی۔ راستبازی میں} {سیدھے سادے انداز میں: عبرانی۔ راست راست} {ظلم: یا، دھوکہ دہی} {خون: عبرانی۔ bloods}\n16۔ وہ بلند مقام پر رہے گا: اس کی حفاظت کی جگہ چٹانوں کے گولہ بارود ہوں گے: اسے روٹی دی جائے گی؛ اس کا پانی {یقینا} ہوگا۔ {اونچا: ہیب۔ اونچائیاں، یا، اونچی جگہیں}\n17۔ تمہاری آنکھیں بادشاہ کو اس کی خوبصورتی میں دیکھیں گی: وہ اس دور دراز زمین کو دیکھیں گی۔ {وہ...: عبرانی۔ دور دراز دوریوں سے}\n18۔ تمہارا دل دہشت پر غور کرے گا۔ کاتب کہاں ہے؟ ریسیور کہاں ہے؟ وہ کہاں ہے جس نے ٹاورز گنے؟ {وصول کنندہ: ہیب۔ وزن؟}\n19۔ تم ایک سخت قوم کو نہیں دیکھو گے، ایسی قوم جو تمہاری نظر سے زیادہ گہری زبان کی ہو؛ ایک ہچکچاتی ہوئی زبان کی، {جسے تم سمجھ نہیں سکتے}۔ {ہچکچاتے ہوئے: یا، مضحکہ خیز}\n20۔ صیون کو دیکھو، جو ہماری تقریبات کا شہر ہے: تمہاری آنکھیں یروشلم کو دیکھیں گی، ایک پرسکون رہائش گا، ایک خیمہ جو کبھی نہیں گرایا جائے گا؛ اس کے ایک بھی کھمبے کبھی نہیں ہٹے جائیں گے، نہ ہی اس کی کوئی رسی ٹوٹی جائے گی۔\n21. لیکن وہاں جلال یافتہ خداوند {ہوگا} ہمارے لیے وسیع دریاؤں {اور} ندیوں کی جگہ ہوگا؛ جہاں کوئی کشتی چپو لے کر نہیں جائے گی، نہ ہی بہادر جہاز وہاں سے گزرے گا۔ {of...: عبرانی۔ وسیع جگہیں، یا ہاتھیں}\n22۔ کیونکہ خداوند ہمارا منصف ہے، خداوند ہمارا قانون ساز ہے، خداوند ہمارا بادشاہ ہے؛ وہ ہمیں بچائے گا۔ {قانون ساز: عبرانی۔ statutemaker}\n23. تمہاری لپیٹ کھول دی جاتی ہے؛ وہ اپنے ماسٹ کو مضبوط نہیں کر سکے، نہ ہی بادبان بکھیر سکے: پھر بڑی مال غنیمت کا شکار تقسیم ہو جاتا ہے؛ لنگڑے شکار کو لے جاتے ہیں۔ {تمہاری...: یا، انہوں نے تمہارے کام چھوڑ دیے ہیں}\n24۔ اور رہائشی یہ نہیں کہے گا کہ میں بیمار ہوں: جو لوگ وہاں رہتے ہیں {ان کی} گناہوں کو معاف کیا جائے گا۔","1. اے قوموں، قریب آؤ، سنو؛ اور سنو، اے لوگو: زمین اور اس میں موجود سب کچھ سنو؛ دنیا، اور اس سے نکلنے والی تمام چیزیں۔ {یہ سب...: عبرانی۔ اس کی مکمل شدت}\n2۔ کیونکہ خداوند کا غصہ تمام قوموں پر ہے، اور ان کی تمام فوجوں پر اس کا غصہ: اس نے انہیں مکمل طور پر تباہ کر دیا ہے، انہیں ذبح کے حوالے کر دیا ہے۔\n3۔ ان کے مقتول بھی نکالے جائیں گے، ان کی بدبو ان کے لاشوں سے نکلے گی، اور پہاڑ ان کے خون سے پگھل جائیں گے۔\n4۔ اور آسمان کی ساری فوج تحلیل ہو جائے گی، اور آسمان ایک لول کی طرح لپٹ جائیں گے: اور ان کا سارا لشکر نیچے گرے گا، جیسے پتا بیل سے گرتا ہے، اور انجیر کے درخت سے گرتا ہے۔\n5۔ کیونکہ میری تلوار آسمان میں نہائے گی: دیکھو، وہ ایدومیا اور میرے لعنت کے لوگوں پر نازل ہوگی۔\n6۔ خداوند کی تلوار خون سے بھری ہوئی ہے، یہ چربی سے موٹی ہو جاتی ہے، {اور} بھیڑ اور بکریوں کے خون سے، مینڈوں کے گردوں کی چربی سے: کیونکہ خداوند نے بوزرہ میں قربانی دی ہے، اور ایدومیا کی سرزمین میں بڑا ذبح کیا ہے۔\n7۔ اور یونیکورن ان کے ساتھ نیچے آئیں گے، اور بیل بیلوں کے ساتھ؛ اور ان کی زمین خون میں بھیگ جائے گی، اور ان کی خاک چربی سے موٹی ہو جائے گی۔ {یونیکورن: یا، گینڈے} {بھیگا ہوا: یا، نشے میں}\n8. کیونکہ {یہ} خداوند کے انتقام کا دن ہے، {اور} صہیون کے تنازعے کے بدلے کا سال ہے۔\n9۔ اور اس کی ندیاں قیر میں بدل جائیں گی، اور اس کی خاک گندھک میں بدل جائے گی، اور اس کی زمین جلتی ہوئی قیر بن جائے گی۔\n10۔ رات یا دن نہ رات کو بجھایا جائے گا؛ اس کا دھواں ہمیشہ کے لیے اٹھے گا: نسل در نسل یہ ضائع ہو جائے گا؛ کوئی بھی ہمیشہ کے لیے اس سے گزرے گا۔\n11۔ لیکن کورمورینٹ اور بٹرن اسے حاصل کریں گے؛ الو اور کوا بھی اس میں رہیں گے: اور وہ اس پر الجھن کی لکیر اور خالی پن کے پتھر پھیلائے گا۔ {کورمورینٹ: یا، پیلیکن}\n12۔ وہ اس کے اشرافیہ کو بادشاہت میں بلائیں گے، لیکن وہاں کوئی نہیں ہوگا، اور اس کے تمام شہزادے کچھ نہیں ہوں گے۔\n13۔ اور اس کے محلوں میں کانٹے نکلیں گے، قلعوں میں کانٹے اور کانٹے دار درخت ہوں گے: اور یہ ڈریگنوں کا مسکن ہوگا، {اور} الوؤں کے لیے ایک صحن۔ {الو: یا، شتر مرغ: عبوری۔ بیٹیاں آف دی آول}\n14۔ صحرا کے جنگلی جانور بھی جزیرے کے جنگلی جانوروں سے ملیں گے، اور سیٹر اپنے ساتھی کو پکارے گا؛ اسکریچ الو بھی وہاں آرام کرے گا، اور اپنے لیے آرام کی جگہ تلاش کرے گا۔ {جنگلی... صحرا: عبرانی۔ زیم} {جنگلی... جزیرہ: عبرانی۔ ایجم} {چیخ...: یا، رات کا عفریت}\n15۔ وہاں بڑا الو اپنا گھونسلا بنائے گا، اور بچے گا، انڈے نکلے گا، اور اس کے سائے تلے جمع ہوگا: وہاں گدھ بھی جمع ہوں گے، ہر ایک اپنے ساتھی کے ساتھ۔\n16۔ خداوند کی کتاب سے تلاش کرو، اور پڑھو: ان میں سے کوئی ناکام نہیں ہوگا، کوئی اس کی ساتھی کو نہیں چاہے گا: کیونکہ میرے منہ نے حکم دیا ہے، اور اس کی روح نے انہیں جمع کیا ہے۔\n17۔ اور اس نے ان کے لیے قرعہ ڈال دیا ہے، اور اس کے ہاتھ نے انہیں لائن میں تقسیم کر دیا ہے: وہ ہمیشہ کے لیے اس کے مالک رہیں گے، نسل در نسل وہاں رہیں گے۔","1۔ بیابان اور تنہا جگہ ان کے لیے خوش ہوں گی؛ اور صحرا خوش ہوگا، اور گلاب کی طرح کھلے گا۔\n2۔ یہ خوب کھلے گا، اور خوشی اور گانے سے خوش ہوگا: لبنان کی شان اسے دی جائے گی، کرمل اور شیرون کی عظمت، وہ خداوند کی شان دیکھیں گے، {اور} ہمارے خدا کی عظمت کو دیکھیں گے۔\n3۔ کمزور ہاتھوں کو مضبوط کرو، اور کمزور گھٹنوں کو مضبوط کرو۔\n4. ان لوگوں سے کہو جو دل خوفزدہ ہیں، مضبوط رہو، ڈرو مت: دیکھو، تمہارا خدا انتقام لے کر آئے گا، اور خدا کو بھی بدلہ ملے گا؛ وہ آئے گا اور تمہیں بچائے گا۔ {خوفزدہ: عبرانی۔ جلدی میں}\n5۔ پھر اندھے کی آنکھیں کھل جائیں گی، اور بہروں کے کان بغیر رکاوٹ کے رکے جائیں گے۔\n6۔ پھر لنگڑا {انسان} ہرن کی طرح چھلانگ لگائے گا، اور گونگے کی زبان گائے گی: کیونکہ بیابان میں پانی پھوٹے گا، اور صحرا میں ندی نالے۔\n7۔ اور خشک زمین تالاب بن جائے گی، اور پیاسی زمین پانی کے چشمے بنے گی: ڈریگنوں کے گھر میں، جہاں ہر ایک پڑے گا، گھاس ہوگی جس میں گھاس اور جھاڑیاں ہوں گی۔ {گھاس...: یا، ریڈز کے لیے کورٹ وغیرہ}\n8۔ اور وہاں ایک شاہراہ ہوگی، اور ایک راستہ، اور اسے پاکیزگی کا راستہ کہا جائے گا؛ ناپاک اس پر نہیں گزرے گا؛ لیکن یہ ان لوگوں کے لیے ہوگا: مسافر لوگ، چاہے بے وقوف ہی کیوں نہ ہوں، غلطی نہیں کریں گے۔ {لیکن...: یا، کیونکہ وہ ان کے ساتھ ہوگا}\n9۔ وہاں کوئی شیر نہیں ہوگا، نہ کوئی بھوکا جانور وہاں جائے گا، وہ وہاں نہیں ملے گا؛ لیکن نجات پانے والے {وہاں} چلیں گے:\n10۔ اور خداوند کے فدیہ پانے والے واپس آئیں گے، اور اپنے سروں پر گیتوں اور دائمی خوشی کے ساتھ صیون آئیں گے: انہیں خوشی اور خوشی ملے گی، اور غم اور آہیں دور ہو جائیں گی۔","1۔ اب بادشاہ حزقیاہ کے چودہویں سال میں یہ ہوا کہ آشور کا بادشاہ سناخریب یہوداہ کے تمام محفوظ شہروں کے خلاف آیا اور انہیں فتح کر لیا۔\n2۔ اور آشور کے بادشاہ نے ربشکہ کو لاخیش سے یروشلم بھیجا، بادشاہ حزقیاہ کے پاس ایک بڑی فوج کے ساتھ۔ اور وہ فلرز فیلڈ کی ہائی وے میں اوپری تالاب کے کنڈویٹ کے پاس کھڑا تھا۔\n3۔ پھر اس کے پاس ایلیاکیم، حلقیاہ کا بیٹا، جو گھر کے اوپر تھا، اور شبنا کاتب اور یوح، آساف کا بیٹا، ریکارڈ کرنے والا آیا۔ {کاتب: یا، سیکرٹری}\n4۔ اور ربشاکہ نے ان سے کہا، اب حزقیاہ سے کہو، یہی عظیم بادشاہ، آشور کے بادشاہ نے فرمایا، کہ تم کس اعتماد پر بھروسہ کرتے ہو؟\n5. میں کہتا ہوں، {کیا تم کہہ رہے ہو}، (لیکن {یہ صرف فضول باتیں ہیں} {میرے پاس جنگ کے لیے مشورہ اور طاقت ہے}: اب تم کس پر بھروسہ کرتے ہو کہ تم میرے خلاف بغاوت کرتے ہو؟ {vanin...: عبرانی ایک لفظ} {میرے پاس ہے...: یا، لیکن مشورہ اور طاقت جنگ کے لیے ہیں}\n6۔ دیکھو، تم اس ٹوٹے ہوئے سرکنڈے کے عصا پر بھروسہ کرتے ہو، مصر پر؛ اگر کوئی آدمی جھکے تو وہ اس کے ہاتھ میں چلا جائے گا، اور اسے چیر دے گا: اسی طرح مصر کا فرعون بادشاہ ہے ان سب لوگوں کے لیے جو اس پر بھروسہ کرتے ہیں۔\n7. لیکن اگر تم مجھ سے کہو، ہم اپنے خداوند خدا پر بھروسہ کرتے ہیں: کیا وہ نہیں جس کے اونچے مقامات اور قربان گاہیں حزقیاہ نے لے لی ہیں، اور یہوداہ اور یروشلم سے کہا ہے کہ تم اس قربان گاہ کے سامنے عبادت کرو گے؟\n8۔ اب میں تم سے درخواست کرتا ہوں کہ میرے آقا آشور کے بادشاہ سے وعدے کرو، اور میں تمہیں دو ہزار گھوڑے دوں گا، اگر تم ان پر سوار بٹھا سکو۔ {وعدے: یا، یرغمالی}\n9۔ تو پھر تم میرے آقا کے سب سے چھوٹے خادموں میں سے ایک کپتان کا چہرہ کیسے موڑ لو گے، اور مصر پر رتھ اور گھڑ سواروں کے لیے بھروسہ کرو گے؟\n10. اور کیا اب میں خدا کے بغیر اس زمین کے خلاف آ رہا ہوں جو اسے تباہ کر دے؟ خداوند نے مجھ سے کہا، اس زمین کے خلاف جاؤ اور اسے تباہ کر دو۔\n11۔ پھر الیاقیم، شبنا اور جوح نے ربشاکہ سے کہا، میں تم سے دعا کرتا ہوں کہ اپنے بندوں سے شامی زبان میں بات کرو؛ کیونکہ ہم سمجھتے ہیں: اور ہم سے یہودیوں کی زبان میں، ان لوگوں کے کانوں میں بات نہیں کرتے جو دیوار پر ہیں۔\n12۔ لیکن ربشاکہ نے کہا، کیا میرے آقا نے مجھے تمہارے آقا اور تمہارے پاس یہ الفاظ کہنے کے لیے بھیجا ہے؟ کیا اس نے مجھے ان لوگوں کے پاس نہیں بھیجا جو دیوار پر بیٹھے ہیں، تاکہ وہ اپنا گوبر کھائیں اور تمہارے ساتھ اپنا پیشاب پی سکیں؟\n13۔ پھر ربشکہ کھڑا ہوا، اور یہودیوں کی زبان میں بلند آواز میں پکارا، اور کہا، عظیم بادشاہ، آشور کے بادشاہ کے الفاظ سنو۔\n14۔ بادشاہ یہ فرماتا ہے، حزقیاہ تمہیں دھوکہ نہ دے، کیونکہ وہ تمہیں نجات نہیں دے سکے گا۔\n15۔ نہ ہی حزقیاہ تمہیں خداوند پر بھروسہ کرنے پر مجبور کرے، یہ کہتے ہوئے، خداوند ہمیں ضرور بچا لے گا: یہ شہر آشور کے بادشاہ کے ہاتھ میں نہیں دیا جائے گا۔\n16۔ حزقیاہ کی بات نہ سنو: کیونکہ آشور کے بادشاہ نے یہی فرمایا، مجھ سے {ایک معاہدہ} کرو {تحفہ} کے ذریعے، اور میرے پاس آؤ، اور اس کی انگور اور اس کے انجیر کے ہر درخت کو کھاؤ، اور ہر ایک کو اس کے اپنے حوض کے پانی سے پیو؛ {بنا...: یا، میری عنایت ایک تحفے کے ذریعے حاصل کرو: عبرانی۔ میرے ساتھ دعا کرو}\n17. جب تک میں آ کر تمہیں تمہاری اپنی زمین کی طرح لے جاؤں، مکئی اور شراب کی سرزمین، روٹی اور انگور کے باغات کی سرزمین۔\n18. {خبردار} کہ حزقیاہ تمہیں قائل کر دے گا کہ خداوند ہمیں نجات دے گا۔ کیا قوموں کے کسی دیوتاؤں نے اس کی سرزمین کو آشور کے بادشاہ کے ہاتھوں سے بچایا ہے؟\n19. حماتھ اور ارفاد کے دیوتا کہاں ہیں؟ سیفارویم کے دیوتا کہاں ہیں؟ اور کیا انہوں نے سامریا کو میرے ہاتھ سے آزاد کر دیا ہے؟\n20۔ ان زمینوں کے تمام دیوتاؤں میں سے کون ہیں، جنہوں نے اپنی زمین میرے ہاتھ سے چھین لی ہے، کہ خداوند یروشلم کو میرے ہاتھ سے آزاد کرے؟\n21۔ لیکن وہ خاموش رہے، اور اس کا ایک لفظ بھی جواب نہ دیا: کیونکہ بادشاہ کا حکم تھا، \"اسے جواب نہ دو۔\"\n22۔ پھر الیاقیم، ہلکیاہ کا بیٹا، جو گھر کے سربراہ تھا، اور شبنا کاتب اور یوح، آصف کا بیٹا، ریکارڈر، حزقیاہ کے پاس آئے اور ان کے کپڑے پھاڑ دیے اور ربشکہ کے الفاظ سنائے۔","1۔ اور ایسا ہوا جب بادشاہ حزقیاہ نے سنا، کہ اس نے اپنے کپڑے پھاڑ دیے، خود کو تھیلے کے کپڑے سے ڈھانپ لیا، اور خداوند کے گھر میں چلا گیا۔\n2۔ اور اس نے ایلیاکیم کو، جو گھرانے کا سربراہ تھا، اور شیبنا کاتب کو، اور کاہنوں کے بزرگوں کو جو تھیلے کپڑے میں لپٹے ہوئے تھے، اشعیا نبی کے پاس بھیجا، جو اموز کا بیٹا تھا۔\n3۔ اور انہوں نے اس سے کہا، حزقیاہ یوں فرماتا ہے، آج دن مصیبت، ملامت اور کفر کا دن ہے: کیونکہ بچے پیدائش کے لیے آئے ہیں، اور پیدا کرنے کی طاقت نہیں۔ {کفر: یا، اشتعال انگیزی}\n4. شاید خداوند تیرا خدا ربشاکہ کے الفاظ سنے، جسے آشور کے بادشاہ نے زندہ خدا کو ملامت کرنے کے لیے بھیجا ہے، اور وہ ان الفاظ کو ملامت کرے جو خداوند تیرے خدا نے سنے ہیں: لہٰذا باقی بچا ہوا باقی ماندہ کے لیے اپنی دعا اٹھاؤ۔ {بائیں: عبرانی۔ مل گیا}\n5۔ یوں بادشاہ حزقیاہ کے خادم یسعیاہ کے پاس آئے۔\n6۔ اور یسعیاہ نے ان سے کہا، \"تم اپنے آقا سے یہی کہو گے، خداوند نے فرمایا، ان الفاظ سے نہ ڈرو جو تم نے سنے، جن سے آشور کے بادشاہ کے بندوں نے میری کفر کی ہے۔\n7۔ دیکھو، میں اس پر ایک دھماکہ بھیجوں گا، اور وہ افواہ سنے گا، اور اپنے ملک واپس چلے گا؛ اور میں اسے اس کی اپنی زمین میں تلوار کے ہاتھوں مارنے پر مجبور کروں گا۔ {بھیجو...: یا، اس میں کوئی روح ڈال دو}\n8۔ تو ربشکہ واپس آیا، اور دیکھا کہ آشور کا بادشاہ لبنہ کے خلاف جنگ کر رہا ہے: کیونکہ اس نے سنا تھا کہ وہ لاخیش سے چلا گیا ہے۔\n9۔ اور اس نے سنا کہ ایتھوپیا کے بادشاہ ترحکہ کے بارے میں کہا گیا ہے، وہ تم سے جنگ کرنے آیا ہے۔ اور جب اس نے سنا، تو اس نے حزقیاہ کے پاس پیغام بھیجے اور کہا،\n10۔ یوں تم یہوداہ کے بادشاہ حزقیاہ سے بات کرو گے، کہو کہ اپنے خدا کو، جس پر تم بھروسہ کرتے ہو، تمہیں دھوکہ نہ دے، اور کہیں کہ یروشلم کو آشور کے بادشاہ کے ہاتھ میں نہیں دیا جائے گا۔\n11۔ دیکھو، تم نے سنا ہے کہ آشور کے بادشاہوں نے تمام زمینوں کو مکمل طور پر تباہ کر کے کیا کیا؛ اور کیا تم آزاد ہو جاؤ گے؟\n12. کیا قوموں کے دیوتاؤں نے انہیں نجات دی ہے جنہیں میرے آباؤ اجداد نے تباہ کیا، {جیسا کہ} گوزان، اور ہاران، اور ریزف، اور عدن کے بچے جو تیلاسر میں {تھے}؟\n13. حمتھ کا بادشاہ، ارفاد کا بادشاہ، اور شہر سیفروایم، حنا اور ایوا کا بادشاہ کہاں ہے؟\n14۔ اور حزقیاہ نے پیغامبروں کے ہاتھ سے خط وصول کیا اور اسے پڑھا: اور حزقیاہ خداوند کے گھر گیا اور اسے خداوند کے سامنے پھیلایا۔\n15۔ اور حزقیاہ نے خداوند سے دعا کی، کہا،\n16. اے لشکروں کے رب، اسرائیل کے خدا، جو کروبیوں کے درمیان رہتا ہے، تو {تو} خدا ہے، {حتی} صرف تو، زمین کی تمام بادشاہتوں کا: تو نے آسمان اور زمین کو بنایا ہے۔\n17. اے خداوند، اپنا کان جھکا کر سنو؛ اے خداوند، اپنی آنکھیں کھولو، اور دیکھو: اور سنخریب کے تمام الفاظ سنو، جو زندہ خدا کو ملامت کرنے کے لیے بھیجے گئے ہیں۔\n18۔ اے خداوند، ایک سچائی کے طور پر، آشور کے بادشاہوں نے تمام قوموں اور ان کے ملکوں کو تباہ کر دیا ہے، {قومیں: عبرانی۔ زمینیں}\n19۔ اور انہوں نے اپنے دیوتاؤں کو آگ میں پھینک دیا: کیونکہ وہ کوئی خدا نہیں تھے، بلکہ انسانوں کے ہاتھوں، لکڑی اور پتھر کا کام تھا: اس لیے انہوں نے انہیں تباہ کر دیا۔ {کاسٹ: عبوری۔ دیا گیا}\n20۔ اب، اے خداوند ہمارے خدا، ہمیں اس کے ہاتھ سے بچا لے، تاکہ زمین کی تمام بادشاہتیں جان سکیں کہ تو خداوند ہی ہے، {حتیٰ کہ} تو صرف تو۔\n21۔ پھر یسعیاہ کے بیٹے اموز نے حزقیاہ کے پاس بھیجا اور کہا، \"یہی فرماتا ہے اسرائیل کے خداوند خدا، جبکہ تو نے مجھ سے آشور کے بادشاہ سناخریب کے خلاف دعا کی ہے:\n22. یہ وہ کلام ہے جو خداوند نے اس کے بارے میں کہا ہے؛ کنواری، صیہون کی بیٹی، نے تمہیں حقیر سمجھا، {اور} تمہیں طنز کے لیے ہنسا؛ یروشلم کی بیٹی نے تم پر سر ہلا دیا ہے۔\n23۔ تم نے کس کو ملامت اور کفر کیا ہے؟ اور کس کے خلاف تم نے اپنی آواز بلند کی، اور اپنی آنکھیں بلند کیں؟ {حتیٰ کہ} اسرائیل کے مقدس وجود کے خلاف۔\n24۔ اپنے بندوں کے ذریعے تو نے خداوند کو ملامت کی اور کہا، اپنی رتھوں کی کثرت سے میں پہاڑوں کی بلندی تک پہنچا ہوں، لبنان کے کناروں تک؛ اور میں اس کے اونچے دیودار کاٹوں گا، {اور} ان کے منتخب صنوبر کے درخت: اور میں اس کی سرحد کی بلندی تک داخل ہو جاؤں گا، {اور} اس کے کرمل کے جنگل میں۔ {تمہارے...: عبرانی کی قسم۔ تمہارے خادموں کے ہاتھوں سے} {لمبا...: عبرانی۔ ان کے دیودار درختوں کی اونچائی اور ان میں سے فر کے درختوں کا انتخاب} {جنگل...: یا، جنگل اور اس کا زرخیز میدان}\n25۔ میں نے کھودا اور پانی پیا؛ اور اپنے پاؤں کے تلوے سے میں نے محصور علاقوں کی تمام ندیاں خشک کر دی ہیں۔ {محصور: یا، باڑ اور بند}\n26. کیا تم نے بہت پہلے نہیں سنا کہ میں نے یہ کیسے کیا؟ {اور} قدیم زمانے کی، کہ میں نے اسے تشکیل دیا ہے؟ اب میں نے یہ حقیقت بنا دی ہے کہ تم محفوظ شہروں کو تباہ کر دو۔ {جلدی کرو...: یا، کیا تم نے نہیں سنا کہ میں نے اسے بہت پہلے بنایا اور قدیم زمانے کی شکل دی؟ کیا اب میں اسے تباہ کر دوں، اور محفوظ شہروں کو تباہ کن ڈھیر بنا دوں؟}\n27۔ اسی لیے ان کے باشندے کم طاقت والے تھے، وہ مایوس اور پریشان تھے: وہ کھیت کی گھاس کی طرح تھے، اور سبز جڑی بوٹی، گھروں کی چھتوں پر گھاس کی طرح، اور مکئی کی طرح جو اگنے سے پہلے اڑتی تھی۔ {چھوٹے...: عبرانی۔ ہاتھ کم ہے}\n28۔ لیکن میں تمہارا گھر جانتا ہوں، تمہارا جانا، تمہارا آنا، اور تمہارا میرے خلاف غصہ جانتا ہوں۔ {رہائش: یا، بیٹھنا}\n29۔ کیونکہ تمہارا غصہ اور تمہارا ہنگامہ میرے کانوں تک پہنچ گیا ہے، اس لیے میں اپنا کانٹا تمہاری ناک میں رکھوں گا، اور اپنی لگام تمہارے ہونٹوں میں رکھوں گا، اور میں تمہیں اس راستے سے واپس پلٹاؤں گا جس سے تم آئے ہو۔\n30۔ اور یہ {تمہارے} کے لیے ایک نشانی ہوگی، تم {یہ} سال کھاؤ گے جو خود سے اگتا ہے؛ اور دوسرے سال جو اسی سے نکلتا ہے: اور تیسرے سال بوئیں، کاٹیں، انگور کے باغ لگائیں اور ان کے پھل کھائیں۔\n31. اور یہوداہ کے گھر سے بچ جانے والا باقیات دوبارہ نیچے کی طرف جڑ پکڑے گا، اور اوپر پھل دے گا: {باقی ماندہ...: عبرانی۔ یہوداہ کے گھرانے کا فرار جو باقی ہے}\n32۔ کیونکہ یروشلم سے ایک باقیات نکلیں گی، اور جو کوہ صیون سے نکلیں گے: خداوند لشکروں کا جوش یہی کرے گا۔ {وہ...: عبرانی۔ دی ایسکیپنگ}\n33۔ لہٰذا خداوند آشور کے بادشاہ کے بارے میں یوں فرماتا ہے، وہ اس شہر میں نہیں آئے گا، نہ وہاں تیر چلے گا، نہ ڈھالوں کے ساتھ آئے گا، نہ اس پر کوئی کنارہ ڈالے گا۔\n34۔ جس راستے سے وہ آیا، اسی راستے سے واپس آئے گا، اور اس شہر میں نہیں آئے گا، خداوند فرماتا ہے۔\n35۔ کیونکہ میں اس شہر کا دفاع کروں گا تاکہ اسے اپنی خاطر اور اپنے خادم داؤد کے لیے بچاؤں۔\n36۔ پھر خداوند کا فرشتہ باہر آیا اور آشوریوں کے کیمپ میں ایک سو چولیس پانچ ہزار کو مارا، اور جب وہ صبح سویرے اٹھے، تو وہ سب مردہ لاشیں تھے۔\n37۔ یوں آشور کا بادشاہ سنحریب، روانہ ہوا، اور واپس آیا، اور نینوا میں بسنے لگا۔\n38۔ اور جب وہ اپنے خدا نسرخ کے گھر میں عبادت کر رہا تھا، تو اس کے بیٹوں ادرامیلخ اور شارزر نے اسے تلوار سے مارا؛ اور وہ آرمینیا کی سرزمین میں فرار ہو گئے: اور اس کا بیٹا اسرحدون اس کی جگہ حکومت کرنے لگا۔ {آرمینیا: عبرانی۔ ارارات}","1۔ ان دنوں حزقیاہ موت کے قریب بیمار تھا۔ اور یسعیاہ نبی اموز کا بیٹا اس کے پاس آیا اور کہا، خداوند نے یوں فرمایا، اپنے گھر کو ترتیب دے، کیونکہ تم مر جاؤ گے اور زندہ نہیں رہو گے۔ {سیٹ...: عبرانی اپنے گھر کی ذمہ داری دو}\n2۔ پھر حزقیاہ نے اپنا چہرہ دیوار کی طرف موڑا اور خداوند سے دعا کی،\n3۔ اور کہا، اے خداوند، اب یاد کر، میں تجھ سے التجا کرتا ہوں کہ میں سچائی اور کامل دل کے ساتھ تیرے سامنے چلا ہوں، اور تیری نظر میں اچھا کیا ہے۔ اور حزقیاہ شدید آنسو بہانے لگا۔ {درد: عبوری۔ بڑے رونے کے ساتھ}\n4۔ پھر خداوند کا کلام یسعیاہ کو آیا، جس میں کہا،\n5۔ جاؤ، اور حزقیاہ سے کہو، یہ فرماتا ہے رب، داؤد کا خدا، تمہارا باپ، میں نے تمہاری دعا سنی ہے، میں نے تیرے آنسو دیکھے ہیں: دیکھو، میں تیرے دنوں میں پندرہ سال کا اضافہ کروں گا۔\n6۔ اور میں تمہیں اور اس شہر کو آشور کے بادشاہ کے ہاتھوں سے آزاد کروں گا: اور میں اس شہر کا دفاع کروں گا۔\n7۔ اور یہ {یہ} آپ کے لیے خداوند کی طرف سے ایک نشانی ہوگی کہ خداوند وہ کام کرے گا جو اس نے کہا ہے؛\n8۔ دیکھو، میں دوبارہ ڈگریوں کا سایہ لے آؤں گا، جو آہاز کے سن ڈائل میں دس ڈگری پیچھے جا رہا ہے۔ تو سورج دس ڈگری واپس آیا، جس کے بعد وہ غروب ہو گیا۔ {سن ڈائل: عبوری۔ ڈگری بائی، یا، سورج کے ساتھ}\n9۔ یہوداہ کے بادشاہ حزقیاہ کی تحریر، جب وہ بیمار تھا اور اپنی بیماری سے صحت یاب ہوا تھا:\n10۔ میں نے اپنی زندگی کے اختتام پر کہا، میں قبر کے دروازوں تک جاؤں گا: میں اپنی عمر کے باقیات سے محروم ہوں۔\n11۔ میں نے کہا، میں خداوند کو نہیں دیکھوں گا، {حتیٰ کہ} خداوند کو بھی، زندہ زمین میں: میں اب انسان کو دنیا کے باشندوں کے ساتھ نہیں دیکھوں گا۔\n12۔ میری عمر ختم ہو چکی ہے، اور مجھ سے چرواہے کے خیمے کی طرح اتار دی گئی ہے: میں نے بنائی کی طرح اپنی زندگی کاٹ دی ہے: وہ مجھے بیماری سے کاٹ دے گا: دن سے رات تک تم میرا خاتمہ کرو گے۔ {ساتھ...: یا، دھڑکن سے}\n13۔ میں نے صبح تک سوچا تھا {کہ} جیسے شیر میری تمام ہڈیاں توڑے گا: دن سے رات تک تم مجھے ختم کرو گے۔\n14. جیسے کرین {یا} ایک ابابیل، میں نے بھی باتیں کیں: میں نے کبوتر کی طرح سوگ منایا: میری آنکھیں اوپر دیکھ کر بند ہو جاتی ہیں: اے خداوند، میں مظلوم ہوں؛ میرے لیے کام کرو۔ {ذمہ داری...: یا، مجھے آرام دیں}\n15۔ میں کیا کہوں؟ اس نے مجھ سے بات کی ہے، اور خود بھی کہہ دیا ہے: میں اپنی تمام عمر اپنی روح کی تلخی میں نرم دل رہوں گا۔\n16. اے خداوند، ان {چیزوں سے} لوگ زندہ ہیں، اور ان سب {چیزوں} میں میری روح کی زندگی ہے: تو مجھے بحال کرو گے اور زندہ رکھو گے۔\n17۔ دیکھو، امن کے لیے مجھے بہت تلخی ملی، لیکن تو نے میری روح سے محبت میں {اسے فساد کے گڑھے سے نجات دلائی}: کیونکہ تم نے میرے سارے گناہ اپنی پیٹھ پیچھے پھینک دیے۔ {امن کے لیے...: یا، میری امن پر بڑی تلخی آ گئی} {آپ نے...: عبرانی میں ہے۔ تم نے میری روح سے گڑھے سے محبت کی ہے}\n18۔ کیونکہ قبر تمہاری تعریف نہیں کر سکتی، موت تمہیں خوش نہیں کر سکتی: جو گڑھے میں جاتے ہیں وہ تیری سچائی کی امید نہیں رکھتے۔\n19۔ زندہ، زندہ، وہ تمہاری تعریف کرے گا، جیسا کہ میں آج کرتا ہوں: بچوں کا باپ تمہاری سچائی کو ظاہر کرے گا۔\n20. خداوند {تیار تھا} مجھے بچانے کے لیے: اس لیے ہم اپنی زندگی کے تمام دن خداوند کے گھر میں میرے گیت تار والے سازوں پر گائیں گے۔\n21۔ کیونکہ یسعیاہ نے کہا تھا، وہ انجیر کا ایک گٹھا لے کر پھوڑے پر لگا دیں، پھر وہ ٹھیک ہو جائے گا۔\n22۔ حزقیاہ نے یہ بھی کہا تھا، یہ کیا نشانی ہے کہ میں خداوند کے گھر جا رہا ہوں؟","1۔ اسی وقت بابل کے بادشاہ بالادان کے بیٹے میروداخبالادان نے حزقیاہ کو خطوط اور تحفہ بھیجا: کیونکہ اس نے سنا تھا کہ وہ بیمار ہے اور صحت یاب ہو گیا ہے۔\n2۔ اور حزقیاہ ان پر خوش ہوا، اور انہیں اپنی قیمتی چیزوں کا گھر دکھایا، چاندی، سونا، مصالحے، قیمتی مرہم اور اس کے زرہ کے تمام گھر، اور جو کچھ اس کے خزانے میں ملا: اس کے گھر اور اس کی سلطنت میں کچھ ایسا نہیں تھا جو حزقیاہ نے انہیں نہ دکھایا۔ قیمتی چیزیں:  یا، مصالحہ} {زرہ: یا، جواہرات: عبرانی۔ برتن، یا، آلات}\n3۔ پھر یسعیاہ نبی بادشاہ حزقیاہ کے پاس آیا اور اس سے کہا، ان لوگوں نے کیا کہا؟ اور وہ کہاں سے تمہارے پاس آئے؟ اور حزقیاہ نے کہا، وہ میرے پاس دور دراز ملک سے آئے ہیں، {حتیٰ کہ} بابل سے۔\n4۔ پھر اس نے کہا، انہوں نے تمہارے گھر میں کیا دیکھا ہے؟ اور حزقیاہ نے جواب دیا، جو کچھ بھی میرے گھر میں ہے وہ سب کچھ دیکھ چکا ہے: میرے خزانے میں سے کچھ ایسا نہیں جو میں نے نہ دکھایا ہو۔\n5۔ پھر یسعیاہ نے حزقیاہ سے کہا، خداوند لشکروں کا کلام سنو:\n6۔ دیکھو، دن آتے ہیں کہ جو کچھ بھی تمہارے گھر میں ہے، اور جو کچھ تمہارے آباؤ اجداد نے آج تک محفوظ رکھا ہے، وہ بابل لے جائے گا: کچھ باقی نہیں رہے گا، خداوند فرماتا ہے۔\n7۔ اور تمہارے بیٹوں میں سے جو تم سے پیدا ہوں گے، جنہیں تم پیدا کرو گے، وہ لے جائیں گے؛ اور وہ بابل کے بادشاہ کے محل میں خواجہ سرا ہوں گے۔\n8۔ پھر حزقیاہ نے یسعیاہ سے کہا، نیکی وہ کلام ہے جو تو نے کہا ہے۔ اس نے مزید کہا، کیونکہ میرے دنوں میں امن اور سچائی ہوگی۔","1. میرے لوگوں کو تسلی دو، تمہارا خدا فرماتا ہے۔\n2۔ یروشلم سے آرام سے بات کرو، اور اس سے پاؤ کہ اس کی جنگ مکمل ہو گئی ہے، اس کی گناہ معاف ہو گئی ہے: کیونکہ اسے خداوند کے ہاتھ سے اس کے تمام گناہوں کے بدلے دوگنا ملا ہے۔ {آرام سے: ہیب۔ دل سے} {جنگ: یا، مقررہ وقت}\n3۔ اس کی آواز جو بیابان میں پکار رہا ہے، خداوند کا راستہ تیار کرو، صحرا میں ہمارے خدا کے لیے راستہ بناؤ۔\n4۔ ہر وادی بلند کی جائے گی، اور ہر پہاڑ اور پہاڑی کو نیچا کیا جائے گا: اور ٹیڑھی سیدھی کی جائے گی، اور کھردری جگہیں سیدھے ہوں گی: {سیدھی: یا، سیدھی جگہ} {میدان: یا، ایک میدان جگہ}\n5۔ اور خداوند کی جلال ظاہر ہوگی، اور تمام جسم مل کر دیکھیں گے: کیونکہ خداوند کے منہ نے کہا ہے۔\n6۔ آواز نے کہا، رو لو۔ اور اس نے کہا، میں کیا روؤں؟ تمام گوشت گھاس ہے، اور اس کی تمام خوبیاں کھیت کے پھول کی طرح ہیں:\n7۔ گھاس مرجھا جاتی ہے، پھول مرجھا جاتا ہے: کیونکہ خداوند کی روح اس پر پھونک مارتی ہے: یقینا لوگ گھاس ہیں۔\n8۔ گھاس مرجھا جاتی ہے، پھول مرجھا جاتا ہے: لیکن ہمارے خدا کا کلام ہمیشہ قائم رہے گا۔\n9۔ اے صییون، جو خوشخبری لاتا ہے، بلند پہاڑ کی طرف چڑھو؛ اے یروشلم، جو خوشخبری لاتی ہے، اپنی آواز کو طاقت سے بلند کرو؛ اسے اٹھاؤ، ڈرو مت؛ یہوداہ کے شہروں سے کہو، اپنے خدا کو دیکھو! {اے صیون...: یا، اے وہ جو صیون کو خوشخبری سناتا ہے} {اے یروشلم...: یا، اے یروشلم کو خوشخبری سنانے والے}\n10۔ دیکھو، خداوند خدا مضبوط {ہاتھ} کے ساتھ آئے گا، اور اس کا بازو اس کے لیے حکمرانی کرے گا: دیکھو، اس کا اجر {ہے} اس کے ساتھ، اور اس کا کام اس کے سامنے ہے۔ {مضبوط...: یا، طاقتور کے خلاف} {اس کا کام: یا، اس کے کام کا معاوضہ}\n11۔ وہ اپنے ریوڑ کو چرواہے کی طرح کھلائے گا: وہ اپنے بازو سے بھیڑوں کو جمع کرے گا، اور انہیں اپنے سینے میں اٹھائے گا، {اور} بچوں کی نرمی سے رہنمائی کرے گا۔ {وہ...: یا، وہ برا ہے}\n12۔ جس نے اپنے ہاتھ کے گڑھے میں پانی کو ناپا، آسمان کو اسپین سے ترتیب دیا، زمین کی خاک کو پیمانہ پر سمجھا، پہاڑوں کو ترازو میں اور پہاڑوں کو توازن میں تول دیا؟ {ایک پیمانہ: عبرانی۔ a tierce}\n13. کس نے خداوند کی روح کو ہدایت دی ہے، یا اس کے مشیر نے اسے سکھایا ہے؟ {اس کا...: عبرانی اس کے مشیر کا آدمی}\n14۔ کس سے اس نے مشورہ لیا، اور کس نے اسے سکھایا، فیصلے کا راستہ سکھایا، علم سکھایا، اور اسے سمجھ کا راستہ دکھایا؟ {ہدایت دی گئی...: عبرانی۔ اسے سمجھایا} {سمجھنا: عبرانی۔ سمجھ بوجھ؟}\n15. دیکھو، قومیں {ہیں} بالٹی کے قطرے کی طرح، اور توازن کی چھوٹی سی خاک کے طور پر شمار ہوتی ہیں: دیکھو، وہ جزائر کو ایک بہت چھوٹی چیز کی طرح قبول کرتا ہے۔\n16۔ اور لبنان نہ تو جلنے کے لیے کافی ہے، نہ ہی اس کے جانور جلانے کے لیے کافی ہیں۔\n17۔ اس سے پہلے تمام قومیں {کچھ نہیں}؛ اور وہ اس کے لیے کچھ بھی نہیں اور خود پسندی سے کم شمار کیے جاتے ہیں۔\n18۔ تو پھر آپ خدا کو کس سے تشبیہ دیں گے؟ یا تم اس سے کس طرح موازنہ کرو گے؟\n19۔ کاریگر ایک کندہ شدہ تصویر پگھلاتا ہے، اور سنار اسے سونے سے بکھیرتا ہے، اور چاندی کی زنجیریں ڈالتا ہے۔\n20. جو {اتنا} غریب ہے کہ اس کے پاس کوئی قربانی نہیں، وہ ایسا درخت چنتا ہے {جو} سڑتا نہیں؛ وہ اس سے ایک چالاک مزدور چاہتا ہے کہ وہ ایک کندہ شدہ مجسمہ تیار کرے، {جو} ہلائے نہ جائے۔ {یہ تو...: عبرانی ہے۔ نذر میں کمزور ہے}\n21۔ کیا آپ کو معلوم نہیں؟ کیا تم نے نہیں سنا؟ کیا شروع سے تمہیں نہیں بتایا گیا؟ کیا تم نے زمین کی بنیادوں سے نہیں سمجھا؟\n22. {یہ} وہ ہے جو زمین کے دائرے پر بیٹھا ہے، اور اس کے باشندے {ٹڈوں کی طرح ہیں}؛ جو آسمانوں کو پردے کی طرح پھیلاتا ہے، اور انہیں خیمے کی طرح پھیلاتا ہے جس میں وہ بسنے کے لیے ہے: {یہ...: یا، وہی ہے جو}\n23۔ جو شہزادوں کو کچھ نہیں لے آتا؛ وہ زمین کے قاضیوں کو فضول بناتا ہے۔\n24۔ ہاں، انہیں نہیں لگایا جائے گا؛ ہاں، وہ بوئے نہیں جائیں گے: ہاں، ان کی نسل زمین میں جڑ نہیں پکڑے گی؛ اور وہ بھی ان پر پھونکے گا، اور وہ مرجھا جائیں گے، اور طوفان انہیں داڑھی کی طرح لے جائے گا۔\n25۔ تو پھر تم مجھے کس سے تشبیہ دو گے، یا کیا میں برابر ہوں گا؟ مقدس فرماتا ہے۔\n26۔ اپنی آنکھیں بلند کرو، اور دیکھو کہ کس نے یہ {چیزیں} پیدا کیں، جو ان کے لشکر کو تعداد کے حساب سے نکالتا ہے: وہ اپنی طاقت کی عظمت سے سب کو ناموں سے پکارتا ہے، کیونکہ {وہ} طاقت میں مضبوط ہے؛ کوئی بھی ناکام نہیں ہوتا۔\n27. اے یعقوب، تو کیوں کہتی ہو اور بولتی ہو، اے اسرائیل، میرا راستہ خداوند سے چھپا ہوا ہے، اور میرا فیصلہ میرے خدا سے منسوخ ہو گیا ہے؟\n28۔ کیا تم نہیں جانتے؟ کیا تم نے نہیں سنا کہ ابدی خدا، خداوند، زمین کے کناروں کا خالق، نہ بے ہوش ہوتا ہے، نہ تھکتا ہے؟ {اس کی سمجھ بوجھ کی کوئی تلاش نہیں ہوتی}۔\n29۔ وہ کمزوروں کو طاقت دیتا ہے؛ اور جن کے پاس طاقت نہیں، ان کے لیے وہ طاقت بڑھاتا ہے۔\n30۔ یہاں تک کہ نوجوان بھی بے ہوش ہو کر تھک جائیں گے، اور نوجوان مکمل طور پر گر جائیں گے:\n31۔ لیکن جو لوگ خداوند کا انتظار کرتے ہیں وہ اپنی طاقت کو دوبارہ زندہ کریں گے؛ وہ پروں کے ساتھ عقاب کی طرح سوار ہوں گے؛ وہ دوڑیں گے، اور تھکیں گے نہیں؛ {اور} وہ چلیں گے، اور بے ہوش نہیں ہوں گے۔ {تجدید: عبوری۔ تبدیلی}","1. اے جزیروں، میرے سامنے خاموش رہو؛ اور لوگوں کو اپنی طاقت دوبارہ حاصل کرنے دو: انہیں قریب آنے دو؛ تو انہیں بولنے دو: آؤ ہم ایک ساتھ فیصلے کے قریب آئیں۔\n2. کس نے مشرق سے نیک انسان کو اٹھایا، اسے اپنے قدموں پر بلایا، اپنے سے پہلے کی قوموں کو دیا، اور بادشاہوں پر حکمرانی کی؟ اس نے {ان} کو اپنی تلوار کی گرد کی طرح دیا، {اور} اپنی کمان پر دبا ہوا داڑھی کی طرح۔ {راستباز...: عبرانی۔ راستبازی}\n3۔ اس نے ان کا پیچھا کیا، {اور} بحفاظت گزر گیا؛ {حتیٰ کہ} ویسے {کہ} وہ اپنے پیروں کے ساتھ نہیں گیا۔ {محفوظ طریقے سے: ہیب۔ امن میں}\n4۔ کس نے یہ کیا اور کیا ہے، شروع سے نسلوں کو بلاتا ہے؟ میں خداوند ہوں، پہلا، اور آخری کے ساتھ؛ میں وہی ہوں۔\n5۔ جزائر نے اسے دیکھا اور ڈرا؛ زمین کے کنارے خوفزدہ تھے، قریب آئے، اور آ گئے۔\n6۔ انہوں نے اپنے پڑوسی کی ہر ایک کی مدد کی؛ اور {ہر ایک} نے اپنے بھائی سے کہا، حوصلہ رکھو۔ {ہو...: عبرانی۔ مضبوط رہو}\n7۔ تو بڑھئی نے سنار کو حوصلہ دیا، {اور} جس نے ہتھوڑے سے سیدھا کیا، اس کو جو سندان پر مارا تھا، کہا، یہ {تیار ہے} اور اسے کیلوں سے باندھ دیا، {تاکہ} اسے حرکت نہ دی جائے۔ {گولڈ اسمتھ: اور، بانی} {وہ...: یا، مارنا} {کہا...: یا، سوڈر کے بارے میں کہا، یہ اچھا ہے}\n8. لیکن تو، اسرائیل، میرے بندے ہو، یعقوب جسے میں نے چنا ہے، ابراہیم کی نسل میرا دوست۔\n9۔ {تم} جسے میں نے زمین کے کونے سے لیا ہے، اور تمہیں اس کے سرداروں میں سے بلایا ہے، اور تم سے کہا، 'تو میرا خادم ہے}؛ میں نے تمہیں چنا ہے، اور تمہیں نہیں چھوڑا۔\n10۔ ڈر مت؛ کیونکہ میں تمہارے ساتھ ہوں: مایوس نہ ہو؛ کیونکہ میں تمہارا خدا ہوں: میں تمہیں مضبوط کروں گا؛ ہاں، میں تمہاری مدد کروں گا؛ ہاں، میں اپنی راستبازی کے دائیں ہاتھ سے تمہیں سہارا دوں گا۔\n11۔ دیکھو، جو بھی تمہارے خلاف ناراض تھے وہ شرمندہ اور پریشان ہوں گے: وہ کچھ بھی نہیں ہوں گے؛ اور جو تمہارے ساتھ لڑیں گے وہ تباہ ہو جائیں گے۔ {جو کوشش کرتے ہیں...: عبرانی۔ تیری جدوجہد کے لوگ}\n12۔ تم انہیں تلاش کرو گے، اور انہیں نہیں پاؤ گے، {حتی} کہ وہ بھی جو تم سے لڑتے تھے: جو تمہارے خلاف جنگ کریں گے وہ کچھ نہیں ہوں گے، اور بے معنی چیز ہوں گے۔ {وہ کہ...: عبرانی۔ تمہارے تنازعے کے لوگ} {وہ...: عبرانی۔ تیری جنگ کے مرد}\n13. کیونکہ میں، خداوند تیرا خدا، تمہارا دایاں ہاتھ پکڑوں گا، اور تم سے کہوں گا، خوف نہ کرو؛ میں تمہاری مدد کروں گا۔\n14. ڈر مت، اے کیڑے یعقوب، {اور} اے اسرائیل کے لوگو؛ میں تمہاری مدد کروں گا، خداوند فرماتا ہے، اور تمہارا نجات دہندہ، اسرائیل کا پاک۔ {مرد: یا، چند مرد}\n15۔ دیکھو، میں تمہارے لیے ایک نیا تیز تھریشنگ آلہ بناؤں گا جس کے دانت ہوں گے: تم پہاڑوں کو کوٹے مارو گے، اور پہاڑوں کو بھوسے کی طرح مارو گے۔ {دانت: عبرانی۔ ماؤتھس}\n16۔ تم انہیں ہوا میں اڑاؤ گے، اور ہوا انہیں لے جائے گی، اور طوفان انہیں بکھیر دے گا: اور تم خداوند میں خوش رہو گے، {اور} اسرائیل کے مقدس وجود میں جلال پکڑو گے۔\n17۔ {جب} غریب اور محتاج پانی تلاش کرتے ہیں، اور {کوئی نہیں}، {اور} ان کی زبان پیاس سے بند ہو جائے، تو میں خداوند انہیں سنوں گا، میں اسرائیل کا خدا انہیں نہیں چھوڑوں گا۔\n18۔ میں اونچی جگہوں پر دریا اور وادیوں کے بیچ چشمے کھولوں گا: میں بیابان کو پانی کا تالاب اور خشک زمین کو پانی کے چشمے بنا دوں گا۔\n19۔ میں جنگل میں دیودار، شیتا کا درخت، مرٹل اور تیل کا درخت لگاؤں گا؛ میں صحرا میں فر کا درخت، صنوبر اور باکس ٹری کو ایک ساتھ لگاؤں گا:\n20۔ تاکہ وہ دیکھ سکیں، جان سکیں، غور کریں، اور مل کر سمجھیں، کہ خداوند کے ہاتھ نے یہ کیا ہے، اور اسرائیل کے مقدس ہستی نے اسے پیدا کیا ہے۔\n21۔ اپنا مقصد پیش کرو، خداوند فرماتا ہے؛ اپنے مضبوط {وجوہات} سامنے لاؤ، یعقوب کے بادشاہ نے کہا۔ {پروڈیوس: عبرانی۔ قریب آنے کی وجہ ہے}\n22۔ وہ سامنے لائیں اور ہمیں دکھائیں کہ کیا ہوگا: وہ پہلی چیزیں دکھائیں، جو وہ {ہیں}، تاکہ ہم ان پر غور کریں، اور ان کے بعد کے انجام کو جان سکیں؛ یا ہمیں آنے والے کاموں کا اعلان نہیں کرتا۔ {غور کریں...: عبرانی۔ اپنا دل ان پر رکھیں}\n23۔ آنے والی چیزیں دکھاؤ، تاکہ ہم جان سکیں کہ تم خدا ہو: ہاں، نیکی کرو یا برائی کرو، تاکہ ہم مایوس ہو جائیں اور مل کر اسے دیکھیں۔\n24۔ دیکھو، تم کچھ نہیں ہو، اور تمہارا کام بے کار ہے: ایک مکروہ {کیا وہ ہے} جو تمہیں چنتا ہے۔ {کچھ نہیں: یا، کچھ نہ ہونے سے بھی برا} {کچھ نہیں: یا، سانپ سے بھی بدتر}\n25۔ میں نے شمال سے {ایک} اٹھایا ہے، اور وہ آئے گا: سورج کے طلوع آفتاب سے وہ میرا نام پکارے گا: اور وہ شہزادوں پر آئے گا جیسے {مورٹر پر}، اور مٹی پر چلنے والا مٹی کے ساتھ۔\n26۔ کس نے ابتدا سے اعلان کیا ہے تاکہ ہم جان سکیں؟ اور وقت سے پہلے، تاکہ ہم کہیں، {وہ} راستباز ہے؟ ہاں، کوئی نہیں جو ظاہر کرے، ہاں، کوئی نہیں جو اعلان کرے، ہاں، کوئی نہیں جو تمہاری باتیں سنے۔\n27۔ پہلا {کہے} صیون کو، دیکھو انہیں: اور میں یروشلم کو وہ دوں گا جو خوشخبری لاتا ہے۔\n28۔ کیونکہ میں نے دیکھا، اور کوئی انسان نہیں تھا؛ یہاں تک کہ ان میں بھی، اور {وہاں کوئی مشیر نہیں تھا}، جو جب میں ان سے پوچھتا تو ایک لفظ بھی جواب دے سکتا۔ {جواب: عبرانی۔ واپسی}\n29۔ دیکھو، وہ سب خود غرض ہیں؛ ان کے کام کچھ بھی نہیں: ان کی پگھلی ہوئی تصویریں ہوا اور الجھن ہیں۔","1. دیکھو میرے بندے کو، جسے میں سنبھالتا ہوں؛ میرا منتخب، {جس سے} میری روح خوش ہوتی ہے؛ میں نے اپنی روح اس پر رکھی ہے: وہ غیر قوموں کے لیے فیصلہ کرے گا۔\n2۔ وہ نہ روئے، نہ اٹھے گا، نہ اپنی آواز کو سڑک پر سنائے گا۔\n3۔ زخمی سرکنڈے کو وہ نہیں توڑے گا، اور دھواں دار فلیس کو وہ نہیں بجھائے گا: وہ سچائی پر فیصلہ کرے گا۔ {سگریٹ نوشی: یا، مدھم جلنا} {quench: عبوری۔ اسے بجھاؤ}\n4۔ وہ مایوس یا مایوس نہیں ہوگا، جب تک کہ وہ زمین پر فیصلہ نہ کر لے: اور جزائر اس کے قانون کا انتظار کریں گے۔ {مایوس ہو کر: عبرانی۔ ٹوٹا ہوا}\n5. یہی فرماتا ہے خدا، جس نے آسمانوں کو بنایا اور انہیں پھیلایا؛ جو زمین کو پھیلاتا ہے، اور جو اس سے نکلتا ہے؛ جو اس پر موجود لوگوں کو سانس دیتا ہے، اور ان کو روح دیتا ہے جو اس میں چلتے ہیں:\n6۔ میں، خداوند، نے تمہیں راستبازی میں بلایا ہے، اور تمہارا ہاتھ تھاموں گا، تمہیں سنبھالوں گا، اور تمہیں قوم کے عہد کے طور پر، غیر قوموں کی روشنی کے طور پر دوں گا؛\n7۔ اندھی آنکھیں کھولنا، قیدیوں کو قید خانے سے نکالنا، {اور} اندھیرے میں بیٹھے لوگوں کو قید خانے سے باہر نکالنا۔\n8. میں {ہوں} خداوند ہوں: یہی {ہے} میرا نام: اور میں اپنی جلال کسی اور کو نہیں دوں گا، نہ ہی اپنی تعریف کندہ شدہ تصاویر کو۔\n9۔ دیکھو، پرانی چیزیں ہو چکی ہیں، اور میں نئی چیزوں کا اعلان کرتا ہوں: ان کے پھوٹنے سے پہلے میں تمہیں ان کے بارے میں بتاتا ہوں۔\n10. خداوند کو نیا گیت گاؤ، {اور} زمین کے کونے سے اس کی حمد کرو، اے جو سمندر تک اور اس میں سب کچھ ہے؛ جزائر اور ان کے باشندے۔ {سب...: عبرانی۔ اس کی مکمل شدت}\n11۔ بیابان اور اس کے شہر اپنی آواز بلند کریں، وہ گاؤں جو کیدار رہتے ہیں: چٹان کے باشندے گائیں، پہاڑوں کی چوٹی سے چیخیں۔\n12۔ خداوند کی شان دیں، اور جزائر میں اس کی تعریف کریں۔\n13۔ خداوند ایک طاقتور آدمی کی طرح باہر نکلے گا، وہ جنگ کے آدمی کی طرح حسد کو بھڑکائے گا: وہ پکارے گا، ہاں، دہاڑے گا؛ وہ اپنے دشمنوں پر غالب آئے گا۔ {غالب آنا: یا، خود کو قابو میں رکھنا}\n14. میں نے طویل عرصے سے اپنی سکون برقرار رکھی ہے؛ میں خاموش تھا، {اور} خود کو روک لیا: {اب} میں ایک اذیت زدہ عورت کی طرح روؤں گا؛ میں فورا تباہ اور نگل جاؤں گا۔ {نگلیں: عبرانی۔ نگلو، یا، بس کرو}\n15۔ میں ویراڈ پہاڑ اور پہاڑیاں بناؤں گا، اور ان کی تمام جڑی بوٹیاں خشک کر دوں گا؛ اور میں دریاؤں کو جزیرے بنا دوں گا، اور تالابوں کو خشک کر دوں گا۔\n16۔ اور میں اندھوں کو ایک ایسے راستے سے لاؤں گا جو وہ نہیں جانتے تھے؛ میں انہیں ان راستوں پر لے جاؤں گا جو انہوں نے نہیں جانے: میں اندھیرا ان کے سامنے روشن کروں گا، اور ٹیڑھی چیزوں کو سیدھا کروں گا۔ یہ سب میں ان کے ساتھ کروں گا، اور انہیں ترک نہیں کروں گا۔ {سیدھا: عبرانی۔ سیدھا پن کی طرف}\n17۔ انہیں واپس لوٹا دیا جائے گا، وہ بہت شرمندہ ہوں گے، جو کندہ شدہ تصاویر پر بھروسہ کرتے ہیں، جو پگھلے ہوئے مجسموں کو کہتے ہیں، تم ہمارے خدا ہو۔\n18۔ سنو، اے بہرو؛ اور دیکھو، اے اندھوں، تاکہ تم دیکھ سکو۔\n19. کون نابینا ہے، سوائے میرا نوکر؟ یا بہرا، جیسا کہ میرا پیغام رساں بھیجا تھا؟ کون {جو ہے} نابینا ہے جیسا {جو ہے} کامل، اور اندھا ہے جیسا کہ خداوند کا بندہ؟\n20۔ بہت سی چیزیں دیکھتے ہیں، لیکن آپ نہیں دیکھتے؛ کان کھولتا ہے، لیکن وہ سنتا نہیں۔\n21۔ خداوند اپنی راستبازی کے لیے خوش ہے؛ وہ قانون کو بڑھائے گا، اور اسے عزت دار بنائے گا۔ {یہ: یا، وہ}\n22۔ لیکن یہ ایک قوم ہے جسے لوٹا اور بگاڑا گیا ہے؛ {وہ} سب سوراخوں میں پھنسے ہوئے ہیں، اور قید خانوں میں چھپے ہوئے ہیں: وہ شکار کے لیے ہیں، اور کوئی نجات نہیں دیتا؛ ایک غنیمت کے لیے، اور کوئی نہیں کہتا، بحالی۔ {وہ سب...: یا، ان کے تمام نوجوانوں کو پھنسانے میں} {ایک انعام کے لیے: عبوری۔ ایک قدم چلانا}\n23۔ تم میں سے کون اس بات کو سنے گا؟ {کون} آنے والے وقت کے لیے سنے گا اور سنے گا؟ {for...: عبرانی۔ بعد کے وقت کے لیے؟}\n24۔ کس نے یعقوب کو غنیمت کے بدلے دیا، اور اسرائیل کو ڈاکوؤں کو؟ کیا خداوند نے، جس کے خلاف ہم نے گناہ کیا ہے؟ کیونکہ وہ اس کے راستے پر نہیں چلیں گے، نہ ہی اس کے قانون کے تابع تھے۔\n25۔ اسی لیے اس نے اپنے غصے اور جنگ کی طاقت اس پر ڈال دی: اور اس نے اسے ارد گرد آگ لگا دی، حالانکہ وہ نہیں جانتا تھا؛ اور اس نے اسے جلا دیا، پھر بھی اس نے اسے دل میں نہیں رکھا۔","1۔ لیکن اب خداوند نے یہی فرمایا ہے جس نے تمہیں پیدا کیا، اے یعقوب، اور جس نے تمہیں بنایا، اے اسرائیل، خوف نہ کرو: کیونکہ میں نے تمہیں نجات دی ہے، میں نے {تم} کو تیرے نام سے بلایا ہے؛ تم میرے ہو۔\n2۔ جب تم پانیوں سے گزرو گے، میں تمہارے ساتھ ہوں گا؛ اور دریاؤں کے پار، وہ تمہیں نہیں بہائیں گے: جب تم آگ میں چلو گے، تو تم نہیں جلو گے؛ نہ ہی تم پر شعلہ جلائے گا۔\n3۔ کیونکہ میں خداوند ہوں، تیرا خدا، اسرائیل کا مقدس، تیرا نجات دہندہ: میں نے مصر کو تمہاری فدیہ کے بدلے دیا، ایتھوپیا اور سبا تمہارے لیے۔\n4۔ چونکہ تم میری نظر میں قیمتی تھے، تم معزز رہے ہو، اور میں نے تم سے محبت کی ہے: اس لیے میں تمہارے لیے انسان دوں گا، اور تمہاری زندگی کے لیے لوگوں کو دوں گا۔ {زندگی: یا، شخص}\n5۔ خوف نہ کرو: کیونکہ میں تمہارے ساتھ ہوں: میں تمہاری نسل مشرق سے لاؤں گا، اور تمہیں مغرب سے جمع کروں گا؛\n6۔ میں شمال سے کہوں گا، ہار مان لو؛ اور جنوب کی طرف، پیچھے نہ رہو: میرے بیٹوں کو دور سے لے آؤ، اور میری بیٹیوں کو زمین کے کونے سے لانا؛\n7۔ {حتیٰ کہ} ہر وہ شخص جسے میرے نام سے پکارا جاتا ہے: کیونکہ میں نے اسے اپنی شان کے لیے پیدا کیا ہے، میں نے اسے بنایا ہے؛ ہاں، میں نے اسے بنایا ہے۔\n8۔ آنکھوں والے اندھے لوگوں کو اور کان رکھنے والے بہرے لوگوں کو باہر لاؤ۔\n9۔ تمام قومیں اکٹھی ہوں، اور لوگ اکٹھے ہوں: ان میں سے کون اس کا اعلان کر سکتا ہے، اور ہمیں پرانی باتیں دکھا سکتا ہے؟ انہیں اپنے گواہ پیش کرنے دیں تاکہ وہ درست ثابت ہوں: یا انہیں سننے دیں اور کہیں، {یہ سچ ہے}۔\n10۔ خداوند فرماتا ہے، آپ میرے گواہ ہیں، اور میرا بندہ جسے میں نے چنا ہے: تاکہ آپ مجھے جان سکیں اور یقین کریں، اور سمجھیں کہ میں وہی ہوں: میرے سامنے کوئی خدا نہیں تھا، نہ ہی میرے بعد کوئی خدا ہوگا۔ {نہیں...: یا، خدا کی کوئی شکل نہیں}\n11. میں، {حتی} میں، {ہوں} خداوند ہوں؛ اور میرے ساتھ کوئی نجات دہندہ نہیں۔\n12. میں نے اعلان کیا ہے، نجات دی ہے، اور دکھا دیا ہے، جب تم میں کوئی اجنبی خدا نہیں تھا: اس لیے تم میرے گواہ ہو، خداوند فرماتا ہے، کہ میں خدا ہوں۔\n13۔ ہاں، اس دن سے پہلے {تھا} میں {ہوں} وہ؛ اور {کوئی نہیں} جو میرے ہاتھ سے نجات دے سکے: میں کام کروں گا، اور کون اسے اجازت دے گا؟ {لیٹ اٹ: عبرانی۔ واپس کر دوں؟}\n14. یہ فرماتا ہے، خداوند تمہارا نجات دہندہ، اسرائیل کا پاک؛ تمہارے لیے میں نے بابل بھیجا ہے، اور ان کے تمام اشرافیہ اور کلدانی لوگوں کو گرا دیا ہے، جن کی آواز جہازوں میں ہے۔ {نوبلز: عبرانی۔ بارز}\n15. میں خداوند ہوں، تمہارا مقدس، اسرائیل کا خالق، تمہارا بادشاہ۔\n16۔ خداوند یہی فرماتا ہے، جو سمندر میں راستہ بناتا ہے، اور عظیم پانیوں میں راستہ بناتا ہے؛\n17۔ جو رتھ اور گھوڑا، فوج اور طاقت لاتی ہے؛ وہ ایک ساتھ لیٹیں گے، اٹھیں گے نہیں: وہ معدوم ہو چکے ہیں، وہ ٹو کی طرح بجھ چکے ہیں۔\n18۔ پرانی باتوں کو یاد نہ رکھو، نہ ہی پرانی باتوں پر غور کرو۔\n19۔ دیکھو، میں ایک نیا کام کروں گا؛ اب یہ پھوٹے گا؛ کیا تم اسے نہیں جانتے؟ میں جنگل میں بھی راستہ بنا لوں گا، {اور} صحرا میں دریا بھی۔\n20۔ میدان کا درندہ مجھے، اژدہوں اور الوؤں کی عزت کرے گا: کیونکہ میں صحرا میں پانی دیتا ہوں، اور صحرا میں دریا بھی، تاکہ اپنے لوگوں کو پانی دے سکوں، جو میرے منتخب ہیں۔ {الو: یا، شتر مرغ: عبوری۔ بیٹیاں آف دی آول}\n21۔ یہ لوگ میں نے اپنے لیے بنائے ہیں؛ وہ میری تعریف کریں گے۔\n22. لیکن تم نے مجھے نہیں بلایا، اے یعقوب؛ لیکن تم مجھ سے تھک چکے ہو، اے اسرائیل۔\n23۔ تم نے مجھے اپنے جلانے والے نذرانے کے چھوٹے مویشی نہیں دیے؛ نہ ہی تم نے اپنی قربانیوں سے مجھے عزت دی۔ میں نے تمہیں نذرانہ دینے پر مجبور نہیں کیا، نہ ہی تمہیں لوبان سے تھکایا۔ {چھوٹا...: عبوری۔ بھیڑیں، یا، بچے}\n24۔ تم نے مجھے پیسے سے کوئی میٹھی چھڑی نہیں خریدی، نہ ہی اپنی قربانیوں کی چربی سے مجھے بھر دیا، بلکہ تم نے مجھے اپنے گناہوں سے خدمت کرنے پر مجبور کیا، تم نے مجھے اپنی گناہوں سے تھکا دیا۔ {بھرا ہوا...: عبوری۔ مجھے نشے میں ڈال دیا، یا بہت زیادہ نم کر دیا}\n25. میں، {حتی} میں وہ ہوں جو تمہاری گناہوں کو اپنی خاطر مٹاتا ہے، اور تمہارے گناہوں کو یاد نہیں رکھتا۔\n26۔ مجھے یاد میں رکھو: آؤ مل کر دعا کریں: تو اعلان کرو تاکہ تم راستباز ہو۔\n27. تمہارے پہلے باپ نے گناہ کیا ہے، اور تمہارے اساتذہ نے میرے خلاف گناہ کیا ہے۔ {اساتذہ: عبدی۔ مترجمین}\n28۔ اسی لیے میں نے مقدس مقام کے شہزادوں کی بے حرمتی کی ہے، اور یعقوب کو لعنت کے حوالے کر دیا ہے، اور اسرائیل کو ملامت کے لیے دیا ہے۔ {شہزادے...: یا، مقدس شہزادے}","1۔ اب سنو، اے یعقوب میرے بندے؛ اور اسرائیل، جسے میں نے چنا ہے:\n2. یہی فرماتا ہے خداوند جس نے تمہیں بنایا اور تمہیں رحم سے بنایا، {جو} تمہاری مدد کرے گا؛ ڈر مت، اے جیکب، میرے خادم؛ اور تم، جیسورن، جسے میں نے چنا ہے۔\n3۔ کیونکہ میں اس پر پانی ڈالوں گا جو پیاسا ہے اور خشک زمین پر سیلاب بہاتا ہے: میں اپنی روح تیرے نسل پر ڈالوں گا، اور اپنی برکت تیرے اولاد پر ڈالوں گا:\n4۔ اور وہ گھاس میں پھوٹیں گے، جیسے پانی کے کنارے بید کے درخت۔\n5۔ کوئی کہے گا، میں خداوند کا ہوں؛ اور دوسرا خود کو یعقوب کے نام سے پکارے گا؛ اور دوسرا اپنے ہاتھ کے ساتھ خداوند کے نام سے سبسکرائب کرے گا، اور اپنا خاندانی نام {خود} اسرائیل کے نام سے رکھے گا۔\n6۔ یہی فرماتا ہے، خداوند اسرائیل کا بادشاہ، اور اس کا نجات دہندہ، رب لشکر؛ میں پہلا ہوں، اور میں آخری ہوں؛ اور میرے ساتھ کوئی خدا نہیں۔\n7۔ اور کون، جیسا کہ میں بلاؤں گا، اسے اعلان کرے گا، اور میرے لیے ترتیب دے گا، چونکہ میں نے قدیم لوگوں کو مقرر کیا ہے؟ اور جو چیزیں آ رہی ہیں اور آئیں گی، وہ انہیں دکھائیں۔\n8۔ نہ ڈرو، نہ ڈرو: کیا میں نے تمہیں اس وقت سے نہیں بتایا اور اعلان نہیں کیا؟ تم میرے گواہ بھی ہو۔ کیا میرے ساتھ کوئی خدا ہے؟ ہاں، {کوئی خدا نہیں}؛ مجھے معلوم نہیں، {کوئی بھی}۔ {خدا؛ I: عبرانی۔ راک، وغیرہ}\n9۔ جو لوگ کندہ شدہ تصویر بناتے ہیں وہ سب خود غرض ہیں؛ اور ان کی لذیذ چیزوں سے کوئی فائدہ نہیں ہوگا؛ اور وہ خود اپنے گواہ ہیں؛ وہ نہ دیکھتے ہیں، نہ جانتے ہیں؛ تاکہ وہ شرمندہ ہوں۔ {لذیذ: عبرانی۔ پسندیدہ}\n10۔ کس نے خدا بنایا ہے، یا ایک کندہ شدہ تصویر کو پگھلا کر {جو} بے فائدہ ہے؟\n11۔ دیکھو، اس کے تمام ساتھی شرمندہ ہوں گے: اور مزدور انسانوں میں سے ہیں: سب اکٹھے ہو جائیں، کھڑے ہو جائیں؛ {پھر بھی} وہ ڈریں گے، {اور} وہ مل کر شرمندہ ہوں گے۔\n12۔ چمٹے والا لوہار کوئلوں میں کام کرتا ہے، اسے ہتھوڑوں سے بناتا ہے، اور اپنے بازوؤں کی طاقت سے کام کرتا ہے: ہاں، وہ بھوکا ہے، اور اس کی طاقت کمزور ہو جاتی ہے: وہ پانی نہیں پیتا، اور بے ہوش ہے۔ {چمٹے کے ساتھ: یا، کلہاڑی سے}\n13۔ بڑھئی اپنے اصول کو پھیلاتا ہے؛ اس نے اسے ایک لائن کے ذریعے مارکیٹ کیا؛ وہ اسے طیاروں سے جوڑتا ہے، اور کمپاس سے اسے مارکیٹ کرتا ہے، اور اسے انسان کی خوبصورتی کے مطابق انسان کی شکل کے مطابق بناتا ہے؛ تاکہ وہ گھر میں ہی رہ سکے۔\n14۔ وہ اسے دیودار کے درخت کاٹتا ہے، اور جنگل کے درختوں میں سائپریس اور بلوط کو اپنے لیے مضبوط کرتا ہے: وہ راکھ بوتا ہے، اور بارش اسے خوراک دیتی ہے۔ {مضبوط: یا، حوصلہ لیتا ہے}\n15۔ پھر انسان کے لیے جلنا ہوگا: کیونکہ وہ اسے لے گا اور خود کو گرم کرے گا؛ ہاں، وہ اسے جلا دیتا ہے، اور روٹی بناتا ہے؛ ہاں، وہ خدا بناتا ہے، اور اس کی عبادت کرتا ہے؛ وہ اسے کندہ شدہ تصویر بناتا ہے، اور اس پر گر جاتا ہے۔\n16۔ وہ اس کا کچھ حصہ آگ میں جلا دیتا ہے؛ اس کا کچھ حصہ گوشت کھاتا ہے؛ وہ روسٹ کرتا ہے، اور مطمئن ہوتا ہے: ہاں، وہ خود کو گرم کرتا ہے، اور کہتا ہے، آہا، میں گرم ہوں، میں نے آگ دیکھی ہے:\n17۔ اور اس کے باقیات کو وہ خدا بناتا ہے، حتیٰ کہ اپنی کندہ شدہ تصویر بھی: وہ اس پر گر پڑتا ہے، اس کی عبادت کرتا ہے، اس سے دعا کرتا ہے، اور کہتا ہے، مجھے نجات دے؛ کیونکہ تو میرے خدا ہو۔\n18۔ وہ نہ جانتے ہیں اور نہ ہی سمجھ سکے: کیونکہ اس نے ان کی آنکھیں بند کر دی ہیں تاکہ وہ دیکھ نہ سکیں؛ {اور} ان کے دلوں کو، جنہیں وہ سمجھ نہیں سکتے۔ {بند: عبوری۔ daubed}\n19۔ اور کوئی اپنے دل میں یہ نہیں سوچتا، نہ کوئی علم ہے اور نہ ہی سمجھ کہ میں نے اس کا کچھ حصہ آگ میں جلا دیا ہے؛ ہاں، میں نے اس کے کوئلوں پر روٹی بھی پکی ہے؛ میں نے گوشت بھنا ہے، اور کھا لیا ہے: اور کیا میں اس کے باقیات کو مکروہ بنا دوں؟ کیا میں درخت کے ذرے پر گر جاؤں؟ {غور کریں...: عبرانی۔ اس کے دل سے جڑے} {دی اسٹاک...: عبرانی جو درخت سے نکلتا ہے؟}\n20۔ وہ راکھ پر پلتا ہے: ایک دھوکہ کھا ہوا دل اسے پیچھے دھکیل چکا ہے، کہ وہ اپنی جان نہیں بچا سکتا، اور نہ ہی کہہ سکتا ہے، {کیا} میرے دائیں ہاتھ میں کوئی جھوٹ نہیں؟\n21. اے یعقوب اور اسرائیل، ان کو یاد رکھو؛ کیونکہ تم میرے خادم ہو: میں نے تمہیں بنایا ہے؛ تو میرے خادم ہو: اے اسرائیل، تم مجھے کبھی نہیں بھولنا۔\n22. میں نے تمہاری گناہوں کو ایک گھنے بادل کی طرح اور تمہارے گناہوں کو بادل کی طرح چھپا دیا ہے: میرے پاس واپس آؤ؛ کیونکہ میں نے تمہیں نجات دی ہے۔\n23. اے آسمانوں کو گاؤ؛ کیونکہ خداوند نے یہ کیا ہے: اے زمین کے نچلے حصے چیخیں، اے پہاڑوں، اے جنگل اور اس کے ہر درخت، گانے میں پھٹ پڑو، کیونکہ خداوند نے یعقوب کو نجات دی اور اسرائیل میں جلال بخشا۔\n24. خداوند یہی فرماتا ہے، تیرے نجات دہندہ، اور جس نے تمہیں رحم سے پیدا کیا، میں وہ خداوند ہوں جو سب چیزیں بناتا ہے؛ جو صرف آسمانوں تک پھیلا ہوا ہے؛ جو خود زمین کو پھیلاتا ہے؛\n25۔ جو جھوٹوں کے نشانات کو ناکام بناتا ہے، اور غیب گوؤں کو پاگل کر دیتا ہے؛ جو عقلمندوں کو پیچھے لے جاتا ہے، اور ان کے علم کو بے وقوف بناتا ہے؛\n26۔ جو اس کے خادم کے کلام کی تصدیق کرے، اور اس کے رسولوں کی نصیحت پر عمل کرے؛ جو یروشلم سے کہتا ہے، تو آباد ہو گا؛ اور یہوداہ کے شہروں میں تم تعمیر کیے جاؤ گے، اور میں ان کے سڑے ہوئے مقامات کو دوبارہ زندہ کروں گا: {سڑا...: عبرانی۔ ویسٹس}\n27۔ جو گہرائی سے کہتا ہے، خشک ہو جاؤ، اور میں تمہارے دریا خشک کر دوں گا:\n28۔ جو سائرس کے بارے میں کہتا ہے، {وہ} میرا چرواہا ہے، اور میری تمام خوشیوں کو پورا کرے گا: یہاں تک کہ یروشلم سے کہتا ہے، تو تعمیر ہو گا؛ اور مندر میں تمہاری بنیاد رکھی جائے گی۔","1۔ خداوند اپنے مسح شدہ، سائرس سے، جس کا دایاں ہاتھ میں تھامے ہوئے ہوں، سے فرماتا ہے کہ قوموں کو اس کے سامنے تابع کرے؛ اور میں بادشاہوں کی کمر کھولوں گا، اس کے سامنے دو پتوں والے دروازے کھولوں گا؛ اور دروازے بند نہیں ہوں گے؛ {ہے...: یا، مضبوط کیا گیا ہے}\n2۔ میں تمہارے سامنے جاؤں گا، اور ٹیڑھی جگہوں کو سیدھا کروں گا: میں پیتل کے دروازے ٹکڑوں میں توڑوں گا، اور لوہے کی سلاخوں کے نیچے کاٹ دوں گا:\n3۔ اور میں تمہیں تاریکی کے خزانے اور خفیہ جگہوں کی چھپی ہوئی دولت دوں گا، تاکہ تم جان سکو کہ میں، خداوند، جو تمہیں تمہارے نام سے پکارتا ہوں، اسرائیل کا خدا ہوں۔\n4۔ میرے خادم یعقوب کے لیے، اور میرے منتخب اسرائیل کے لیے، میں نے تمہیں تمہارے نام سے پکارا ہے: میں نے تمہیں نام دیا ہے، حالانکہ تم نے مجھے نہیں جانا۔\n5. میں خداوند ہوں، اور کوئی اور نہیں، میرے سوا کوئی خدا نہیں: میں نے تمہیں باندھا، حالانکہ تم نے مجھے نہیں جانا:\n6۔ تاکہ وہ سورج کے طلوع آفتاب اور مغرب سے جان سکیں کہ میرے سوا کوئی نہیں۔ میں {ہوں}خداوند ہوں، اور {کوئی اور} نہیں۔\n7. میں روشنی بناتا ہوں، اور تاریکی پیدا کرتا ہوں: میں صلح کرتا ہوں، اور برائی پیدا کرتا ہوں: میں خداوند یہ سب کچھ کرتا ہوں۔\n8۔ اے آسمانوں، اوپر سے نیچے آؤ، اور آسمانوں کو راستبازی برساؤ: زمین کو کھول دو، اور وہ نجات دے، اور راستبازی کو ایک ساتھ پھوٹنے دو؛ میں، خداوند، نے اسے پیدا کیا ہے۔\n9۔ اس پر افسوس جو اپنے خالق کے ساتھ جدوجہد کرتا ہے! {آؤ} مٹی کے ٹکڑے {کوشش کریں} زمین کے مٹی کے ٹکڑوں کے ساتھ۔ کیا مٹی اس سے کہے گی جو اسے بناتا ہے، تم کیا بناتے ہو؟ یا تمہارا کام، اس کے ہاتھ نہیں ہیں؟\n10۔ اس پر افسوس جو اپنے باپ سے کہتا ہے، تم نے کیا پیدا کیا؟ یا عورت سے، تم نے کیا پیدا کیا ہے؟\n11. خداوند اسرائیل کے مقدس اور اس کے خالق کے لیے یہی فرماتا ہے، میرے بیٹوں کے بارے میں آنے والے معاملات سے مجھ سے پوچھو، اور میرے ہاتھوں کے کام کے بارے میں حکم دو۔\n12. میں نے زمین بنائی ہے، اور انسان کو اس پر پیدا کیا ہے: میں نے اپنے ہاتھوں سے آسمان کو پھیلایا ہے، اور ان کے تمام لشکر کو میں نے حکم دیا ہے۔\n13. میں نے اسے راستبازی میں اٹھایا ہے، اور میں اس کے تمام راستے دکھاؤں گا: وہ میرا شہر تعمیر کرے گا، اور میرے قیدیوں کو آزاد کرے گا، نہ قیمت کے بدلے اور نہ اجر کے لیے، لشکروں کے رب فرماتا ہے۔ {براہ راست: یا، سیدھا کرو}\n14۔ خداوند یہ فرماتا ہے، مصر کی محنت، ایتھوپیا کی تجارت، اور سبین کی تجارت، جو باوقار لوگ ہیں، تمہارے پاس آئیں گے، اور وہ تمہارے ہوں گے: وہ تمہارے پیچھے آئیں گے؛ وہ زنجیروں میں آ کر آئیں گے، اور آپ کے پاس گریں گے، وہ آپ سے دعا کریں گے، {کہیں}، یقینا خدا آپ میں ہے؛ اور {کوئی اور نہیں}، {کوئی خدا نہیں}۔\n15. یقینا تو وہ خدا ہو جو اپنے آپ کو چھپاتا ہے، اے اسرائیل کے خدا، نجات دہندہ۔\n16. وہ سب شرمندہ ہوں گے، اور ساتھ ہی الجھن کا شکار ہوں گے: وہ سب مل کر الجھن میں جائیں گے {جو بت بنانے والے} ہیں۔\n17. {لیکن} اسرائیل خداوند میں ہمیشہ کی نجات کے ساتھ نجات پائے گا: تم شرمندہ نہیں ہو گے اور نہ ہی دنیا کو ہمیشہ کے لیے پریشان کرو گے۔\n18۔ کیونکہ ایسا فرماتا ہے خداوند جس نے آسمانوں کو پیدا کیا؛ خدا نے خود زمین کو بنایا اور اسے بنایا؛ اس نے اسے قائم کیا، اس نے اسے بے سود نہیں بنایا، بلکہ اسے آباد کرنے کے لیے بنایا ہے: میں {ہوں} خداوند ہوں؛ اور {اور کوئی نہیں}۔\n19۔ میں نے زمین کے تاریک حصے میں خفیہ طور پر بات نہیں کی: میں نے یعقوب کی نسل سے یہ نہیں کہا، مجھے بے فائدہ تلاش کرو: میں خداوند راستبازی کی بات کرتا ہوں، میں صحیح باتوں کا اعلان کرتا ہوں۔\n20۔ جمع ہو جاؤ اور آؤ؛ قریب آ جاؤ، تم جو قوموں سے فرار ہو گئے: انہیں معلوم نہیں کہ ان کی تراشی ہوئی تصویر کی لکڑی کیسے بنائی گئی ہے، اور وہ اس خدا سے دعا کرتے ہیں جو بچا نہیں سکتا۔\n21. بتاؤ، اور {ان} کو قریب لاؤ؛ ہاں، انہیں مل کر مشورہ کرنے دو: قدیم زمانے سے یہ اعلان کس نے کیا ہے؟ {کس نے} نے اس وقت سے اسے سنایا؟ کیا میں خداوند نہیں ہوں؟ اور {میرے سوا} کوئی اور خدا نہیں؛ ایک عادل خدا اور نجات دہندہ؛ {میرے سوا} کوئی نہیں ہے۔\n22۔ میری طرف دیکھو، اور زمین کے تمام کناروں پر نجات پانا: کیونکہ میں خدا ہوں، اور کوئی اور نہیں۔\n23۔ میں نے خود سے قسم کھائی ہے کہ میرے منہ سے نیکی کا لفظ نکل چکا ہے، اور واپس نہیں آئے گا، کہ ہر گھٹنا میرے سامنے جھکے گا، ہر زبان قسم کھائے گی۔\n24. یقینا، {ایک} کہے گا، خداوند میں میرے پاس راستبازی اور طاقت ہے: {حتی} لوگ {لوگ} اس کے پاس آئیں گے؛ اور جو بھی اس کے خلاف غصہ کرے گا وہ شرمندہ ہوگا۔ {یقینا...: یا، یقینا وہ میرے بارے میں کہے گا، خداوند میں تمام راستبازی اور طاقت ہے} {راستبازی: عبرانی۔ راستبازی}\n25. خداوند میں اسرائیل کی تمام نسل کو راستباز بنایا جائے گا اور جلال پایا جائے گا۔","1۔ بیل جھک جاؤ، نیبو جھک گیا، ان کے بت جانوروں اور مویشیوں پر تھے: تمہاری گاڑیاں بھاری بوجھ تھیں؛ {وہ تھکے ہوئے {درنده} کے لیے بوجھ ہیں۔\n2۔ وہ جھکتے ہیں، ایک ساتھ جھکتے ہیں؛ وہ بوجھ نہیں اٹھا سکے، لیکن خود قید میں چلے جاتے ہیں۔ {خود: ہیب۔ ان کی روح}\n3. اے یعقوب کے گھرے، اور اسرائیل کے خاندان کی تمام باقیات کو سنو، جو {میرے ذریعے} پیٹ سے پیدا ہوتے ہیں، جو رحم سے اٹھے جاتے ہیں:\n4۔ اور {حتی} آپ کی بڑھاپے تک {میں} وہ ہوں؛ اور {حتیٰ کہ} میں بالوں کو کھودنے تک لے جاؤں گا {تم}: میں نے بنایا ہے، اور میں برداشت کروں گا؛ یہاں تک کہ میں بھی تمہیں اٹھاؤں گا، اور تمہیں دے دوں گا۔\n5. تم مجھے کس سے تشبیہ دو گے، اور مجھے برابر کرو گے، اور موازنہ کرو گے تاکہ ہم ایک جیسے ہوں؟\n6۔ وہ تھیلے سے سونا نکالتے ہیں، چاندی کا وزن کرتے ہیں، {اور} ایک سنار کو ملازمت دیتے ہیں؛ اور وہ اسے خدا بناتا ہے: وہ گرتے ہیں، ہاں، وہ عبادت کرتے ہیں۔\n7۔ وہ اسے کندھے پر اٹھاتے ہیں، اسے اٹھاتے ہیں، اور اس کی جگہ بٹھاتے ہیں، اور وہ کھڑا ہوتا ہے؛ وہ اپنی جگہ سے نہیں ہٹے گا: ہاں، {ایک} اس سے پکار رہا ہوگا، لیکن وہ جواب نہیں دے سکتا، نہ اسے اس کی مصیبت سے بچا سکتا ہے۔\n8۔ یہ یاد رکھو، اور اپنے آپ کو دکھاؤ، اے گندی حضرات۔\n9۔ پرانی باتوں کو یاد رکھو: کیونکہ میں خدا ہوں، اور کوئی اور نہیں؛ {میں ہوں} خدا، اور میرے جیسا کوئی نہیں،\n10۔ ابتدا سے انجام کا اعلان کرنا، اور قدیم زمانے سے {وہ چیزیں} جو ابھی تک نہیں ہوئیں، کہتے ہوئے، میری نصیحت قائم رہے گی، اور میں اپنی ساری خوشی کروں گا:\n11۔ مشرق سے ایک بھوکے پرندے کو بلانا، وہ آدمی جو دور دراز ملک سے میری نصیحت پر عمل کرتا ہے: ہاں، میں نے کہا ہے، میں اسے حقیقت میں بھی لاؤں گا؛ میں نے ارادہ کر لیا ہے، میں یہ بھی کروں گا۔ {وہ...: عببرانی۔ میرے مشورے سے}\n12۔ اے دلیر لوگو، میری بات سنو، جو نیکی سے بہت دور ہیں:\n13۔ میں اپنی راستبازی کو قریب لاتا ہوں؛ یہ دور نہیں ہوگا، اور میری نجات دیر نہیں کرے گی: اور میں نجات کو صیہون میں رکھوں گا، اسرائیل کے لیے میری جلال۔","1۔ نیچے آؤ، اور مٹی میں بیٹھ جاؤ، اے بابل کی کنواری بیٹی، زمین پر بیٹھ جاؤ: {کوئی تخت نہیں}، اے کلدانیوں کی بیٹی: کیونکہ اب تمہیں نرم اور نازک نہیں کہا جائے گا۔\n2۔ چکی کے پتھر لے کر آٹا پیسو: اپنے بال کھولو، ٹانگ ننگا کرو، ران کھولو، دریاؤں کے پار سے گزرو۔\n3. تیری برہنگی بے نقاب ہو جائے گی، ہاں، تمہاری شرمندگی نظر آئے گی: میں انتقام لوں گا، اور میں تم سے مرد بن کر نہیں ملوں گا۔\n4. {جہاں تک} ہمارے نجات دہندہ، لشکروں کا رب {ہے} اس کا نام، اسرائیل کا پاک۔\n5. خاموش بیٹھو، اور اندھیرے میں چلی جاؤ، اے کلدانیوں کی بیٹی، کیونکہ اب تمہیں بادشاہتوں کی خاتون نہیں کہا جائے گا۔\n6۔ میں اپنے لوگوں سے غصے میں تھا، میں نے اپنی میراث کو آلودہ کیا اور انہیں تیرے ہاتھ میں دے دیا: تو نے ان پر رحم نہیں کیا؛ قدیم چیزوں پر تم نے اپنا جوا بہت بھاری ڈال دیا ہے۔\n7۔ اور تم نے کہا، میں ہمیشہ کے لیے ایک خاتون رہوں گی: {تاکہ} تم نے یہ [چیزیں} اپنے دل پر نہ رکھیں، اور نہ ہی اس کے آخری انجام کو یاد رکھی۔\n8۔ تو اب یہ سنو، {تو} جو خوشیوں کے لیے وقف ہے، جو لاپرواہی سے رہتا ہے، جو اپنے دل میں کہتا ہے، میں {ہوں}، اور میرے سوا کوئی نہیں؛ میں بیوہ کی طرح نہیں بیٹھوں گی، نہ ہی بچوں کے نقصان کو جانوں گی:\n9۔ لیکن یہ دونوں {چیزیں} آپ کے پاس ایک لمحے میں ایک دن میں آئیں گی، بچوں کا نقصان اور بیوہ ہونا: یہ آپ پر اپنی کمال کے ساتھ آپ پر آئیں گی کیونکہ آپ کی جادوئی کثرت {اور} آپ کی جادوئی کثرت کی وجہ سے۔\n10۔ کیونکہ تم نے اپنی برائی پر بھروسہ کیا ہے: تم نے کہا، کوئی مجھے نہیں دیکھتا۔ تمہاری حکمت اور علم نے تمہیں گمراہ کیا ہے؛ اور تم نے اپنے دل میں کہا ہے، میں ہوں، اور میرے علاوہ کوئی اور نہیں۔ {بگاڑی...: یا، تمہیں منہ موڑنے پر مجبور کیا}\n11۔ اس لیے برائی تم پر آئے گی؛ تمہیں معلوم نہیں ہوگا کہ یہ کہاں سے نکلتا ہے: اور تم پر مصیبت آئے گی؛ تم اسے ٹال نہیں سکو گے: اور اچانک تم پر تباہی آ جائے گی، {جو} تم نہیں جانو گے۔ {سے...: عبرانی اس کی صبح} {put: Hebrew. کفارہ}\n12۔ اب اپنے جادوؤں کے ساتھ کھڑے ہو جاؤ، اور اپنی بے شمار جادوگریوں کے ساتھ، جن میں تم نے اپنی جوانی سے محنت کی ہے؛ اگر ایسا ہوا تو تم فائدہ اٹھاؤ گے، اگر ایسا ہو تو تم کامیاب ہو جاؤ گے۔\n13۔ تم اپنی نصیحتوں کی کثرت سے تھک چکے ہو۔ اب نجومیوں، ستاروں کو دیکھنے والے، ماہانہ پیش گو کرنے والے کھڑے ہو جائیں، اور تمہیں ان {چیزوں} سے بچائیں جو تم پر آئیں گی۔ {نجومی: عبرانی۔ آسمانوں کے ناظرین} {دی منتھلی...: عبرانی جو مہینوں کے بارے میں علم فراہم کرتا ہے}\n14۔ دیکھو، وہ داڑھی کی طرح ہوں گے؛ آگ انہیں جلا دے گی؛ وہ خود کو آگ کی طاقت سے نجات نہیں دیں گے: نہ کوئی کوئلہ ہوگا جس پر گرم کیا جائے، نہ ہی آگ اس کے سامنے بیٹھے۔ {خود: ہیب۔ ان کی روحیں}\n15۔ اسی طرح وہ تمہارے ساتھ ہوں گے جن کے ساتھ تم نے محنت کی، {حتیٰ کہ} تمہارے تاجروں کے ساتھ، تمہاری جوانی سے: وہ ہر ایک کو اس کے علاقے کی طرف بھٹکیں گے؛ کوئی تمہیں بچا نہیں سکتا۔","1۔ اے یعقوب کے گھرانے کو سنو، جو اسرائیل کے نام سے پکارے گئے ہیں، اور یہوداہ کے پانیوں سے نکلے ہیں، جو خداوند کے نام پر قسم کھاتے ہیں، اور اسرائیل کے خدا کا ذکر کرتے ہیں، {لیکن} سچائی میں نہیں، نہ راستبازی میں۔\n2۔ کیونکہ وہ خود کو مقدس شہر کہتے ہیں، اور اسرائیل کے خدا پر قائم ہیں؛ لشکروں کا رب اس کا نام ہے۔\n3۔ میں نے پہلے والے معاملات کو شروع سے ہی بیان کیا ہے؛ اور وہ میرے منہ سے نکلے، اور میں نے انہیں دکھایا؛ میں نے اچانک ان کے ساتھ کام کیا، اور وہ حقیقت بن گئے۔\n4۔ کیونکہ میں جانتا تھا کہ تم ضدی ہو، اور تمہاری گردن لوہے کی رگ ہے، اور تمہاری پیشانی پیتل کی ہے؛ {ضدی: عبرانی۔ مشکل}\n5۔ میں نے شروع سے ہی یہ آپ کے سامنے اعلان کیا ہے؛ اس سے پہلے کہ وہ ہوتا، میں نے تمہیں دکھایا: کہیں تم کہیں کہ میرا بت انہیں کر چکا ہے، اور میری تراشی ہوئی تصویر اور میری پگھلی ہوئی تصویر نے انہیں حکم دیا ہے۔\n6۔ تم نے سنا ہے، یہ سب دیکھو؛ اور کیا تم اس کا اعلان نہیں کرو گے؟ میں نے تمہیں اس وقت سے نئی چیزیں دکھائی ہیں، یہاں تک کہ چھپی ہوئی چیزیں بھی، اور تم انہیں نہیں جانتے تھے۔\n7۔ وہ اب پیدا کیے گئے ہیں، اور ابتدا سے نہیں؛ یہاں تک کہ اس دن سے پہلے جب تم انہیں نہ سنو؛ کہیں تم یہ نہ کہو، دیکھو، میں انہیں جانتا تھا۔\n8۔ ہاں، تم نے نہیں سنا؛ ہاں، تم نہیں جانتے تھے؛ ہاں، اس وقت سے {کہ} تمہارا کان نہیں کھلا: کیونکہ میں جانتا تھا کہ تم بہت دھوکہ دہی کرو گے، اور مجھے رحم سے ہی نافرمان کہا گیا۔\n9۔ اپنے نام کے لیے میں اپنا غصہ مؤخر کروں گا، اور اپنی تعریف کے لیے میں تمہارے لیے خود کو روک لوں گا کہ میں تمہیں کاٹوں گا نہیں۔\n10۔ دیکھو، میں نے تمہیں نکھارا ہے، لیکن چاندی سے نہیں؛ میں نے تمہیں مصیبت کی بھٹی میں چنا ہے۔ {ساتھ...: یا، چاندی کے لیے}\n11. اپنے فائدے کے لیے، {حتیٰ کہ} اپنے لیے بھی، کیا میں یہ کروں گا: کیونکہ {میرا نام} کیسے آلودہ ہونا چاہیے؟ اور میں اپنی شان کسی اور کو نہیں دوں گا۔\n12. اے یعقوب اور اسرائیل، میرے پکارے ہوئے میری بات سنو؛ میں {ہوں} وہ؛ میں پہلا ہوں، میں بھی آخری ہوں۔\n13۔ میرا ہاتھ بھی زمین کی بنیاد رکھ چکا ہے، اور میرا دایاں ہاتھ آسمانوں تک پھیلا ہوا ہے: {جب} میں انہیں پکارتا ہوں، وہ اکٹھے کھڑے ہو جاتے ہیں۔ {میرا...: یا، میرے دائیں ہاتھ کی ہتھیلی پھیل گئی ہے}\n14۔ سب لوگ، جمع ہو جاؤ اور سنو؛ ان میں سے کس نے یہ {چیزیں} کا اعلان کیا ہے؟ خداوند نے اسے محبت کی ہے: وہ اپنی مرضی بابل پر کرے گا، اور اس کا بازو کلدانیوں پر ہوگا۔\n15. میں، {حتی} میں نے بات کی ہے؛ ہاں، میں نے اسے بلایا ہے: میں اسے لایا ہوں، اور وہ خوشحال ہوگا۔\n16۔ میرے قریب آؤ، یہ سنو؛ میں نے شروع سے خفیہ بات نہیں کی؛ جب سے یہ تھا، میں {ہوں}: اور اب خداوند خدا اور اس کی روح نے مجھے بھیجا ہے۔\n17. خداوند یہی فرماتا ہے، تیرے نجات دہندہ، اسرائیل کا پاک؛ میں خداوند ہوں، تیرا خدا جو تمہیں فائدہ سکھاتا ہے، جو تمہیں اس راستے کی طرف لے جاتا ہے جہاں تمہیں جانا چاہیے۔\n18. کاش تم نے میرے احکامات پر عمل کیا ہوتا! تب تمہاری امن دریا کی طرح ہوتی، اور تیری راستبازی سمندر کی لہروں کی طرح:\n19۔ تمہارا بیج بھی ریت کی طرح تھا، اور تمہارے آنتوں کی اولاد اس کے کنکر کی طرح تھی؛ اس کا نام مجھ سے پہلے کاٹنا یا تباہ نہیں ہونا چاہیے تھا۔\n20۔ بابل سے نکل جاؤ، کلدانیوں سے بھاگ جاؤ، گانے کی آواز کے ساتھ کہو، یہ کہو، اسے زمین کے آخر تک کہو؛ کہو، خداوند نے اپنے بندے یعقوب کو نجات دی ہے۔\n21۔ اور وہ پیاس نہیں لگے {جب} جب اس نے انہیں صحرا سے گزارا: اس نے ان کے لیے چٹان سے پانی بہایا: اس نے چٹان کو بھی توڑا، اور پانی بہنے لگا۔\n22. {کوئی امن نہیں}، خداوند فرماتا ہے، بدکاروں سے۔","1. اے جزیروں، میری بات سنو؛ اور اے لوگو، دور سے سنو؛ خداوند نے مجھے رحم سے بلایا ہے؛ اس نے میری ماں کی آنتوں سے میرا نام لیا ہے۔\n2۔ اور اس نے میرے منہ کو تیز تلوار کی طرح بنا دیا ہے؛ اس نے اپنے ہاتھ کے سائے میں مجھے چھپا لیا ہے، اور مجھے چمکدار عضو بنا دیا ہے؛ اس نے مجھے اپنی ترکش میں چھپا لیا ہے؛\n3۔ اور مجھ سے کہا، اے اسرائیل، تو میرا بندہ ہو، جس میں میں جلال پاتا ہوں۔\n4۔ پھر میں نے کہا، میں نے بے فائدہ محنت کی، اپنی طاقت ضائع کی ہے، اور بے سود: {لیکن} یقینا میرا فیصلہ {ہے} خداوند کے ساتھ، اور میرا کام میرے خدا کے ساتھ۔ {میرا کام: یا، میرا انعام}\n5۔ اور اب، خداوند نے فرمایا، جس نے مجھے رحم سے پیدا کیا {تاکہ اس کا بندہ بن سکوں، تاکہ یعقوب کو دوبارہ اس کے پاس لے آؤں، اگرچہ اسرائیل جمع نہ ہوں، پھر بھی میں خداوند کی نظر میں جلال بخشوں گا، اور میرا خدا میری طاقت ہوگا۔ {اگرچہ...: یا، تاکہ اسرائیل اس کے پاس جمع ہو جائے، اور میں کر سکوں، وغیرہ}\n6۔ اور اس نے کہا، یہ ہلکی بات ہے کہ تم میرے خادم بنو تاکہ یعقوب کے قبائل کو زندہ کرو اور اسرائیل کی حفاظت کو بحال کرو: میں تمہیں غیر قوموں کے لیے روشنی کے طور پر بھی دوں گا، تاکہ تم زمین کے آخر تک میری نجات بنو۔ {یہ ہے...: یا، کیا تم اس سے ہلکے ہو جتنا تمہیں ہونا چاہیے، وغیرہ} {محفوظ: یا، ویرانیاں}\n7. یہی فرماتا ہے رب، اسرائیل کا نجات دہندہ، {اور} اس کا مقدس، جسے انسان حقیر کرتا ہے، جسے قوم نفرت کرتی ہے، حکمرانوں کے خادم سے، بادشاہ دیکھیں گے اور اٹھیں گے، شہزادے بھی عبادت کریں گے، خدا کے لیے جو وفادار ہے، {اور} اسرائیل کے پاک ہستی کی وجہ سے، اور وہ تمہیں چنے گا۔ {جسے انسان...: یا، جو روح میں حقیر سمجھا جاتا ہے}\n8۔ خداوند یہ فرماتا ہے، ایک مناسب وقت میں میں نے تمہیں سنا ہے، اور نجات کے دن میں میں نے تمہاری مدد کی ہے: اور میں تمہیں محفوظ رکھوں گا، اور تمہیں لوگوں کے عہد کے طور پر دوں گا، زمین قائم کرنے کے لیے، ویران میراثوں کو وارث بنانے کے لیے؛ {قائم: یا، اٹھو}\n9۔ تاکہ تم قیدیوں سے کہہ سکو، آگے بڑھو؛ جو لوگ اندھیرے میں ہیں، اپنے آپ کو دکھائیں۔ وہ راستوں میں خوراک حاصل کریں گے، اور ان کے چراگاہیں ہر اونچی جگہوں پر ہوں گی۔\n10۔ انہیں نہ بھوک لگے گی نہ پیاس ہوگی؛ نہ گرمی نہ دھوپ انہیں نقصان پہنچائے گی، کیونکہ جو ان پر رحم کرے گا وہ انہیں پانی کے چشموں کے ذریعے بھی رہنمائی کرے گا۔\n11۔ اور میں اپنے تمام پہاڑوں کو راستہ بنا دوں گا، اور میری شاہراہیں بلند ہوں گی۔\n12۔ دیکھو، یہ دور سے آ رہے ہیں: اور دیکھو، یہ شمال اور مغرب سے آ رہے ہیں؛ اور یہ سینم کی سرزمین سے ہیں۔\n13. گاؤ، اے آسمان؛ اور خوش رہو، اے زمین؛ اور اے پہاڑوں، گانے میں پھٹ پڑو، کیونکہ خداوند نے اپنے لوگوں کو تسلی دی ہے، اور اپنے مظلوموں پر رحم کرے گا۔\n14۔ لیکن صیون نے کہا، خداوند نے مجھے چھوڑ دیا ہے، اور میرے رب نے مجھے بھلا دیا ہے۔\n15. کیا عورت اپنے دودھ پیتے بچے کو بھول سکتی ہے، کہ اسے اپنے پیٹ کے بیٹے پر رحم نہیں کرنا چاہیے؟ ہاں، وہ بھول سکتے ہیں، لیکن میں تمہیں نہیں بھولوں گا۔ {وہ...: عببرانی۔ ہمدردی سے بچنے سے}\n16۔ دیکھو، میں نے تمہیں اپنے ہاتھوں کی ہتھیلیوں پر کندہ کیا ہے؛ تمہاری دیواریں ہمیشہ میرے سامنے ہیں۔\n17۔ تمہارے بچے جلدی کرو؛ تمہارے تباہ کرنے والے اور جنہوں نے تمہیں برباد کیا وہ تم سے نکل جائیں گے۔\n18۔ اپنی آنکھیں ادھر ادھر اٹھاؤ، اور دیکھو: یہ سب اکٹھے ہو جاتے ہیں، {اور} تیرے پاس آتے ہیں۔ {As} میں زندہ ہوں، خداوند فرماتا ہے، تو ضرور تمہیں ان سب سے ملبوس کرو، جیسے زیور کے ساتھ، اور انہیں اپنے اوپر باندھے، جیسے دلہن کرتی ہے۔\n19۔ کیونکہ تمہاری بربادی، تمہاری ویران جگہیں، اور تمہاری تباہی کی زمین، اب بھی یہاں کے باشندوں کی وجہ سے بہت تنگ ہو جائے گی، اور جو تمہیں نگل گئے ہیں وہ بہت دور ہوں گے۔\n20۔ وہ بچے جو تمہارے ہوں گے، جب تم دوسرے کو کھو دو گے، وہ تمہارے کانوں میں دوبارہ کہیں گے، جگہ میرے لیے بہت تنگ ہے: مجھے جگہ دو تاکہ میں رہ سکوں۔\n21۔ تو پھر تم اپنے دل میں کہو گے، یہ کس نے مجھے پیدا کیا، جب میں نے اپنے بچے کھو دیے ہیں، اور میں ویران ہوں، قیدی ہوں، اور ادھر ادھر آ جاتا ہوں؟ اور یہ سب کس نے اٹھایا؟ دیکھو، میں اکیلا رہ گیا تھا؛ یہ، کہاں {تھے} وہ {تھے}؟\n22۔ خداوند خدا یہ فرماتا ہے، دیکھو، میں غیر یہودیوں کے سامنے اپنا ہاتھ اٹھاؤں گا، اور لوگوں کے سامنے اپنا جھنڈا قائم کروں گا: اور وہ تیرے بیٹوں کو اپنے بازوؤں میں لائیں گے، اور تیری بیٹیاں ان کے کندھوں پر اٹھائے جائیں گی۔ {بازو: عبوری۔ چھاتی\n23۔ اور بادشاہ تمہارے دودھ پلانے والے باپ ہوں گے، اور ان کی ملکہ تمہاری دودھ پلانے والی مائیں ہوں گی: وہ تمہارے سامنے زمین کی طرف منہ کر کے سجدہ کریں گی، اور تمہارے قدموں کی خاک چاٹیں گی؛ اور تم جان لو گے کہ میں خداوند ہوں: کیونکہ وہ لوگ شرمندہ نہیں ہوں گے جو میرا انتظار کر رہے ہیں۔ {دودھ پلانے والے والد: عبرانی۔ غذائیت دینے والے} {ملکہ: عبرانی۔ شہزادیاں}\n24. کیا شکار طاقتور سے لیا جائے گا، یا قانونی قیدی کو آزاد کیا جائے گا؟ {قانونی...: عبرانی۔ عادلوں کی قید}\n25۔ لیکن خداوند یوں فرماتا ہے، طاقتور کے قیدی بھی لے لیے جائیں گے، اور خوفناک کا شکار آزاد ہو جائے گا: کیونکہ میں اس سے لڑوں گا جو تم سے لڑتا ہے، اور تمہارے بچوں کو بچاؤں گا۔ {قیدی: عبرانی۔ قید}\n26۔ اور میں ان لوگوں کو کھلاؤں گا جو تمہیں ظلم کرتے ہیں؛ اور وہ اپنے ہی خون سے مست ہوں گے، جیسے میٹھی شراب سے: اور ہر جسم کو معلوم ہوگا کہ میں خداوند تمہارا نجات دہندہ ہوں اور تیرا نجات دہندہ، یعقوب کا طاقتور ہوں۔ {میٹھا: یا، نیا}","1. خداوند فرماتا ہے، تمہاری ماں کی طلاق کا بل کہاں ہے، جسے میں نے رکھ دیا ہے؟ یا میرے کون سے قرض دہندہ {کیا ہے} جنہیں میں نے تمہیں بیچا ہے؟ دیکھو، تم نے اپنی غلطیوں کی وجہ سے خود کو بیچ دیا ہے، اور تمہاری غلطیوں کی وجہ سے تمہاری ماں کو قید کر دیا گیا ہے۔\n2. جب میں آیا تو وہاں کوئی مرد کیوں نہیں تھا؟ جب میں نے کال کی، کیا کوئی جواب دینے والا نہیں تھا؟ کیا میرا ہاتھ کسی حد تک چھوٹا ہو گیا ہے، جس کی وجہ سے یہ واپس نہیں آ سکتا؟ یا میرے پاس دینے کی طاقت نہیں؟ دیکھو، میری سرزنش پر میں سمندر کو خشک کر دیتا ہوں، میں دریاؤں کو ویران بنا دیتا ہوں: ان کی مچھلیاں بدبو دار ہیں، کیونکہ {یہاں پانی نہیں}، اور وہ پیاس سے مر جاتے ہیں۔\n3۔ میں آسمانوں کو سیاہی سے کپڑے پہناتا ہوں، اور تھیلے کے کپڑے کو ان کی چادر بناتا ہوں۔\n4۔ خداوند خدا نے مجھے عالموں کی زبان دی ہے تاکہ میں وقت کے مطابق لفظ کہہ سکوں جو تھکا ہوا ہے: وہ صبح صبح جاگتا ہے، وہ میرے کان کو جگاتا ہے تاکہ وہ سننے کے لیے جیسا کہ عالم ہے۔\n5۔ خداوند خدا نے میرا کان کھول دیا ہے، اور میں باغی نہیں تھا، نہ ہی پیچھے ہٹا۔\n6. میں نے اپنی پیٹھ سمائٹرز کو دی، اور اپنے گال ان کے سامنے جو بال توڑ رہے تھے: میں نے شرم اور تھوکنے سے اپنا چہرہ نہیں چھپایا۔\n7. کیونکہ خداوند خدا میری مدد کرے گا؛ لہٰذا میں شرمندہ نہیں ہوں گا: اس لیے میں نے اپنا چہرہ چقماق کی طرح بنایا ہے، اور میں جانتا ہوں کہ میں شرمندہ نہیں ہوں گا۔\n8۔ {وہ} قریب ہے جو مجھے جائز ٹھہراتا ہے؛ کون میرا مقابلہ کرے گا؟ آئیے ایک ساتھ کھڑے ہوں: میرا دشمن کون ہے؟ اسے میرے قریب آنے دو۔ {میرا...: عبرانی۔ میرے مقصد کا مالک؟}\n9۔ دیکھو، خداوند خدا میری مدد کرے گا؛ وہ کون ہے جو مجھے سزا دے گا؟ دیکھو، وہ سب ایک لباس کی طرح بوڑھے ہو جائیں گے؛ پتنگا انہیں کھا جائے گا۔\n10۔ آپ میں سے کون ہے جو خداوند سے ڈرتا ہے، جو اپنے بندے کی آواز کی اطاعت کرتا ہے، جو اندھیرے میں چلتا ہے، اور اس کے پاس روشنی نہیں؟ وہ خداوند کے نام پر بھروسہ کرے، اور اپنے خدا پر قائم رہے۔\n11. دیکھو، وہ سب جو آگ جلاتے ہو، جو چنگاریوں سے گھومتے ہیں: اپنی آگ کی روشنی میں چلو، اور ان چنگاریوں میں جو تم نے جلا دی ہیں۔ یہ میرے ہاتھ سے تمہیں ملے گا؛ تم غم میں لیٹ جاؤ گے۔","1. میری بات سنو، اے جو راستبازی کے پیچھے چلتے ہو، اور جو خداوند کی تلاش میں ہیں: اس چٹان کی طرف دیکھو {جہاں سے} تم تراشے گئے ہو، اور اس گڑھے کے گڑھے کی طرف جہاں سے تم کھودے گئے ہو۔\n2۔ ابراہیم کو اپنے باپ کی طرف دیکھو، اور سارہ کی طرف دیکھو جو تمہیں جنم دیتی ہے: کیونکہ میں نے اسے اکیلا بلایا، اسے برکت دی اور بڑھا دیا۔\n3۔ کیونکہ خداوند صیون کو تسلی دے گا: وہ اس کی تمام ویران جگہوں کو تسلی دے گا؛ اور وہ اس کے صحرا کو عدن کی طرح اور صحرا کو خداوند کے باغ کی طرح بنائے گا؛ اس میں خوشی اور خوشی ملے گی، شکرگزاری، اور دھن کی آواز۔\n4. میری بات سنو، میرے لوگو؛ اور میری بات سنو، اے میری قوم، کیونکہ مجھ سے ایک قانون نکلے گا، اور میں اپنی رائے کو عوام کی روشنی کے لیے قائم کروں گا۔\n5. میری راستبازی قریب ہے؛ میری نجات ختم ہو چکی ہے، اور میرے بازو لوگوں کا فیصلہ کریں گے؛ جزائر میرا انتظار کریں گے، اور میرے بازو پر بھروسہ کریں گے۔\n6۔ اپنی آنکھیں آسمان کی طرف اٹھاؤ، اور نیچے زمین کو دیکھو، کیونکہ آسمان دھوئیں کی طرح غائب ہو جائے گا، زمین ایک لباس کی طرح بوڑھی ہو جائے گی، اور جو وہاں رہیں گے وہ بھی اسی طرح مر جائیں گے: لیکن میری نجات ہمیشہ کے لیے ہوگی، اور میری راستبازی ختم نہیں ہوگی۔\n7. اے جو راستبازی جانتے ہیں، میری بات سنو، ان لوگوں کو جن کے دل میں میرا قانون ہے؛ انسانوں کی ملامت سے نہ ڈرو، نہ ہی ان کی گالیوں سے ڈرو۔\n8۔ کیونکہ پتنگا انہیں لباس کی طرح کھا جائے گا، اور کیڑا انہیں اون کی طرح کھائے گا: لیکن میری راستبازی ہمیشہ رہے گی، اور میری نجات نسل در نسل ہوگی۔\n9۔ جاگو، جاگو، طاقت حاصل کرو، اے خداوند کا بازو؛ جاگنا، جیسے قدیم زمانے میں، پرانے زمانے کی نسلوں میں۔ کیا تم وہ نہیں جس نے راحاب کو کاٹا، اور اژدہے کو زخمی کیا؟\n10۔ {کیا تو} وہ نہیں جس نے سمندر کو خشک کیا، عظیم گہرائی کے پانیوں کو؛ جس نے سمندر کی گہرائیوں کو فدیہ پانے والوں کے گزرنے کا راستہ بنا دیا ہے؟\n11۔ لہٰذا خداوند کے نجات پانے والے واپس آئیں گے، اور صیون کے لیے گانے کے ساتھ آئیں گے؛ اور ان کے سر پر ہمیشہ کی خوشی ہوگی: انہیں خوشی اور خوشی ملے گی؛ {اور} غم اور سوگ دور ہو جائیں گے۔\n12. میں، {حتی} میں، {میں} وہ ہوں جو تمہیں تسلی دیتا ہے: جو {تو} ہے، کہ تم اس آدمی سے ڈرو {جو} مر جائے گا، اور اس انسان کے بیٹے {جو} گھاس بن جائے گا؛\n13۔ اور اپنے خالق خداوند کو بھول جا، جس نے آسمانوں کو پھیلایا اور زمین کی بنیادیں رکھی ہیں؛ اور ظالم کے غصے کی وجہ سے روزانہ خوفزدہ رہا، جیسے وہ تباہ کرنے کو تیار ہو؟ اور ظالم کا غصہ کہاں ہے؟ {تھے...: یا، خود کو تیار کر لیا}\n14۔ قیدی جلاوطن جلدی کرتا ہے تاکہ اسے رہا کیا جائے، اور وہ گڑھے میں نہ مرے، نہ اس کی روٹی ختم ہو جائے۔\n15۔ لیکن میں خداوند ہوں تیرا خدا، جس نے سمندر کو تقسیم کیا، جس کی لہریں گرجتی تھیں: لشکروں کا رب اس کا نام ہے۔\n16۔ اور میں نے اپنے الفاظ تیرے منہ میں رکھے ہیں، اور تمہیں اپنے ہاتھ کے سائے میں ڈھانپ دیا ہے، تاکہ میں آسمان لگا سکوں، زمین کی بنیادیں رکھوں، اور صیون سے کہوں، تو میرے لوگ ہو۔\n17. جاگو، جاگو، اٹھو، اے یروشلم، جس نے خداوند کے ہاتھ سے اپنے غضب کا پیالہ پی لیا ہے؛ تم نے کانپتے ہوئے پیالے کے باقیات پی لیے، {اور} انہیں نچوڑ لیا۔\n18۔ {کوئی نہیں} جو اس کے تمام بیٹوں میں رہنمائی کرے {جنہوں نے} پیدا کیے؛ نہ ہی کوئی {کوئی} ہے جو اسے ان تمام بیٹوں کے ہاتھوں پکڑتی ہے جنہیں اس نے پالا ہے۔\n19۔ یہ دو {چیزیں} تمہارے پاس آئی ہیں؛ کون تمہارے لیے افسوس کرے گا؟ ویرانی، تباہی، قحط، اور تلوار: کس سے تمہیں تسلی دوں؟ {آر...: عبرانی ہوا} {تباہی: عبرانی۔ بریکنگ}\n20۔ تیرے بیٹے بے ہوش ہو گئے ہیں، وہ تمام گلیوں کے سرے پر لیٹے ہیں، جیسے جال میں جنگلی بیل: وہ خداوند کے غضب سے بھرے ہوئے ہیں، جو تیرے خدا کی ملامت ہے۔\n21. تو اب یہ سنو، اے مصیبت زدہ اور نشے میں، مگر شراب سے نہیں:\n22۔ یہ فرماتا ہے تیرے رب خداوند اور تمہارا خدا {جو اپنے لوگوں کی حمایت کرتا ہے}، دیکھو، میں نے تمہارے ہاتھ سے کانپتے ہوئے پیالہ نکال لیا، {حتیٰ کہ} اپنے غضب کے پیالے کا بچا بھی ہوا؛ تم اسے دوبارہ نہیں پیو گے:\n23۔ لیکن میں اسے ان کے ہاتھ میں دوں گا جو تمہیں تکلیف دیتے ہیں؛ جنہوں نے اپنی روح سے کہا ہے، جھک جاؤ، تاکہ ہم گزر سکیں: اور تم نے اپنا جسم زمین اور سڑک کے طور پر ان لوگوں کے لیے پیش کیا ہے جو گزرے۔","1. جاگو، جاگو؛ اے صیہون، اپنی طاقت پہن لو؛ اے یروشلم، مقدس شہر، اپنے خوبصورت لباس پہن لو، کیونکہ اب سے تمہارے اندر ختنہ شدہ اور ناپاک نہیں آئیں گے۔\n2. خود کو مٹی سے جھاڑو؛ اٹھو، {اور} بیٹھ جاؤ، اے یروشلم: اپنی گردن کی پٹیوں سے آزاد ہو جاؤ، اے صیون کی قیدی بیٹی۔\n3۔ کیونکہ خداوند فرماتا ہے، تم نے خود کو بے کار بیچ دیا؛ اور تم بغیر پیسے کے نجات پاؤ گے۔\n4۔ کیونکہ خداوند خدا یوں فرماتا ہے، میرے لوگ پہلے مصر میں گئے تھے تاکہ وہاں قیام کریں؛ اور آشوری نے انہیں بغیر وجہ کے ظلم کیا۔\n5. تو اب، خداوند فرماتا ہے، میرے پاس یہاں کیا ہے کہ میرے لوگ بے فائدہ لے جائے؟ جو ان پر حکمرانی کرتے ہیں وہ انہیں چیخنے پر مجبور کرتے ہیں، خداوند فرماتا ہے؛ اور میرا نام ہر روز مسلسل کفر کیا جاتا ہے۔\n6۔ اس لیے میرے لوگ میرا نام جانیں گے: اسی لیے {وہ جانیں گے} اس دن کہ میں وہ ہوں جو بولتا ہے: دیکھو، {یہ} میں ہوں۔\n7۔ پہاڑوں کے قدموں پر اس کے قدموں کتنے خوبصورت ہیں جو خوشخبری لاتا ہے، جو امن پھیلاتا ہے؛ جو نیکی کی خوشخبری لاتا ہے، جو نجات کو شائع کرتا ہے؛ جو صیون سے کہتا ہے، تیرا خدا حکمرانی کرتا ہے!\n8۔ تمہارے پہرے دار آواز بلند کریں گے؛ آواز کے ساتھ وہ مل کر گائیں گے: کیونکہ وہ آنکھوں میں آنکھیں ڈال کر دیکھیں گے، جب خداوند صیہون کو دوبارہ لائے گا۔\n9۔ خوشی میں پھوٹو، مل کر گاؤ، یروشلم کی جگہوں کو برباد کرو: کیونکہ خداوند نے اپنے لوگوں کو تسلی دی ہے، اس نے یروشلم کو نجات دی ہے۔\n10۔ خداوند نے تمام قوموں کی آنکھوں میں اپنا مقدس بازو بے نقاب کر دیا ہے؛ اور زمین کے تمام کونے ہمارے خدا کی نجات دیکھیں گے۔\n11۔ چلے جاؤ، چلے جاؤ، وہاں سے نکل جاؤ، ناپاک چیز کو نہ چھوؤ؛ تم اس کے بیچ سے نکل جاؤ؛ تم پاک رہو جو خداوند کے برتن اٹھائے ہوئے ہو۔\n12۔ کیونکہ تم جلد بازی میں باہر نہیں جاؤ گے، نہ بھاگ کر جائیں گے، کیونکہ خداوند تمہارے سامنے جائے گا؛ اور اسرائیل کا خدا تمہارا بدلہ ہوگا۔ {be...: عبرانی۔ تمہیں لے آؤں گا}\n13۔ دیکھو، میرا خادم دانشمندی سے پیش آئے گا، اسے بلند اور سراہا جائے گا، اور بہت بلند ہوگا۔ {معاہدہ...: یا، خوشحال}\n14۔ جیسا کہ بہت سے لوگ تم پر حیران تھے؛ اس کا چہرہ کسی بھی انسان سے زیادہ خراب تھا، اور اس کی شکل انسانوں کے بیٹوں سے بھی زیادہ:\n15۔ اسی طرح وہ کئی قوموں کو چھڑکائے گا؛ بادشاہ اس پر منہ بند کر لیں گے: کیونکہ وہ جو انہیں نہیں بتایا گیا تھا، وہ دیکھیں گے؛ اور {یہ} جو انہوں نے نہیں سنا تھا، وہ غور کریں گے۔","1. کس نے ہماری رپورٹ پر یقین کیا؟ اور خداوند کا بازو کس کے لیے ظاہر کیا گیا ہے؟ {رپورٹ: یا، عقیدہ؟: عببرانی۔ سننا؟}\n2۔ کیونکہ وہ اس کے سامنے ایک نرم پودے کی طرح اگتا ہے، اور خشک زمین کی جڑ کی طرح: اس کی کوئی شکل یا خوبصورتی نہیں؛ اور جب ہم اسے دیکھیں گے، {کوئی خوبصورتی نہیں} جس کی ہمیں خواہش کرنی چاہیے۔\n3۔ وہ مردوں سے حقیر اور مسترد کیا جاتا ہے؛ غموں کا آدمی، اور غم سے واقف: اور ہم نے اس سے اپنے چہرے چھپا لیے؛ اسے حقیر سمجھا جاتا تھا، اور ہم نے اس کی عزت نہیں کی۔ {ہم نے چھپایا...: یا، اس نے اپنا چہرہ ہم سے چھپایا: عبرانی۔ چہروں کو اس سے چھپانے کے لیے، یا ہم سے بھی}\n4۔ یقینا اس نے ہمارے غم برداشت کیے، اور ہمارے غم اٹھائے، پھر بھی ہم نے اسے خدا کے ہاتھوں متاثر اور مصیبت زدہ سمجھا۔\n5۔ لیکن وہ ہمارے گناہوں کی وجہ سے زخمی ہوا، ہمارے گناہوں کی وجہ سے زخمی ہوا: ہمارے امن کی سزا اس پر تھی؛ اور اس کی دھاریوں کے ساتھ ہم شفا پاتے ہیں۔ {زخمی: یا، اذیت زدہ} {دھاریاں: عببرانی۔ بروز}\n6۔ ہم سب بھیڑوں کی طرح گمراہ ہو گئے ہیں؛ ہم نے ہر ایک کو اس کے اپنے راستے پر موڑ دیا ہے؛ اور خداوند نے ہم سب کی بدکاری اس پر نازل کی ہے۔ {layed...: عبرانی اس نے ہم سب کو اس پر ملنے کی بدکاری کی تھی}\n7۔ اسے ظلم کیا گیا، اور وہ تکلیف میں مبتلا ہوا، پھر بھی اس نے اپنا منہ نہ کھولا: اسے ذبح کے لیے بکری کی طرح لایا گیا، اور جیسے بھیڑ کاٹنے والوں کے سامنے گونگا ہے، تو وہ اپنا منہ نہیں کھولتا۔\n8۔ اسے قید سے اور فیصلے سے نکالا گیا: اور اس کی نسل کا اعلان کون کرے گا؟ کیونکہ وہ زندہ لوگوں کی سرزمین سے کٹ گیا تھا: کیونکہ میرے لوگوں کی گناہ نے اسے متاثر کیا تھا۔ {قید سے...: یا، پریشانی اور فیصلے کی وجہ سے دور: لیکن، وغیرہ} {کیا وہ...: عبرانی۔ کیا اس پر حملہ ہوا تھا}\n9۔ اور اس نے اپنی قبر بدکاروں کے ساتھ اور امیروں کے ساتھ اپنی موت میں بنائی؛ کیونکہ اس نے کوئی تشدد نہیں کیا تھا، نہ ہی اس کے منہ میں کوئی دھوکہ تھا۔ {موت: عبرانی۔ اموات}\n10۔ پھر بھی خداوند نے اسے زخم پہنچایا؛ اس نے {اسے} کو غمگین کر دیا ہے: جب تم اس کی روح کو گناہ کے بدلے نذرانہ پیش کرو گے، تو وہ اپنی نسل کو دیکھے گا، وہ اپنے دنوں کو طول دے گا، اور خداوند کی رضا اس کے ہاتھ میں پھلے گی۔ {تم...: یا اس کی روح قربانی دے گی}\n11. وہ اپنی روح کی تکلیف کو دیکھے گا، {اور} مطمئن ہو جائے گا: اس کے علم سے میرا راستباز بندہ بہت سے لوگوں کو راستباز بنائے گا؛ کیونکہ وہ ان کے گناہوں کو برداشت کرے گا۔\n12۔ لہٰذا میں اسے بڑے لوگوں کے ساتھ {ایک حصہ} تقسیم کروں گا، اور وہ مال کو طاقتوروں کے ساتھ تقسیم کرے گا؛ کیونکہ اس نے اپنی جان موت تک بہا دی ہے: اور وہ مجرموں میں شمار کیا گیا؛ اور اس نے بہت سے گناہوں کا بوجھ اٹھایا، اور مجرموں کے لیے سفارش کی۔","1. اے بنجر، تو گاؤ، جو برداشت نہیں کیا؛ گانا شروع کرو، اور بلند آواز میں پکارو، تو جس نے بچے کی تکلیف نہیں کی، کیونکہ ویرانیوں کے بچے شادی شدہ بیوی کے بچوں سے زیادہ ہیں، خداوند فرماتا ہے۔\n2۔ اپنے خیمے کی جگہ کو بڑا کرو، اور انہیں اپنے گھروں کے پردے پھیلا دو: نہ چھوڑو، اپنی رسیاں لمبی کرو، اور اپنی کھمبے مضبوط کرو؛\n3۔ کیونکہ تم دائیں اور بائیں طرف سے باہر آؤ گے؛ اور تمہاری نسل غیر یہودیوں کی وارث بنے گی، اور ویران شہروں کو آباد بنائے گی۔\n4. خوف نہ کریں؛ کیونکہ تم شرمندہ نہیں ہو، نہ ہی شرمندہ ہو؛ کیونکہ تمہیں شرمندہ نہیں کیا جائے گا: کیونکہ تم اپنی جوانی کی شرمندگی کو بھول جاؤ گے، اور اپنی بیوہ پن کی ملامت کو مزید یاد نہیں رکھو گے۔\n5۔ کیونکہ تیرا خالق {ہے} تمہارا شوہر؛ لشکروں کا رب اس کا نام ہے؛ اور تمہارا نجات دہندہ، اسرائیل کا مقدس؛ اسے پوری زمین کا خدا کہا جائے گا۔ {خالق: عبرانی۔ میکرز}\n6۔ کیونکہ خداوند نے تمہیں ایک ایسی عورت کی طرح بلایا ہے جو روح میں چھوڑی گئی اور غمگین ہو، اور جب تمہیں رد کیا گیا تو جوانی کی بیوی ہو، تمہارا خدا فرماتا ہے۔\n7۔ ایک لمحے کے لیے میں نے تمہیں چھوڑ دیا ہے؛ لیکن بڑی مہربانی کے ساتھ میں تمہیں جمع کروں گا۔\n8۔ تھوڑے غصے میں میں نے ایک لمحے کے لیے اپنا چہرہ تم سے چھپا لیا؛ لیکن ہمیشہ کی مہربانی کے ساتھ میں تم پر رحم کروں گا، خداوند تیرے نجات دہندہ فرماتا ہے۔\n9۔ کیونکہ یہ {ہے} جیسا کہ نوح کا پانی میرے لیے ہے: کیونکہ {ویسے} میں نے قسم کھائی ہے کہ نوح کے پانی زمین پر نہیں بہیں گے؛ تو میں نے قسم کھائی ہے کہ میں تم سے ناراض نہیں ہوں گا، نہ تمہیں ملامت کروں گا۔\n10۔ کیونکہ پہاڑ ختم ہو جائیں گے، اور پہاڑ ہٹ جائیں گے؛ لیکن میری مہربانی تم سے جدا نہیں ہوگی، اور نہ ہی میرا امن کا عہد ختم ہو جائے گا، یہ فرماتا ہے خداوند جو تم پر رحم کرتا ہے۔\n11۔ اے تم مصیبت زدہ ہو، طوفان میں مبتلا ہو، {اور} تسلی نہیں دی، دیکھو، میں تمہارے پتھر خوبصورت رنگوں سے رکھوں گا، اور تمہاری بنیادیں نیلم سے رکھوں گا۔\n12۔ اور میں تمہاری کھڑکیاں اگیٹس سے بناؤں گا، تمہارے دروازے کاربنکل سے، اور تمہارے تمام کناروں کو خوبصورت پتھروں سے بنا دوں گا۔\n13۔ اور تمہارے تمام بچوں کو خداوند کے بارے میں تعلیم دی جائے گی؛ اور تمہارے بچوں کا سکون عظیم ہوگا۔\n14۔ راستبازی میں تم قائم ہو جاؤ گے: تم ظلم سے دور رہو گے؛ کیونکہ تمہیں خوف نہ ہو: اور خوف سے؛ کیونکہ وہ تمہارے قریب نہیں آئے گا۔\n15۔ دیکھو، وہ یقینا اکٹھے ہوں گے، {لیکن} میرے ذریعے نہیں: جو بھی تمہارے خلاف جمع ہوگا، وہ تمہارے لیے گر جائے گا۔\n16۔ دیکھو، میں نے وہ لوہار پیدا کیا ہے جو آگ میں کوئلے پھونکتا ہے، اور جو اپنے کام کے لیے ایک آلہ لاتا ہے؛ اور میں نے برباد کرنے والے کو تباہ کرنے کے لیے پیدا کیا ہے۔\n17۔ تمہارے خلاف کوئی ہتھیار کامیاب نہیں ہوگا؛ اور ہر زبان جو تمہارے خلاف فیصلے میں اٹھے گی، تم اسے مذمت کرو گے۔ یہ خداوند کے بندوں کی وراثت ہے، اور ان کی راستبازی میری ہے، خداوند فرماتا ہے۔","1۔ جو بھی پیاسا ہے، وہ پانیوں کی طرف آؤ، اور جس کے پاس پیسے نہیں؛ آؤ، خریدو اور کھاؤ؛ ہاں، آؤ، بغیر پیسے اور بغیر قیمت کے شراب اور دودھ خریدو۔\n2. تم پیسے کیوں خرچ کرتے ہو {جو روٹی نہیں}؟ اور تمہاری محنت {جو کہ} پوری نہیں کرتی؟ میری بات غور سے سنو، اور جو اچھا ہے کھاؤ، اور اپنی روح کو موٹاپے میں خوش کرو۔ {خرچ کریں: ہیب۔ وزن کریں}\n3۔ اپنا کان جھکاؤ، اور میرے پاس آؤ: سنو، اور تمہاری جان زندہ رہے گی؛ اور میں تمہارے ساتھ ایک دائمی عہد کروں گا، {حتیٰ کہ} داؤد کی پختہ رحمتوں کے ساتھ۔\n4۔ دیکھو، میں نے اسے عوام کے لیے گواہ، عوام کے لیے ایک رہنما اور کمانڈر کے طور پر پیش کیا ہے۔\n5۔ دیکھو، تو ایک ایسی قوم کو بلاؤ گے جنہیں تم نہیں جانتے، اور وہ قومیں جو تمہیں نہیں جانتیں، وہ خداوند تمہارے خدا اور اسرائیل کے مقدس کے لیے تمہاری طرف دوڑیں گی؛ کیونکہ اس نے تمہیں جلال بخشا ہے۔\n6۔ جب تک خداوند ملتا ہے، اسے پکارو، جب وہ قریب ہو تو اسے پکارو:\n7۔ بدکار اپنا راستہ چھوڑ دے، اور بدکار آدمی اپنے خیالات کو چھوڑ دے: اور وہ خداوند کی طرف لوٹ جائے، اور اس پر رحم کرے؛ اور ہمارے خدا کے لیے، کیونکہ وہ بھرپور معافی دے گا۔ {ناراست...: عبرانی۔ بدکاری کا آدمی} {کثرت سے...: عبرانی۔ معافی کے لیے ضرب دو}\n8۔ کیونکہ میرے خیالات تمہارے خیالات نہیں ہیں، اور نہ ہی تمہارے طریقے میرے طریقے ہیں، خداوند فرماتا ہے۔\n9. جیسے آسمان زمین سے بلند ہیں، ویسے ہی میرے راستے تمہارے راستوں سے بلند ہیں، اور میرے خیالات تمہارے خیالات سے بلند ہیں۔\n10۔ جیسے بارش گرتی ہے، اور آسمان سے برف آتی ہے، جو وہاں واپس نہیں آتی، بلکہ زمین کو پانی دیتی ہے، اور اسے اگاتی ہے اور پھولتی ہے، تاکہ وہ بیج دے اور کھانے والے کو روٹی دے:\n11۔ اسی طرح میرا کلام میرے منہ سے نکلے گا: وہ مجھے خالی نہیں کرے گا، بلکہ وہ جو میں چاہوں پورا کرے گا، اور اس چیز میں کامیاب ہوگا جس کے لیے میں نے بھیجا ہے۔\n12۔ کیونکہ تم خوشی کے ساتھ باہر جاؤ گے، اور امن کے ساتھ آگے بڑھو گے: پہاڑ اور پہاڑ تمہارے سامنے گانے کے لیے کھلیں گے، اور میدان کے تمام درخت ہاتھوں سے تالیاں بجائیں گے۔\n13۔ کانٹے کی جگہ فر کے درخت پر چڑھے گا، اور کانٹے کی جگہ مرٹل کے درخت پر چڑھے گا: اور یہ خداوند کے نام کے لیے ہوگا، کیونکہ ایک دائمی نشانی {جو} کاٹے نہیں جائے گی۔","1۔ خداوند یہ فرماتا ہے، فیصلہ کرو اور انصاف کرو، کیونکہ میری نجات قریب ہے، اور میری راستبازی ظاہر ہونے والی ہے۔ {فیصلہ: یا، انصاف}\n2۔ مبارک ہے {ہے} وہ شخص {جو} یہ کرتا ہے، اور انسان کا بیٹا {جو} اسے تھامے رکھتا ہے؛ جو سبت کو اسے آلودہ کرنے سے روکتا ہے، اور اس کے ہاتھ کو کسی بھی برائی سے بچاتا ہے۔\n3۔ نہ ہی اجنبی کے بیٹے کو، جو خود کو خداوند سے جوڑ چکا ہے، بولے اور کہے، خداوند نے مجھے اپنی قوم سے مکمل طور پر جدا کر دیا ہے؛ نہ ہی خواجہ سرا کہے، دیکھو، میں خشک درخت ہوں۔\n4۔ کیونکہ خداوند نے ایسے ہی ان خواجہ سرا سے فرمایا ہے جو میرے سبت کے دن نبھاتے ہیں، اور وہ چیزیں چنتے ہیں جو مجھے پسند کرتی ہیں، اور میرا عہد پکڑتے ہیں؛\n5۔ میں انہیں اپنے گھر اور اپنی دیواروں کے اندر بیٹوں اور بیٹیوں سے بہتر جگہ اور نام دوں گا: میں انہیں ایک دائمی نام دوں گا جو کاٹا نہ جائے۔\n6۔ اور اجنبی کے بیٹے، جو خود کو خداوند کے ساتھ جوڑتے ہیں، اس کی خدمت کرتے ہیں، اور خداوند کے نام سے محبت کرتے ہیں، اس کے خادم بنتے ہیں، ہر وہ شخص جو سبت کو آلودہ ہونے سے بچاتا ہے، اور میرا عہد پکڑتا ہے؛\n7۔ میں انہیں بھی اپنے مقدس پہاڑ پر لے جاؤں گا، اور انہیں اپنے عبادت کے گھر میں خوش کروں گا: ان کی جلنے کی قربانیاں اور قربانیاں {قبول کی جائیں گی} میرے محراب پر؛ کیونکہ میرا گھر تمام لوگوں کے لیے دعا کا گھر کہا جائے گا۔\n8۔ خداوند خدا جو اسرائیل کے بے دخلیوں کو جمع کرتا ہے، فرماتا ہے، پھر بھی میں [دوسروں کو} اس کے پاس جمع کروں گا، ان کے علاوہ جو اس کے لیے جمع کیے گئے ہیں۔ {اس کے علاوہ...: عبرانی۔ اپنے جمع شدہ لوگوں کے لیے}\n9۔ اے تمام میدان کے جانوروں، آؤ کھانے کے لیے، {ہاں}، اے جنگل کے تمام جانوروں۔\n10۔ اس کے محافظ اندھے ہیں: وہ سب جاہل ہیں، وہ سب بے وقوف کتے ہیں، وہ بھونک نہیں سکتے؛ سونا، لیٹنا، نیند سے محبت کرنا۔ {سونا: یا، خواب دیکھنا، یا، نیند میں بات کرنا}\n11۔ ہاں، {وہ} لالچی کتے ہیں {جو} کبھی سیر نہیں ہو سکتے، اور وہ {چرواہے ہیں} {جو} سمجھ نہیں سکتے: وہ سب اپنی راہ دیکھتے ہیں، ہر ایک اپنے فائدے کے لیے، اپنے علاقے سے۔ {لالچی: عبرانی۔ بھوک کی طاقت} {can...: عبرانی مطمئن نہ ہونا چاہیے}\n12۔ آؤ، {وہ کہتے ہیں}، میں شراب لے آؤں گا، اور ہم خود کو تیز شراب سے بھر لیں گے؛ اور کل بھی آج کی طرح ہوگا، {اور} بہت زیادہ فراوان۔","1۔ نیک فنا ہو جاتے ہیں، اور کوئی اسے دل پر نہیں لگاتا: اور رحم دل لوگ لے جایا جاتا ہے، کوئی یہ نہیں سمجھتا کہ نیک لوگ آنے والی برائی سے دور ہو جاتے ہیں۔ {مہربان...: عبرانی۔ مہربان مرد، یا، دیندار} {سے...: یا، اس چیز سے جو برائی ہے}\n2. وہ امن میں داخل ہوں گے: وہ اپنے بستروں میں آرام کریں گے، {ہر ایک} اپنی درستگی میں چلے گا۔ {داخل کریں: یا، اندر جائیں} {اپنے...: یا، اس سے پہلے}\n3. لیکن یہاں آ جاؤ، اے جادوگرنی کے بیٹو، زناکار اور بدکار کی نسل کے بیٹے۔\n4. آپ خود کو کس کے خلاف کھیلتے ہیں؟ کس کے خلاف زبان کھلی ہوئی ہے، {اور} زبان نکالتے ہیں؟ کیا تم گناہ کے بچے نہیں ہو، جھوٹ کے بیج نہیں ہو،\n5. ہر سبز درخت کے نیچے بتوں سے خود کو آگ لگا کر، وادیوں میں چٹانوں کے نیچے بچوں کو مارنا؟ {ساتھ...: یا، بلوط کے درختوں کے درمیان}\n6۔ ندی کے ہموار {پتھر} میں {ہے} تیرا حصہ؛ وہ تمہاری قسمت ہیں: اگر تم نے ان کے لیے شراب ڈالی، تو گوشت کی قربانی بھی دی۔ کیا مجھے ان میں سکون ملنا چاہیے؟\n7۔ تم نے ایک بلند اور بلند پہاڑ پر اپنا بستر رکھا ہے: یہاں بھی تم قربانی دینے کے لیے اوپر جا رہے ہو۔\n8۔ دروازوں اور ستونوں کے پیچھے بھی تم نے اپنی یاد رکھی ہے: کیونکہ تم نے مجھ سے بڑھ کر کسی اور کو دریافت کیا ہے، اور اوپر چلے گئے ہیں؛ تم نے اپنا بستر بڑا کیا ہے، اور ان کے ساتھ عہد کیا ہے؛ تم ان کے بستر سے محبت کرتے تھے جہاں تم نے دیکھا {اسے}۔ {بنایا...: یا، اپنے لیے اسے ان سے بڑا تراشا} {کہاں...: یا، تم نے جگہ فراہم کی}\n9۔ اور تم نے بادشاہ کے پاس مرہم سے ملاقات کی، اپنی خوشبو بڑھائی، اپنے پیغامبروں کو دور بھیجا، اور خود کو جہنم میں گرا دیا۔ {تم...: یا، تم عزت کرتے ہو}\n10۔ تم اپنے راستے کی عظمت سے تھک چکے ہو؛ {پھر بھی} تم نے نہیں کہا، کوئی امید نہیں: تم نے اپنے ہاتھ کی جان پا لی ہے؛ لہٰذا تم غمگین نہیں ہوئے۔ {زندگی: یا، جینا}\n11۔ اور تم کس سے ڈرتے تھے یا ڈرتے تھے، کہ تم نے جھوٹ بولا، اور مجھے یاد نہیں کیا، اور نہ ہی اسے اپنے دل میں رکھا؟ کیا میں نے پرانے زمانے میں بھی خاموش نہیں رہا، اور تم مجھ سے نہیں ڈرتے؟\n12۔ میں تیری راستبازی اور تمہارے اعمال کا اعلان کروں گا؛ کیونکہ وہ تمہیں فائدہ نہیں دیں گے۔\n13۔ جب تم پکارو، تو تمہاری جماعتیں تمہیں نجات دیں؛ لیکن ہوا انہیں سب کو لے جائے گی؛ غرور ان پر قبضہ کر لے گا: لیکن جو مجھ پر بھروسہ کرے گا وہ زمین کا مالک ہوگا، اور میرے مقدس پہاڑ کا وارث ہوگا؛\n14۔ اور کہے گا، پھینک دو، پھینک دو، راستہ تیار کرو، رکاوٹ اٹھا کر میرے لوگوں کے راستے سے ہٹ جاؤ۔\n15۔ کیونکہ یہی فرماتا ہے وہ بلند اور بلند ذات جو ابدیت میں رہتا ہے، جس کا نام {پاک} ہے؛ میں اعلیٰ اور مقدس {مقام} میں رہتا ہوں، اس کے ساتھ {یعنی} ایک پشیمان اور عاجز روح کا بھی، تاکہ عاجزوں کی روح کو زندہ کروں، اور توبہ کرنے والوں کے دل کو زندہ کروں۔\n16۔ کیونکہ میں ہمیشہ کے لیے لڑائی نہیں کروں گا، نہ ہی ہمیشہ غصے میں رہوں گا: کیونکہ روح میرے سامنے اور ان روحوں کے سامنے ناکام ہو جائے گی جو میں نے بنائی ہیں۔\n17۔ کیونکہ اس کی لالچ کی گناہ میں نے غصہ کیا اور اسے مارا: میں نے خود کو چھپایا، اور غصے میں آیا، اور وہ اپنے دل کی راہ میں بے قابو ہو گیا۔ {شرارتی انداز میں: عبرانی۔ مڑ کر}\n18. میں نے اس کے طریقے دیکھے ہیں، اور اسے شفا دوں گا: میں اسے بھی رہنمائی کروں گا، اور اس کے اور اس کے سوگواروں کو تسلی دوں گا۔\n19. میں ہونٹوں کا پھل پیدا کرتا ہوں؛ سلام، امن اس کے لیے جو دور ہے، اور جو قریب ہے، خداوند فرماتا ہے؛ اور میں اسے شفا دوں گا۔\n20. لیکن بدکار ایسے ہیں جیسے پریشان سمندر جب وہ آرام نہیں کر سکتا، جس کا پانی کیچڑ اور مٹی بکھیرتا ہے۔\n21. {کوئی امن نہیں}، میرے خدا نے برے لوگوں سے فرمایا۔","1۔ بلند آواز میں پکارو، رحم نہ کرو، اپنی آواز بگل کی طرح بلند کرو، اور میرے لوگوں کو ان کی گناہ دکھاؤ، اور یعقوب کے گھرانے کو ان کے گناہ دکھاؤ۔ {بلند آواز میں: عبوری۔ گلے کے ساتھ}\n2۔ پھر بھی وہ روزانہ مجھے تلاش کرتے ہیں، اور میرے راستے جاننے میں خوشی محسوس کرتے ہیں، ایک ایسی قوم کے طور پر جس نے نیکی کی اور اپنے خدا کے حکم کو ترک نہیں کیا: وہ مجھ سے انصاف کے احکامات مانگتے ہیں؛ وہ خدا کے قریب جانے میں خوشی محسوس کرتے ہیں۔\n3. ہم نے روزہ کیوں رکھا ہے، {وہ کہتے ہیں}، اور تم نہیں دیکھتے؟ ہم نے اپنی روح کو کیوں تکلیف دی، اور تم علم نہیں لیتے؟ دیکھو، روزے کے دن تم خوشی پاتے ہو، اور اپنی تمام محنت کرتے ہو۔ {محنت: یا، وہ چیزیں جن سے تم دوسروں کو غمگین کرتے ہو: عبرانی۔ غم}\n4۔ دیکھو، تم لڑائی اور بحث کے لیے روزہ رکھتے ہو، اور برائی کے مکے سے مارو: تم آج کی طرح روزہ نہیں رکھو گے، تاکہ اپنی آواز بلند آواز میں سنائی دے۔ {تم...: یا، تم آج کی طرح روزہ نہیں رکھو}\n5. کیا یہ اتنا ہی تیز ہے جو میں نے چنا ہے؟ ایک دن جب انسان اپنی روح کو تکلیف دے؟ {کیا یہ ہے}کہ وہ اپنا سر جھکا کر بلرش کی طرح جھک جائے، اور کپڑے اور راکھ {اس کے نیچے پھیلا دے}؟ کیا تم اسے روزہ اور خداوند کے لیے قابل قبول دن کہو گے؟ {ایک دن...: یا، اس کی روح کو ایک دن کے لیے تکلیف دینا؟}\n6. کیا یہ وہ روزہ نہیں جو میں نے چنا ہے؟ برائی کے بندھن کھولنے کے لیے، بھاری بوجھ کھولنے کے لیے، مظلوموں کو آزاد کرنے کے لیے، اور ہر بندھن توڑنے کے لیے؟ {بھاری...: عبرانی یوک کے گٹھے} {مظلوم: عبرانی۔ ٹوٹا ہوا}\n7۔ کیا یہ نہیں کہ تم اپنی روٹی بھوکوں کو بانٹو، اور ان غریبوں کو اپنے گھر لے آؤ؟ جب تم ننگا دیکھو، تو تم اسے ڈھانپ لیتے ہو؛ اور تم اپنے جسم سے خود کو نہ چھپاؤ؟ {cast...: یا، مصیبت}\n8۔ پھر تمہاری روشنی صبح کی طرح چمٹے گی، اور تمہاری صحت تیزی سے پھوٹے گی: اور تیری راستبازی تمہارے سامنے جائے گی؛ خداوند کی شان تمہارا بدلہ ہوگی۔ {be...: عبرانی۔ جمع ہو جاؤ}\n9۔ پھر تم پکارو گے، اور خداوند جواب دے گا؛ تم روؤ گے، اور وہ کہے گا، میں یہاں ہوں۔ اگر تم اپنے درمیان سے جو، انگلی نکالنے، اور بکواس کہنے سے ہٹا دو؛\n10۔ اور اگر تم اپنی روح بھوکوں کے لیے نکالو، اور مصیبت زدہ روح کو تسکین دو؛ تب تمہاری روشنی گمنامی میں ابھرے گی، اور تمہاری تاریکی دوپہر کی طرح ہو جائے گی:\n11۔ اور خداوند تمہیں مسلسل رہنمائی دے گا، تمہاری روح کو خشک سالی میں تسکین دے گا، اور تمہاری ہڈیاں موٹی کرے گا، اور تم ایک پانی والے باغ کی مانند بنو گے، اور پانی کے چشمے کی مانند جس کا پانی کبھی نہیں بلے گا۔ {خشک سالی: عبرانی۔ خشک سالی} {ناکام: عبرانی۔ جھوٹ بولو، یا، دھوکہ دینا}\n12۔ اور {جو تم میں سے ہوں گے} وہ پرانے ویران مقامات تعمیر کریں گے: تم کئی نسلوں کی بنیادیں اٹھاؤ گے؛ اور تمہیں بلایا جائے گا، دراڑ کی مرمت کرنے والی، رہنے کے راستوں کی بحالی۔\n13۔ اگر تم اپنے قدم کو ہفتہ سے ہٹا دو، {سے} اپنی مرضی سے میرے مقدس دن پر؛ اور سبت کو لذت، خداوند کا مقدس، معزز کہیں؛ اور اس کی عزت کرو، نہ اپنی مرضی کرو، نہ اپنی خوشی پاؤ، نہ اپنے الفاظ کہو:\n14۔ تو پھر تم خداوند میں خوش ہو؛ اور میں تمہیں زمین کی اونچی جگہوں پر سوار کروں گا، اور تمہیں یعقوب تمہارے باپ کی میراث سے کھلاؤں گا: کیونکہ خداوند کے منہ نے کہا ہے۔","1۔ دیکھو، خداوند کا ہاتھ چھوٹا نہیں ہوا، کہ وہ بچا نہیں سکتا؛ نہ اس کا کان، جو سن نہیں سکتا:\n2۔ لیکن تمہارے گناہوں نے تم اور تمہارے خدا کے درمیان جدائی کر دی ہے، اور تمہارے گناہوں نے اس کا چہرہ تم سے چھپا دیا ہے، جو وہ سن نہیں سکتا۔ {چھپ گیا: یا، اسے چھپایا ہے}\n3۔ کیونکہ تمہارے ہاتھ خون سے آلودہ ہیں، اور تمہاری انگلیاں گناہ سے؛ تمہارے ہونٹوں نے جھوٹ بولے ہیں، تمہاری زبان نے بے راہ روی کی سرگوشی کی ہے۔\n4۔ کوئی انصاف کے لیے نہیں پکارتا، نہ کوئی سچائی کی درخواست کرتا ہے: وہ باطل پر بھروسہ کرتے ہیں اور جھوٹ بولتے ہیں؛ وہ شرارتیں کرتے ہیں، اور بدکاری کو جنم دیتے ہیں۔\n5. وہ کاکاٹریس کے انڈے نکالتے ہیں، اور مکڑی کا جال بنتے ہیں: جو ان کے انڈے کھاتا ہے وہ کھاتا ہے، اور جو کچلا جاتا ہے وہ سانپ بن جاتا ہے۔ {کاکاٹریس': یا، ایڈرز کا} {کچلا گیا...: یا، چھڑک کر ایسا ہے جیسے وہاں کوئی سانپ ٹوٹ جائے}\n6۔ ان کے جال کپڑے نہیں بنیں گے، نہ ہی وہ اپنے اعمال سے ڈھانپیں گے: ان کے اعمال گناہ کے کام ہیں، اور ظلم کا عمل ان کے ہاتھ میں ہے۔\n7۔ ان کے قدم برائی کی طرف دوڑتے ہیں، اور معصوم خون بہانے کے لیے جلدی کرتے ہیں: ان کے خیالات گناہ کے خیالات ہیں؛ ضیاع اور تباہی ان کے راستے میں ہے۔ {تباہی: عبرانی۔ بریکنگ}\n8۔ امن کا راستہ جو وہ نہیں جانتے؛ اور ان کے چلنے میں کوئی فیصلہ نہیں: انہوں نے انہیں ٹیڑھے راستے بنا دیے ہیں: جو بھی وہاں جائے گا اسے سکون نہیں ملے گا۔ {فیصلہ: یا، صحیح}\n9۔ لہٰذا فیصلہ ہم سے دور ہے، نہ ہی انصاف ہمیں قابو پاتا ہے: ہم روشنی کا انتظار کرتے ہیں، لیکن گندگی کو دیکھتے ہیں؛ روشنی کے لیے، {لیکن} ہم اندھیرے میں چلتے ہیں۔\n10۔ ہم دیوار کو اندھے کی طرح چھوتے ہیں، اور ایسے چھوتے ہیں جیسے کہ ہماری کوئی آنکھ نہ ہو: ہم دوپہر کو رات کی طرح لڑکھڑاتے ہیں؛ {ہم} ویران جگہوں پر مردہ {مرد} کی طرح ہیں۔\n11۔ ہم سب ریچھوں کی طرح دہاڑتے ہیں، اور کبوتر کی طرح غمگین ہوتے ہیں: ہم فیصلہ چاہتے ہیں، لیکن کوئی نہیں؛ نجات کے لیے، {لیکن} یہ ہم سے بہت دور ہے۔\n12۔ کیونکہ ہمارے گناہ تیرے سامنے بڑھ جاتے ہیں، اور ہمارے گناہ ہمارے خلاف گواہی دیتے ہیں: کیونکہ ہمارے گناہ ہمارے ساتھ ہیں؛ اور {جہاں تک} ہماری گناہوں کا تعلق ہے، ہم انہیں جانتے ہیں؛\n13۔ خداوند کے خلاف سرکشی اور جھوٹ بولنے میں، اور اپنے خدا سے دور ہو کر، ظلم اور بغاوت کا اظہار کرنا، دل سے جھوٹ کے الفاظ سمجھنا اور بولنا۔\n14۔ اور فیصلہ الٹا کر دیا جاتا ہے، اور انصاف دور کھڑا ہو جاتا ہے: کیونکہ سچائی سڑک پر گر جاتی ہے، اور انصاف اندر نہیں آ سکتا۔\n15. ہاں، سچائی ناکام ہو جاتی ہے؛ اور جو برائی سے نکلتا ہے وہ خود کو شکار بناتا ہے: اور خداوند نے دیکھ لیا، اور اسے ناپسند آیا کہ کوئی فیصلہ نہیں ہوا۔ {maketh...: یا، پاگل سمجھا جاتا ہے} {یہ ناراض...: عبرانی یہ اس کی نظر میں شیطانی تھا}\n16۔ اور اس نے دیکھا کہ {کوئی آدمی} نہیں ہے، اور حیران ہوا کہ {کوئی شفاعت کرنے والا} نہیں ہے: اس لیے اس کا بازو اسے نجات دلاتا ہے؛ اور اس کی راستبازی نے اسے سہارا دیا۔\n17۔ کیونکہ اس نے راستبازی کو سینے کی طرح پہنا، اور اپنے سر پر نجات کا ہیلمٹ پہنا؛ اور اس نے انتقام کے کپڑے پہنے، اور جوش و جذبے سے ملبوس ہو گیا۔\n18۔ ان کے اعمال کے مطابق، وہ اپنے مخالفین کو غصہ اور دشمنوں کو بدلہ دے گا؛ جزائر کو وہ اس کا بدلہ چکائے گا۔ {کارنامے: عبرانی۔ معاوضہ}\n19۔ اسی طرح وہ مغرب سے خداوند کے نام سے ڈریں گے، اور سورج کے طلوع ہونے سے اس کی شان سے ڈریں گے۔ جب دشمن سیلاب کی طرح آئے گا، تو خداوند کی روح اس کے خلاف پرچم اٹھائے گی۔ {اٹھاؤ...: یا، اسے بھگا دو}\n20۔ اور نجات دہندہ صیہون آئے گا، اور یعقوب میں گناہ سے منہ موڑنے والوں کے پاس، خداوند فرماتا ہے۔\n21. جہاں تک میرا تعلق ہے، یہ {ہے} میرا ان کے ساتھ عہد ہے، خداوند فرماتا ہے؛ میری روح جو آپ پر ہے، اور میرے الفاظ جو میں نے تیرے منہ میں رکھے ہیں، نہ تیرے منہ سے، نہ تیری نسل کے منہ سے، نہ تیری نسل کے منہ سے، خداوند فرماتا ہے، اب سے اور ہمیشہ کے لیے۔","1. اٹھو، چمکو؛ کیونکہ تیری روشنی آ گئی ہے، اور خداوند کی جلال تم پر اٹھی ہے۔ {چمک...: یا، روشن ہو جاؤ؛ کیونکہ تیری روشنی آتی ہے}\n2۔ کیونکہ دیکھو، اندھیرا زمین کو ڈھانپے گا اور لوگوں کو گہرا اندھیرا لے گا، لیکن خداوند تم پر اٹھے گا، اور اس کی جلال تم پر نظر آئے گی۔\n3۔ اور غیر یہودی تیری روشنی میں آئیں گے، اور بادشاہ تیرے قیامت کی روشنی کی طرف آئیں گے۔\n4۔ اپنی آنکھیں ادھر ادھر اٹھاؤ، اور دیکھو: جو سب اکٹھے ہوتے ہیں، وہ تمہارے پاس آتے ہیں: تمہارے بیٹے دور سے آئیں گے، اور تمہاری بیٹیاں تمہارے ساتھ دودھ پلا رہی ہوں گی۔\n5۔ پھر تم دیکھو گے، اور ایک ساتھ بہاؤ گے، اور تمہارا دل ڈرے گا، اور بڑا ہوگا؛ کیونکہ سمندر کی فراوانی تمہارے لیے تبدیل ہو جائے گی، غیر یہودیوں کی فوجیں تمہارے پاس آئیں گی۔ {فراوانی...: یا، سمندر کی آواز تمہاری طرف مڑی جائے گی} {قوتیں: یا، دولت}\n6۔ اونٹوں کی کثرت تمہیں ڈھانپے گی، مدیان اور ایفاہ کے ڈرومیڈریوں کو؛ جو سب سبا سے آئیں گے: وہ سونا اور لوبان لائیں گے؛ اور وہ خداوند کی تعریف کریں گے۔\n7۔ کیدار کے تمام ریوڑ تمہارے پاس جمع ہوں گے، نیبایوت کے مینڈھے تمہاری خدمت کریں گے: وہ میرے قربان گاہ پر قبولیت کے ساتھ آئیں گے، اور میں اپنے جلال کے گھر کی جلال بخشوں گا۔\n8. یہ کون ہیں جو بادل کی طرح اڑتے ہیں، اور اپنی کھڑکیوں کی طرف کبوتر کی طرح اڑتے ہیں؟\n9۔ یقینا جزائر میرے اور ترشیش کے جہاز سب سے پہلے انتظار کریں گے کہ میں دور سے اپنے بیٹوں کو ان کے چاندی اور سونے کے ساتھ لے آؤں، خداوند تمہارے خدا کے نام پر، اور اسرائیل کے مقدس وجود کے لیے، کیونکہ اس نے تیری جلال دی ہے۔\n10۔ اور اجنبیوں کے بیٹے تمہاری دیواریں بنائیں گے، اور ان کے بادشاہ تمہاری خدمت کریں گے: کیونکہ میں نے اپنے غصے میں تمہیں مارا ہے، لیکن اپنے حق میں میں نے تم پر رحم کیا ہے۔\n11۔ اس لیے تمہارے دروازے مسلسل کھلے رہیں گے؛ انہیں دن یا رات بند نہیں کیا جائے گا؛ تاکہ {لوگ} غیر یہودیوں کی فوجیں تمہارے پاس لا سکیں، اور {جو} ان کے بادشاہ {لائے جائیں}۔ {قوتیں: یا، دولت}\n12۔ کیونکہ وہ قوم اور بادشاہی جو تمہاری خدمت نہیں کرے گی، فنا ہو جائے گی؛ ہاں، {وہ} قومیں مکمل طور پر ضائع ہو جائیں گی۔\n13۔ لبنان کی شان تمہیں ملے گی، صنوبر کا درخت، صنوبر کا درخت، اور صندوق مل کر، تاکہ میرے مقدس مقام کو خوبصورت بنایا جا سکے؛ اور میں اپنے قدموں کی جگہ کو شاندار بنا دوں گا۔\n14۔ ان کے بیٹے بھی جنہوں نے تمہیں تکلیف دی، وہ بھی تمہارے سامنے جھک کر آئیں گے؛ اور جو لوگ تمہیں حقیر سمجھتے ہیں وہ تمہارے قدموں کے تلووں پر جھک جائیں گے؛ اور وہ تمہیں کہیں گے، خداوند کا شہر، اسرائیل کے مقدس وجود کا صیون۔\n15۔ جہاں تمہیں چھوڑ دیا گیا اور نفرت کی گئی، یہاں تک کہ کوئی انسان تمہارے ذریعے نہیں گیا، میں تمہیں ایک دائمی عظمت اور کئی نسلوں کی خوشی بناؤں گا۔\n16۔ تم غیر یہودیوں کا دودھ بھی چوستے ہو، اور بادشاہوں کے سینے کو بھی چوستے ہو: اور تم جان لو گے کہ میں خداوند تمہارا نجات دہندہ اور تیرا نجات دہندہ ہوں، یعقوب کا طاقتور ہوا۔\n17۔ پیتل کے لیے میں سونا لاؤں گا، لوہے کے لیے چاندی، لکڑی کے پیتل کے لیے، اور پتھروں کے لیے لوہا: میں تمہارے افسران کو بھی امن دوں گا، اور تمہارے سخت گیر راستبازی کو بھی۔\n18۔ تیری سرزمین میں تشدد مزید نہیں سنا جائے گا، نہ ضائع ہوگا اور نہ ہی تباہی تمہاری سرحدوں کے اندر؛ لیکن تم اپنی دیواروں کو نجات کہو گے، اور اپنے دروازوں کو تعریف کرو۔\n19۔ دن میں سورج تمہاری روشنی نہیں رہے گا؛ نہ چاندنی کے لیے چاند تمہیں روشنی دے گا، بلکہ خداوند تمہارے لیے ہمیشہ کی روشنی ہوگا، اور تیرا خدا تمہاری جلال۔\n20۔ تمہارا سورج اب غروب نہیں ہوگا؛ نہ ہی تمہارا چاند پیچھے ہٹے گا: کیونکہ خداوند تیری ابدی روشنی ہوگا، اور تمہارے سوگ کے دن ختم ہو جائیں گے۔\n21۔ تمہارے لوگ بھی {تمام} نیک ہوں گے: وہ ہمیشہ کے لیے زمین کے وارث ہوں گے، میری کاشت کی شاخ، میرے ہاتھوں کا کام، تاکہ میں جلال حاصل کر سکوں۔\n22۔ ایک چھوٹا ہزار بنے گا، اور چھوٹا ایک مضبوط قوم: میں خداوند اس کے وقت میں اسے جلدی کروں گا۔","1. خداوند خدا کی روح {ہے} میرے اوپر؛ کیونکہ خداوند نے مجھے عاجزوں کو خوشخبری دینے کے لیے مسح کیا ہے؛ اس نے مجھے بھیجا ہے کہ ٹوٹے دل کو باندھوں، قیدیوں کو آزادی کا اعلان کروں، اور قید خانہ کھولوں جو پابند ہیں؛\n2۔ خداوند کے قابل قبول سال اور ہمارے خدا کے انتقام کے دن کا اعلان کرنا؛ ان سب کو تسلی دینے کے لیے؛\n3۔ جو لوگ صیون میں ماتم کرتے ہیں ان کے لیے راکھ کے بدلے خوبصورتی، سوگ کے لیے خوشی کا تیل، بھاری پن کی روح کے لیے تعریف کا لباس دینا؛ تاکہ انہیں راستبازی کے درخت کہا جائے، خداوند کی کاشت کنی، تاکہ وہ جلال پائے۔\n4۔ اور وہ پرانے ویرانوں کو تعمیر کریں گے، وہ پرانے ویرانوں کو دوبارہ زندہ کریں گے، اور وہ ویران شہروں کی مرمت کریں گے، جو کئی نسلوں کی ویرانی ہیں۔\n5۔ اور اجنبی کھڑے ہوں گے اور تمہارے ریوڑ کو کھلائیں گے، اور اجنبی کے بیٹے تمہارے ہل چلانے والے اور تمہارے انگور بنانے والے ہوں گے۔\n6۔ لیکن آپ کو خداوند کے کاہین نامزد کیا جائے گا: {لوگ} آپ کو ہمارے خدا کے خادم بلائیں گے: آپ غیر یہودیوں کی دولت کھائیں گے، اور ان کی شان میں فخر کریں گے۔\n7۔ تمہاری شرمندگی کے لیے {تمہیں دوگنا ملے گا}؛ اور {الجھن} کی وجہ سے وہ اپنے حصے پر خوش ہوں گے: اس لیے ان کی زمین میں وہ دوہرا مالک ہوں گے: ان کے لیے ہمیشہ کی خوشی ہوگی۔\n8. کیونکہ میں خداوند فیصلے سے محبت کرتا ہوں، میں جلانے کی قربانی کے لیے لوٹ مار سے نفرت کرتا ہوں؛ اور میں ان کے کام کی سچائی میں رہنمائی کروں گا، اور ان کے ساتھ ایک دائمی عہد کروں گا۔\n9۔ اور ان کی نسل غیر قوموں میں جانی جائے گی، اور ان کی اولاد لوگوں میں: جو انہیں دیکھے گا وہ تسلیم کرے گا کہ وہ وہ نسل ہیں جو خداوند نے برکت دی ہے۔\n10۔ میں خداوند میں بہت خوش ہوں گا، میری روح اپنے خدا میں خوش ہوگی؛ کیونکہ اس نے مجھے نجات کے کپڑے پہنائے ہیں، اس نے مجھے راستبازی کے لباس میں ڈھانپ دیا ہے، جیسے دولہا خود کو زیورات سے سجاتا ہے، اور دلہن اپنے زیورات سے سجاتی ہے۔ {ڈیکیتھ: عبرانی پادری کے طور پر ڈیکیتھ}\n11۔ کیونکہ جیسے زمین اپنی کلی نکالتی ہے، اور جیسے باغ اپنی بوئی ہوئی چیزوں کو پھوٹنے دیتا ہے؛ تو خداوند خدا تمام قوموں کے سامنے راستبازی اور تعریف کو جنم دے گا۔","1۔ صیون کی خاطر میں خاموش نہیں رہوں گا، اور یروشلم کی خاطر میں آرام نہیں کروں گا، جب تک اس کی راستبازی روشنی کی طرح باہر نہ نکلے، اور اس کی نجات ایک چراغ کی طرح نہ جل جائے۔\n2۔ اور غیر یہودی تیری راستبازی دیکھیں گے، اور تمام بادشاہوں کو تمہاری شان دیکھے گا: اور تمہیں ایک نئے نام سے پکارا جائے گا، جسے خداوند کا منہ نام دے گا۔\n3. تو خداوند کے ہاتھ میں جلال کا تاج بھی بنو گے، اور اپنے خدا کے ہاتھ میں شاہی تاج بھی۔\n4۔ اب تمہیں ترک شدہ نہیں کہا جائے گا؛ اور نہ ہی تمہاری زمین کو اب ویران کہا جائے گا: لیکن تمہیں حفزیبہ کہا جائے گا، اور تمہاری زمین بیولا کہلائے گی: کیونکہ خداوند تم پر خوش ہے، اور تمہاری زمین شادی ہو جائے گی۔ {ہفزیبا: یعنی، میری خوشی اس میں ہے} {بیولا: یعنی، شادی شدہ}\n5۔ جیسے ایک نوجوان کنواری سے شادی کرتا ہے، اسی طرح تمہارے بیٹے تم سے شادی کریں گے: اور جیسے دولہا دلہن پر خوش ہوتا ہے، ویسے ہی تمہارا خدا تم پر خوش ہوگا۔ {جیسا کہ...: عبرانی۔ دولہے کی خوشی کے ساتھ}\n6. اے یروشلم، میں نے تیری دیواروں پر پہرے دار مقرر کیے ہیں، {جو} دن اور رات کبھی سکون نہیں رکھیں گے: جو خداوند کا ذکر کرتے ہیں، خاموش نہ رہو، {کرو ...: ورنہ خداوند کے یادیں رکھنے والے ہیں}\n7۔ اور اسے آرام نہ دو، جب تک وہ قائم نہ ہو جائے، اور جب تک وہ یروشلم کو زمین میں تعریف نہ بنا دے۔ {آرام: عبرانی خاموشی}\n8۔ خداوند نے اپنے دائیں ہاتھ اور اپنی طاقت کے بازو سے قسم کھائی ہے، یقینا میں تمہارا اناج تمہارے دشمنوں کے لیے گوشت نہیں دوں گا؛ اور اجنبی کے بیٹے تمہاری شراب نہیں پئیں گے، جس کے لیے تم نے محنت کی ہے: {یقینا...: عبرانی۔ اگر میں دوں، وغیرہ}\n9۔ لیکن جو اسے جمع کریں گے وہ اسے کھائیں گے اور خداوند کی تعریف کریں گے؛ اور جنہوں نے اسے اکٹھا کیا ہے، وہ اسے میری پاکیزگی کے درباروں میں پیئیں گے۔\n10۔ دروازوں سے گزریں، دروازوں سے گزریں؛ لوگوں کے راستے کو تیار کرو؛ پھینک دو، ہائی وے پر پھینکو؛ پتھر جمع کریں؛ لوگوں کے لیے معیار بلند کریں۔\n11۔ دیکھو، خداوند نے دنیا کے آخر تک اعلان کیا ہے، اے صیہون کی بیٹی سے کہو، دیکھو، تیری نجات آ رہی ہے؛ دیکھو، اس کا اجر {ہے} اس کے ساتھ، اور اس کا کام اس کے سامنے ہے۔ {کام: یا، معاوضہ}\n12۔ اور وہ انہیں کہیں گے، مقدس لوگ، خداوند کے نجات پانے والے: اور تمہیں بلایا جائے گا، تلاش کیا جائے گا، ایک ایسا شہر جو ترک نہیں کیا گیا۔","1. یہ کون ہے جو ادوم سے آتا ہے، بوزرہ سے رنگے ہوئے کپڑوں کے ساتھ؟ یہ {یعنی} اپنے لباس میں شاندار، اپنی طاقت کی عظمت میں سفر کرتے ہوئے؟ میں جو راستبازی میں بات کرتا ہوں، بچانے کے لیے طاقتور۔ {شاندار: عبرانی۔ ڈیکڈ}\n2. کیوں تم اپنے کپڑوں میں سرخ ہو، اور تمہارے کپڑے اس کی طرح ہیں جو شراب کی چربی میں چلتا ہے؟\n3. میں نے اکیلا شراب کے پریس پر قدم رکھا ہے؛ اور ان لوگوں میں سے کوئی میرے ساتھ نہیں تھا: کیونکہ میں اپنے غصے میں انہیں روند دوں گا، اور اپنے غصے میں روندوں گا؛ اور ان کا خون میرے کپڑوں پر چھڑکا جائے گا، اور میں اپنی ساری کپڑوں کو داغدار کر دوں گا۔\n4. کیونکہ انتقام کا دن {ہے} میرے دل میں، اور میرے نجات پانے کا سال آ گیا ہے۔\n5۔ اور میں نے دیکھا، اور کوئی مدد کرنے والا نہیں تھا؛ اور میں نے سوچا کہ سہارا دینے کے لیے کوئی نہیں: اس لیے میرا اپنا بازو مجھے نجات دیتا ہے؛ اور میرا غصہ، اس نے مجھے سہارا دیا۔\n6۔ اور میں اپنے غصے میں لوگوں کو روند ڈالوں گا، انہیں اپنے غصے میں نشے میں ڈالوں گا، اور ان کی طاقت زمین پر لاؤں گا۔\n7۔ میں خداوند کی محبت بھری مہربانیوں کا ذکر کروں گا، {اور} خداوند کی تعریفوں کے مطابق، جو خداوند نے ہمیں عطا کی ہے، اور اسرائیل کے گھر کے لیے جو عظیم بھلائی ہے، جو اس نے اپنی رحمتوں اور اپنی محبت کی کثرت کے مطابق ان پر عطا کی ہے۔\n8۔ کیونکہ اس نے کہا، یقینا وہ میرے لوگ ہیں، بچے جو جھوٹ نہیں بولیں گے: تو وہ ان کا نجات دہندہ تھا۔\n9۔ ان کی تمام مصیبتوں میں وہ مصیبت میں مبتلا ہوا، اور اس کی موجودگی کے فرشتے نے انہیں بچایا: اپنی محبت اور ہمدردی میں اس نے انہیں نجات دی؛ اور وہ انہیں اٹھایا، اور پرانے دنوں میں اٹھائے رہا۔\n10۔ لیکن انہوں نے بغاوت کی، اور اس کی روح القدس کو ناراض کیا: اس لیے وہ ان کا دشمن بن گیا، {اور} اس نے ان کے خلاف لڑائی کی۔\n11۔ پھر اس نے پرانے زمانے یاد کیے، موسیٰ، {اور} اپنے لوگوں کو، {کہ}، وہ کہاں ہے جس نے انہیں اپنے ریوڑ کے چرواہے کے ساتھ سمندر سے نکالا؟ وہ کہاں ہے جس نے اپنی روح القدس اس کے اندر رکھی ہے؟ {چرواہا: یا، چرواہے}\n12. جس نے موسیٰ کے دائیں ہاتھ سے اپنے شاندار بازو سے پانی کو تقسیم کر کے اپنے لیے ایک دائمی نام بنایا؟\n13. جس نے انہیں گہرائی میں لے جایا، جیسے صحرا میں گھوڑے، {تاکہ} وہ ٹھوکر نہ کھائیں؟\n14۔ جیسے کوئی جانور وادی میں اترتا ہے، خداوند کی روح نے اسے آرام دیا: تو نے اپنے لوگوں کی رہنمائی کی، تاکہ اپنے لیے ایک شاندار نام رکھو۔\n15۔ آسمان سے نیچے دیکھو، اور اپنی پاکیزگی اور جلال کے گھر سے دیکھو: تمہاری جوش اور طاقت، تمہاری آنتوں کی آواز اور تمہاری رحمتوں کی آواز میرے لیے کہاں ہے؟ کیا وہ قابو میں ہیں؟ {آواز: یا، ہجوم}\n16. یقینا تو ہمارا باپ ہو، چاہے ابراہیم ہم سے ناواقف ہو، اور اسرائیل ہمیں تسلیم نہ کرے: اے خداوند، تو ہمارا باپ اور نجات دہندہ ہے؛ تیرا نام {ہے} ازل سے ہے۔ {ہمارا نجات دہندہ...: یا، ہمارا ہمیشہ سے نجات دہندہ تیرا نام ہے}\n17۔ اے خداوند، تو نے ہمیں اپنے راستوں سے کیوں گمراہ کیا، اور ہمارے دل کو اپنے خوف سے کیوں سخت کر دیا؟ اپنے بندوں کے لیے، اپنی وراثت کے قبائل کے لیے واپس آؤ۔\n18. تیری پاکیزگی کے لوگوں نے تھوڑی دیر کے لیے اس پر قبضہ کر لیا ہے: ہمارے مخالفین نے تمہاری پناہ گاہ کو روند ڈالا ہے۔\n19۔ ہم {تمہارے} ہیں: تو کبھی ان پر حکمرانی نہیں کرتی؛ انہیں تمہارے نام سے نہیں پکارا گیا۔ {وہ...: عبرانی۔ تیرا نام ان پر نہیں پکارا گیا}","1۔ کاش تم آسمان پھاڑنا چاہو، تاکہ تم نیچے آ جاؤ، تاکہ پہاڑ تمہاری موجودگی میں نیچے بہہ جائیں،\n2۔ جیسے {جب} پگھلتی آگ جلتی ہے، آگ پانی کو ابال دیتی ہے، تاکہ تمہارا نام تمہارے دشمنوں کو معلوم ہو، {تاکہ} قومیں تمہاری موجودگی میں کانپ جائیں! {پگھلتا ہوا...: عبرانی۔ پگھلنے کی آگ}\n3۔ جب تم نے وہ خوفناک کام کیے جن کی ہم نے توقع نہیں کی، تو تم نیچے آئے، پہاڑ تمہاری موجودگی میں بہنے لگے۔\n4۔ کیونکہ دنیا کے آغاز سے {انسان} نے نہ سنا ہے، نہ کانوں سے محسوس کیا، اور نہ ہی آنکھ نے دیکھا، اے خدا، تیرے سوا جو اس نے اس کے لیے تیار کیا ہے جو اس کا انتظار کر رہا ہے۔ {دیکھا...: یا، تمہارے ساتھ کوئی خدا دیکھا، جو اس کے لیے ایسا کرتا ہے، وغیرہ}\n5۔ تم اس سے ملتے ہو جو خوش ہوتا ہے اور راستبازی کرتا ہے، {جو تمہیں تمہارے راستوں میں یاد کرتے ہیں: دیکھو، تم غصے میں ہو؛ کیونکہ ہم نے گناہ کیا ہے: انہی میں استقامت ہے، اور ہم نجات پائیں گے۔\n6۔ لیکن ہم سب ایک ناپاک {چیز} کی طرح ہیں، اور ہماری تمام راستبازی گندے کپڑوں کی طرح ہیں؛ اور ہم سب پتے کی طرح مدھم ہو جاتے ہیں؛ اور ہمارے گناہوں، ہوا کی طرح، ہمیں لے گئے ہیں۔\n7۔ اور کوئی نہیں جو تیرے نام کو پکارے، جو خود کو آپ پر قابو پانے کے لیے اٹھے، کیونکہ آپ نے اپنا چہرہ ہم سے چھپا لیا اور ہمیں ہمارے گناہوں کی وجہ سے کھا لیا۔ {استعمال شدہ: عبرانی۔ پگھلا ہوا} {کیونکہ: عبرانی۔ ہاتھ سے}\n8. لیکن اب، اے خداوند، تو ہمارا باپ ہے؛ ہم مٹی ہیں، اور تم ہمارے کمہار ہو؛ اور ہم سب تیرے ہاتھ کا کام ہیں۔\n9۔ اے خداوند، بہت زیادہ غصہ نہ کرو، اور ہمیشہ کے لیے گناہ کو یاد نہ رکھو: دیکھو، ہم تجھ سے التجا کرتے ہیں، ہم تیری ساری قوم ہیں۔\n10. تیرے مقدس شہر ویران ہیں، صیون بیابان ہے، یروشلم ویران ہے۔\n11۔ ہمارا مقدس اور خوبصورت گھر، جہاں ہمارے آباؤ اجداد نے تمہاری تعریف کی، آگ میں جل جاتا ہے: اور ہماری ساری خوشگوار چیزیں تباہ ہو جاتی ہیں۔\n12. کیا تم ان {چیزوں} کے لیے خود کو روک لو گے، اے خداوند؟ کیا تم خاموش رہو گے، اور ہمیں بہت تکلیف پہنچاؤ گے؟","1. میں ان لوگوں سے مانگا جا رہا ہوں جنہوں نے مجھ سے درخواست نہیں کی؛ میں ان میں سے پایا گیا ہوں جنہوں نے مجھے تلاش نہیں کیا: میں نے کہا، دیکھو مجھے، دیکھو مجھے، ایک ایسی قوم کو {جو} کو میرے نام سے نہیں پکارا گیا۔\n2. میں نے سارا دن اپنے ہاتھ ایک باغی قوم کے لیے پھیلائے ہیں، جو اپنے خیالات کے پیچھے ایک ناجائز طریقے سے چلتی ہیں؛\n3۔ ایک قوم جو مجھے مسلسل میرے سامنے غصہ دلاتی ہے؛ جو باغات میں قربانی دیتا ہے، اور اینٹوں کے قربان گاہوں پر لوبان جلاتے ہیں؛ {اوپر...: عبرانی اینٹوں پر}\n4۔ جو قبروں کے درمیان باقی ہیں، اور یادگاروں میں ٹھہرے ہوئے ہیں، جو سور کا گوشت کھاتے ہیں، اور ان کے برتنوں میں مکروہ چیزیں کھاتی ہیں؛ {یخنی: یا، ٹکڑے}\n5۔ جو کہتے ہیں، اپنے آپ کو سنبھالو، میرے قریب مت آؤ؛ کیونکہ میں تم سے زیادہ مقدس ہوں۔ یہ میرے ناک میں دھواں ہیں، ایک آگ جو سارا دن جلتی رہتی ہے۔ {ناک: یا، غصہ}\n6۔ دیکھو، {یہ} میرے سامنے لکھا ہے: میں خاموش نہیں رہوں گا، بلکہ ان کے سینے میں بدلہ دوں گا،\n7۔ آپ کے گناہوں اور آپ کے آباؤ اجداد کی گناہوں کے ساتھ، خداوند فرماتا ہے، جس نے پہاڑوں پر لوبان جلایا اور پہاڑوں پر مجھے کفر کیا: اس لیے میں ان کے سابقہ کام کو ان کے سینے میں ناپوں گا۔\n8۔ خداوند یوں فرماتا ہے، جیسے نئی شراب جھرمٹ میں پائی جاتی ہے، اور {ایک} فرماتا ہے: اسے تباہ نہ کرو؛ کیونکہ اس میں ایک برکت ہے: میں اپنے خادموں کے لیے ایسا ہی کروں گا، تاکہ میں سب کو تباہ نہ کر سکوں۔\n9۔ اور میں یعقوب سے ایک نسل پیدا کروں گا، اور یہوداہ سے میرے پہاڑوں کا وارث ہوگا، اور میرے منتخب لوگ اس کے وارث ہوں گے، اور میرے خادم وہاں رہیں گے۔\n10۔ اور شارون ریوڑوں کا ایک جھنڈ ہوگا، اور آخور کی وادی میرے لوگوں کے لیے جو مجھے تلاش کر رہے ہیں، ریوڑوں کے لیے آرام کرنے کی جگہ ہوگی۔\n11. لیکن تم وہ لوگ ہو جو خداوند کو چھوڑ دیتے ہو، جو میرے مقدس پہاڑ کو بھول جاتے ہو، جو اس فوج کے لیے میز تیار کرتے ہو، اور اس تعداد کو شراب کی قربانی دیتے ہو۔ {ٹروپ: یا، گاڈ} {نمبر: یا، مینی، ایک کافر خدا}\n12۔ اسی لیے میں تمہیں تلوار کے سامنے گنوں گا، اور تم سب ذبح کے سامنے جھک جاؤ گے: کیونکہ جب میں نے پکارا تو تم نے جواب نہیں دیا؛ جب میں نے بات کی، تم نے نہیں سنا؛ لیکن اس نے میری آنکھوں کے سامنے برائی کی، اور {یہ} چنا جس میں مجھے خوشی نہیں ہوئی۔\n13۔ اسی لیے خداوند خدا فرماتا ہے، دیکھو، میرے بندے کھائیں گے، لیکن تم بھوکے رہو گے: دیکھو، میرے بندے پیئیں گے، لیکن تم پیاسے ہو گے: دیکھو، میرے بندے خوش ہوں گے، لیکن تم شرمندہ ہو گے:\n14۔ دیکھو، میرے خادم دل کی خوشی کے لیے گائیں گے، لیکن تم دل کے غم کے لیے پکارو گے، اور روح کی پریشانی کے لیے چیخ اٹھو گے۔ {ناراضگی کے ساتھ: عبرانی بریکنگ}\n15۔ اور تم اپنا نام میرے منتخب کردہ پر لعنت چھوڑو گے: کیونکہ خداوند خدا تمہیں مار ڈالے گا، اور اپنے بندوں کو کسی اور نام سے پکارے گا:\n16۔ جو زمین پر خود کو برکت دیتا ہے وہ سچائی کے خدا میں خود کو برکت دے؛ اور جو زمین پر قسم کھائے گا وہ سچائی کے خدا کی قسم کھائے گا؛ کیونکہ پہلے کے مسائل بھلا دیے گئے ہیں، اور وہ میری آنکھوں سے چھپے ہوئے ہیں۔\n17. کیونکہ دیکھو، میں نئے آسمان اور نئی زمین تخلیق کرتا ہوں: اور پہلے کو نہ یاد رکھا جائے گا، نہ ذہن میں آئے گا۔ {آؤ...: عبرانی۔ دل پر آؤ}\n18۔ لیکن ہمیشہ کے لیے خوش رہو اور خوش رہو {اس میں} جو میں تخلیق کرتا ہوں: کیونکہ دیکھو، میں یروشلم کو خوشی اور اس کے لوگوں کو خوشی بناتا ہوں۔\n19۔ اور میں یروشلم میں خوش ہوں گا، اور اپنی قوم میں خوشی مناؤں گا: اور اس میں رونے کی آواز نہ سنی جائے گی، نہ رونے کی آواز۔\n20۔ اس کے بعد کوئی دن کا بچہ نہیں ہوگا، نہ کوئی بوڑھا آدمی جو اپنی عمر پوری نہ کرے: کیونکہ بچہ سو سال کی عمر میں مر جائے گا؛ لیکن جو گناہگار سو سال کا ہو، وہ ہوگا۔\n21۔ اور وہ گھر بنائیں گے، اور ان میں رہیں گے؛ اور وہ انگور کے باغ لگائیں گے، اور ان کے پھل کھائیں گے۔\n22۔ وہ تعمیر نہیں کریں گے، اور کوئی اور آباد ہو جائے گا؛ وہ نہیں لگائیں گے، اور دوسرا کھائیں گے: کیونکہ جیسے درخت کے دن میرے لوگوں کے دن ہیں، اور میرے منتخب لوگ طویل عرصے تک اپنے ہاتھوں کے کام سے لطف اندوز ہوں گے۔ {لمبا...: عبرانی۔ انہیں طویل عرصے تک جاری رکھے گا، یا پھر ختم ہو جائے گا}\n23۔ وہ فضول محنت نہیں کریں گے، نہ ہی مصیبت پیدا کریں گے؛ کیونکہ وہ خداوند کے بابرکت لوگوں کی نسل ہیں، اور ان کی اولاد ان کے ساتھ۔\n24۔ اور ایسا ہوگا کہ ان کے پکارنے سے پہلے میں جواب دوں گا؛ اور جب تک وہ بول رہے ہیں، میں سنوں گا۔\n25۔ بھیڑیا اور بھیڑ مل کر کھائیں گے، اور شیر بیل کی طرح بھوسہ کھائے گا: اور دھول سانپ کے گوشت کی طرح ہوگی۔ وہ میرے مقدس پہاڑ میں نہ نقصان پہنچائیں گے نہ تباہی کریں گے، خداوند فرماتا ہے۔","1. خداوند یوں فرماتا ہے، آسمان میرا تخت ہے، اور زمین میرا سہارا ہے: وہ گھر کہاں ہے جو تم میرے لیے بناتے ہو؟ اور میری آرام گاہ کہاں ہے؟\n2۔ کیونکہ وہ سب {چیزیں} جو میرے ہاتھ سے بنائی گئی ہیں، اور وہ سب {چیزیں} رہی ہیں، خداوند فرماتا ہے: لیکن میں اس {انسان} کی طرف دیکھوں گا، {حتیٰ کہ} اس {کو} جو غریب اور توبہ کرنے والا روح رکھتا ہے، اور اپنے کلام پر کانپوں گا۔\n3۔ جو بیل مارتا ہے {گویا کہ} نے انسان کو مارا ہو؛ جو بکری قربان کرتا ہے، {گویا کتے کی گردن کاٹ دیتا ہو؛ جو قربانی پیش کرتا ہے، {جیسے اس نے سور کا خون پیش کیا ہو}؛ جو خوشبو جلاتی ہے، {گوئی} اس نے بت کو برکت دی ہو۔ ہاں، انہوں نے اپنے طریقے خود چنے ہیں، اور ان کی روح اپنی مکروہ حرکتوں میں خوش ہے۔ {لیمب: یا، بچے} {برنتھ: عبرانی۔ ایک یادگار بناتا ہے}\n4۔ میں ان کے وہم کا انتخاب بھی کروں گا، اور ان کے خوف ان پر لاؤں گا؛ کیونکہ جب میں نے کال کی، کوئی جواب نہیں دیا؛ جب میں نے بات کی، تو انہوں نے نہیں سنا: لیکن انہوں نے میری آنکھوں کے سامنے برا کیا، اور {وہ} کو چنا جس میں مجھے خوشی نہیں تھی۔ {وہم یا، چالیں}\n5. خداوند کا کلام سنو، جو اس کے کلام پر کانپتے ہیں؛ تمہارے وہ بھائی جو تم سے نفرت کرتے تھے، جنہوں نے میرے نام کے لیے تمہیں نکال دیا، انہوں نے کہا، خداوند جلال پائے: لیکن وہ تمہاری خوشی میں ظاہر ہوگا، اور وہ شرمندہ ہوں گے۔\n6۔ شہر سے شور کی آواز، مندر سے آواز، خداوند کی آواز جو اپنے دشمنوں کو بدلہ دیتی ہے۔\n7۔ اس سے پہلے کہ وہ تکلیف اٹھاتی، اس نے نکالا؛ درد آنے سے پہلے، وہ ایک مرد بچے کی پیدائش کر چکی تھی۔\n8۔ ایسا کس نے سنا ہے؟ ایسی چیزیں کس نے دیکھی ہیں؟ کیا زمین ایک دن میں پیدا ہو جائے گی؟ {یا} کیا ایک قوم فورا پیدا ہوگی؟ کیونکہ جیسے ہی صیون نے تکلیف دی، اس نے اپنے بچے پیدا کیے۔\n9۔ کیا میں پیدائش تک لے آؤں، اور اولاد کی وجہ نہ دوں؟ خداوند فرماتا ہے: کیا میں پیدائش کروں اور رحم کو بند کر دوں؟ تیرے خدا نے فرمایا۔ {نہیں...: یا، پیدا نہیں ہونا؟}\n10۔ یروشلم کے ساتھ خوش رہو، اور اس کے ساتھ خوش رہو، جو اس سے محبت کرتے ہیں: اس کے ساتھ خوشی مناؤ، جو اس کے لیے ماتم کرتے ہیں:\n11۔ تاکہ تم اس کی تسلی کے سینے چوسنے اور مطمئن ہو؛ تاکہ تم دودھ نکالو، اور اس کی عظمت کی فراوانی سے خوش رہو۔ {فراوانی: یا، روشنی}\n12۔ کیونکہ خداوند یہ فرماتا ہے، دیکھو، میں اسے دریا کی طرح امن عطا کروں گا، اور غیر قوموں کی شان بہتے ہوئے ندی کی طرح: پھر تم چوسو گے، تم اس کے کناروں پر اٹھائے جاؤ گے، اور {اس کے} گھٹنوں کے بل جھکاؤ گے۔\n13۔ جس طرح اس کی ماں اسے تسلی دیتی ہے، میں بھی تمہیں تسلی دوں گا؛ اور تم یروشلم میں تسلی پاؤ گے۔\n14۔ اور جب تم یہ دیکھو گے، تمہارا دل خوش ہوگا، اور تمہاری ہڈیاں جڑی بوٹی کی طرح پھلیں گے: اور خداوند کا ہاتھ اپنے بندوں کے لیے پہچانا جائے گا، اور اس کا غصہ اپنے دشمنوں کے لیے ہوگا۔\n15۔ کیونکہ دیکھو، خداوند آگ لے کر آئے گا، اور اپنے رتھ لے کر طوفان کی طرح آ جائے گا، تاکہ اس کا غصہ غصے سے اور اپنی ملامت آگ کی آگ سے کرے گا۔\n16۔ کیونکہ آگ اور اپنی تلوار سے خداوند تمام جسم سے دعا کرے گا: اور خداوند کے مارے جانے والے بہت سے ہوں گے۔\n17. جو لوگ خود کو پاک کرتے ہیں، اور ایک درخت کے پیچھے باغات میں خود کو پاک کرتے ہیں، سور کا گوشت کھاتے ہیں، اور مکروہ اور چوہا دونوں مل کر کھا جائیں گے، خداوند فرماتا ہے۔ {پیچھے...: یا، ایک کے بعد ایک}\n18۔ کیونکہ میں ان کے اعمال اور ان کے خیالات کو {جانتا ہوں}: یہ آئے گا، کہ میں تمام قوموں اور زبانوں کو جمع کروں گا؛ اور وہ آئیں گے، اور میری شان دیکھیں گے۔\n19۔ اور میں ان کے درمیان ایک نشان قائم کروں گا، اور جو لوگ ان میں سے بچ نکلیں گے ان قوموں کے پاس بھیجوں گا، {ترشش، پل، اور لود' کے پاس، جو کمان کھینچتے ہیں، {توبال، اور جاوان} کے لیے، {دور دراز جزائر پر}، جنہوں نے میری شہرت نہیں سنی، نہ ہی میری شان دیکھی؛ اور وہ غیر قوموں میں میری شان کا اعلان کریں گے۔\n20۔ اور وہ تمہارے تمام بھائیوں کو سب قوموں میں سے خداوند کے لیے نذرانہ لائیں گے، گھوڑوں، رتھوں پر، لکڑوں میں، خچروں پر، اور تیز جانوروں پر، میرے مقدس پہاڑ یروشلم پر، خداوند فرماتا ہے، جیسے بنی اسرائیل پاک برتن میں خدا کے گھر میں نذرانہ لاتے ہیں۔ {لٹرز: یا، کوچز}\n21۔ اور میں ان میں سے بھی کاہنوں کے طور پر لے جاؤں گا {اور} لاویوں کے لیے، خداوند فرماتا ہے۔\n22۔ جیسے نئے آسمان اور نئی زمین، جنہیں میں بناؤں گا، میرے سامنے رہیں گے، خداوند فرماتا ہے، ویسے ہی تیری نسل اور تمہارا نام باقی رہیں گے۔\n23. اور یہ ہو جائے گا، {کہ} ایک نئے چاند سے دوسرے چاند تک، اور ایک سبت سے دوسرے سبت تک، تمام جسم میرے سامنے عبادت کے لیے آئیں گے، خداوند فرماتا ہے۔ {ایک نئے...: عبرانی سے۔ نئے چاند سے اس کے نئے چاند تک، اور سبت سے اس کے سبت تک}\n24۔ اور وہ باہر نکلیں گے، اور ان لوگوں کی لاشوں کو دیکھیں گے جنہوں نے میرے خلاف زیادتی کی ہے: کیونکہ ان کا کیڑا نہیں مرے گا، نہ ان کی آگ بجھے گی؛ اور وہ ہر جسم کے لیے نفرت انگیز ہوں گے۔"];
